window.__Q=window.__Q||{};window.__Q["tcm/3/A1"]=[{"q":"既清实热，又清虚热的药物是","o":["决明子","栀子","石膏","知母","寒水石"],"a":3,"e":"知母苦甘寒，既能清泻肺胃实热，又能滋阴降火而退虚热，故实热与虚热皆可用；石膏、寒水石只清实热而无滋阴退蒸之力。"},{"q":"下列除哪项外，均为龟甲的功效","o":["滋阴潜阳","益肾强骨","养血补心","固经止崩","软坚散结"],"a":4,"e":"龟甲功能滋阴潜阳、益肾强骨、养血补心、固经止崩，为甲壳类滋阴药；软坚散结为鳖甲所专，龟甲无此功用。"},{"q":"蝉蜕配胖大海除清肺外，又能","o":["通鼻窍","止咳平喘","凉血止血","清利头目","利咽开音"],"a":4,"e":"蝉蜕甘寒质轻，能疏散风热、利咽开音；胖大海亦清肺利咽开音，二药相配善治风热或肺热所致声音嘶哑、咽喉肿痛。"},{"q":"香附的功效为","o":["理气调经","理气健脾","理气散寒","理气杀虫","理气燥湿"],"a":0,"e":"香附辛微苦微甘平，主入肝经，功能疏肝解郁、理气宽中、调经止痛，为妇科理气调经之要药，故称气病之总司、女科之主帅。"},{"q":"既能平抑肝阳，又能疏肝解郁，祛风明目、止痒的药是","o":["柴胡","薄荷","蒺藜","白僵蚕","石决明"],"a":2,"e":"蒺藜苦辛微温，入肝经，既能平抑肝阳，又能疏肝解郁，兼可祛风明目、止痒，故肝阳上亢兼肝郁之目赤瘙痒者最为适宜。"},{"q":"入汤剂需后下的药物是","o":["磁石、牡蛎","蒲黄、海金沙","薄荷、白豆蔻","人参、鹿茸","芒硝、阿胶"],"a":2,"e":"薄荷、白豆蔻均含挥发油，久煎则香气散失、药力大减，故入汤剂须后下；磁石牡蛎当先煎，蒲黄海金沙当包煎，阿胶当烊化。"},{"q":"有清热凉血、活血化瘀之功，常用治肠痈的药物是","o":["玄参","金银花","牡丹皮","生地黄","姜黄"],"a":2,"e":"牡丹皮苦辛微寒，清热凉血之中兼能活血化瘀、散瘀消痈，故肠痈初起用之最宜，为大肠牡丹汤的主药之一。"},{"q":"下列功效中，属于对症治疗的是","o":["止血","安神","开窍","助阳","泻下"],"a":0,"e":"对症治疗又称治标，是直接针对症状用药，止血即为止血这一症状，故属对症治疗；安神、开窍、助阳、泻下均针对病机，属对因治疗。"},{"q":"不属于阿胶功效的是","o":["补血","滋阴","清肝","润肺","止血"],"a":2,"e":"阿胶甘平，功能补血、滋阴、润肺、止血，为血肉有情之品；清肝非其所具，清肝多属羚羊角、夏枯草、决明子之类。"},{"q":"均归心经的补阴药是","o":["麦冬、百合、龟甲","石斛、天冬、百合","龟甲、黄精、鳖甲","北沙参、玉竹、桑椹","枸杞子、女贞子、墨旱莲"],"a":0,"e":"麦冬归心肺胃经、百合归心肺经、龟甲归肝肾心经，三者均入心经；石斛、黄精、玉竹、枸杞子等补阴药则不归心经。"},{"q":"解鱼蟹中毒最宜用的药物是","o":["葛根，菊花","紫苏叶，生姜","生姜，葛根","生姜，白芷","紫苏叶，半夏"],"a":1,"e":"紫苏叶辛温，能解鱼蟹毒；生姜亦解鱼蟹毒并能和胃止呕，二药同用最宜，故食鱼蟹中毒而腹痛吐泻者常用。"},{"q":"砒石内服用治冷哮的每次用量是","o":["0、001～0、002g","0、002～0、004g","0、04～0、06g","0、06～0、1g","0、1～0、2g"],"a":1,"e":"砒石辛大热，有大毒，内服入丸散，每次0.002～0.004g，不可过量久服；其劫痰平喘，善治寒痰久喘之冷哮。"},{"q":"桑叶与菊花均具有的功效是","o":["疏肝解郁","利咽开音","清肺润燥","清热解毒","清肝明目"],"a":4,"e":"桑叶、菊花均甘苦微寒，入肺肝经，同能疏散风热、清肝明目，故风热目赤或肝阳上亢之头晕目暗者相须为用。"},{"q":"芦根、栀子、淡竹叶均具有的功效是","o":["止咳","止血","解毒","利尿","生津"],"a":3,"e":"芦根、栀子、淡竹叶均能清热利尿，使湿热从小便而去，故湿热淋证、小便短赤者均可选用。"},{"q":"下列除哪项外均为苦味药的作用","o":["清热泻火","泄降逆气","收敛固涩","通泻大便","燥湿坚阴"],"a":2,"e":"苦能泄、能燥、能坚，故苦味药有清热泻火、降泄逆气、通泻大便、燥湿坚阴之功；收敛固涩为酸味与涩味药的作用。"},{"q":"药性辛、热，有毒，并具有补肾阳、强筋骨、祛寒湿功效的药物是","o":["续断","杜仲","仙茅","巴戟天","淫羊藿"],"a":2,"e":"仙茅辛热有毒，功能补肾阳、强筋骨、祛寒湿，为温肾壮阳之峻品；续断、杜仲、巴戟天、淫羊藿均无毒。"},{"q":"能温中散寒，行气止痛的药物是","o":["丁香","草果","厚朴","吴茱萸","荜澄茄"],"a":4,"e":"荜澄茄辛温，功能温中散寒、行气止痛，善治胃寒脘腹冷痛、呕吐呃逆；吴茱萸长于散寒止痛、降逆止呕，不作行气止痛之主药。"},{"q":"治带下病，宜选用","o":["百部","白果","款冬花","桑白皮","马兜铃"],"a":1,"e":"白果甘苦涩平，功能敛肺定喘、止带缩尿，善治带下白浊，故湿浊或虚寒带下病多用之，常与山药、芡实相配。"},{"q":"补骨脂、蛤蚧的相同功效是","o":["纳气平喘","消风祛斑","益气养血","温经止血","固肾安胎"],"a":0,"e":"补骨脂补肾壮阳、固精缩尿、温脾止泻、纳气平喘；蛤蚧补肺益肾、纳气定喘、助阳益精，纳气平喘为二者共有之功。"},{"q":"牛膝配伍石膏、知母主要用于","o":["月经不调、痛经闭经","肝肾亏虚之筋骨无力","风寒湿痹之手足麻木","胃火上炎之口舌生疮","血热妄行之吐血、衄血"],"a":3,"e":"牛膝苦甘酸平，功善引血下行，与石膏、知母相配清泻胃火，即玉女煎之意，用于胃火上炎之口舌生疮、牙龈肿痛。"},{"q":"生姜能减轻或清除半夏的毒性，这种配伍关系称为","o":["相须","相使","相恶","相反","相杀"],"a":4,"e":"生姜能减轻或消除半夏的毒副作用，此种配伍关系称为相杀；若言半夏被生姜所制则称相畏，二者为同一关系的两个角度。"},{"q":"既能祛风解表，又能止痉，用治破伤风的药物是","o":["荆芥","防风","独活","紫苏叶","羌活"],"a":1,"e":"防风辛甘微温，祛风解表之中兼能止痉，故破伤风之角弓反张、牙关紧闭者用之，如玉真散以之为君。"},{"q":"归肝经的药物不包括","o":["夏枯草","密蒙花","青葙子","决明子","鸭跖草"],"a":4,"e":"夏枯草、密蒙花、青葙子、决明子均入肝经而能清肝明目；鸭跖草归肺、胃、膀胱经，功能清热泻火、解毒利水。"},{"q":"既能平肝潜阳，又能清肝明目的药物是","o":["柴胡","磁石","牡蛎","赭石","石决明"],"a":4,"e":"石决明咸寒，专入肝经，既能平抑肝阳，又能清肝明目，为肝阳上亢之头痛眩晕、目赤翳障之要药，入汤剂须先煎。"},{"q":"平性药的含义是指","o":["寒、热之性不甚明显的药物","作用比较缓和的药物","升浮、沉降作用趋向不明显的药物","性味甘淡的药物","寒热之性均具备的药物"],"a":0,"e":"平性药指寒热之性不甚明显、作用平和、寒热证均可配伍应用者，并非作用缓和或升降趋向不明之谓。"},{"q":"治寒疝腹痛，首选","o":["干姜","花椒","丁香","高良姜","小茴香"],"a":4,"e":"小茴香辛温，入肝肾脾胃经，功能散寒止痛、理气和胃，为治寒疝腹痛、睾丸偏坠之要药。"},{"q":"功能温经止血，为妇科常用药的是","o":["小蓟","艾叶","三七","茜草","地榆"],"a":1,"e":"艾叶辛苦温，能温经止血、散寒止痛，炒炭后止血之力更著，为下焦虚寒出血及宫冷不孕等妇科病之常用药。"},{"q":"关于药物的基本作用，说法错误的是","o":["祛邪去因","扶正固本","注重配伍","协调脏腑功能","纠正阴阳盛衰"],"a":2,"e":"药物的基本作用为祛邪去因、扶正固本、协调脏腑功能、纠正阴阳盛衰；注重配伍属药物应用原则，不属基本作用。"},{"q":"关于副作用说法错误的是","o":["是指药物用量过多时产生的不适反应","一般较轻微","停药后可消失","与治疗需求无关","对机体危害不大"],"a":0,"e":"副作用是常用剂量下与治疗目的无关的不适反应，一般轻微、停药可消失；用量过大所致的机体损伤称为毒性反应。"},{"q":"为治寒滞肝经诸痛之主药，用于寒滞肝经之寒疝腹痛，厥阴头痛，寒凝痛经及寒湿脚气肿痛等证的药物是","o":["草果","豆蔻","乌药","木瓜","吴茱萸"],"a":4,"e":"吴茱萸辛苦热，主入肝经，善散寒止痛、疏肝下气，为治寒滞肝经之寒疝腹痛、厥阴头痛、寒凝痛经及寒湿脚气肿痛之主药。"},{"q":"首创按药物自然属性分类的本草著作是","o":["《神农本草经》","《本草纲目拾遗》","《证类本草》","《本草经集注》","《新修本草》"],"a":3,"e":"《本草经集注》为陶弘景所撰，载药730种，首创按药物自然属性分类；《神农本草经》则按上中下三品分类。"},{"q":"能补火助阳，散寒止痛，温通经脉，引火归元的药物是","o":["桂枝","葛根","肉桂","胡椒","升麻"],"a":2,"e":"肉桂辛甘大热，功能补火助阳、散寒止痛、温通经脉、引火归元，为治命门火衰、虚阳上浮之要药。"},{"q":"狗脊的功效是","o":["祛风湿，壮筋骨，通经络","祛风湿，强筋骨，补肾阳","祛风湿，强筋骨，安胎元","祛风湿，强筋骨，利水","祛风湿，补肝肾，强腰膝"],"a":4,"e":"狗脊苦甘温，入肝肾经，功能祛风湿、补肝肾、强腰膝，善治肝肾不足之腰脊强痛、俯仰不利。"},{"q":"素有“夏月麻黄”之称的药物是","o":["白芷","香薷","羌活","桂枝","防风"],"a":1,"e":"香薷辛微温，功能发汗解表、化湿和中、利水消肿，夏令外感风寒兼内伤湿滞者用之最宜，故有夏月麻黄之称。"},{"q":"竹茹的功效是","o":["止咳化痰，降逆和胃","化痰行水，降逆止呕","清热化痰，除烦止呕","燥湿化痰，降逆止呕","温肺止咳，和胃止呕"],"a":2,"e":"竹茹甘微寒，入肺胃经，功能清热化痰、除烦止呕，善治痰热咳嗽、胃热呕吐及痰火内扰之心烦不寐。"},{"q":"既能凉血止血，又能活血通经的药物是","o":["大蓟","白及","茜草","血余炭","苎麻根"],"a":2,"e":"茜草苦寒，入肝经，功能凉血止血、活血通经，止血而不留瘀，故血热夹瘀之出血及经闭不行者常用。"},{"q":"肠中蕴热，致便血、痔血，首选","o":["小蓟","大蓟","槐花","茜草","苎麻根"],"a":2,"e":"槐花苦微寒，入肝与大肠经，善清泄肠热、凉血止血，故肠中蕴热之便血、痔血首选，常与地榆相须为用。"},{"q":"下列除哪项以外均是乌药的主治病证","o":["遗尿","痛经","寒疝腹痛","寒凝腹胀","寒湿痹痛"],"a":4,"e":"乌药辛温，功能行气止痛、温肾散寒，主治寒凝气滞之胸腹胀痛、寒疝腹痛、痛经及遗尿尿频；寒湿痹痛非其所长。"},{"q":"桑白皮与葶苈子均有的功效是","o":["泻肺平喘，化瘀消瘿","清热化痰，息风止痉","泻肺平喘，利水消肿","软坚散结，利尿通淋","清肺化痰，清肠疗痔"],"a":2,"e":"桑白皮甘寒、葶苈子辛苦大寒，二者均能泻肺平喘、利水消肿，用治肺热或痰壅之喘咳及水肿小便不利。"},{"q":"大青叶的功效是","o":["凉血止血","凉血消班","凉血止痢","凉血活血","凉血安神"],"a":1,"e":"大青叶苦大寒，功能清热解毒、凉血消斑，善治温毒发斑、丹毒、痄腮、喉痹，凉血消斑之力为清热解毒药中突出者。"},{"q":"砒石内服功效是","o":["通便","劫痰平喘","温肾壮阳","杀虫止痛","祛风燥湿"],"a":1,"e":"砒石辛大热，有大毒，内服劫痰平喘，专治寒痰久喘之冷哮，入丸散用，每次0.002～0.004g，不可久服。"},{"q":"具化浊降脂作用，可治高脂血症的药物是","o":["茯苓","泽泻","猪苓","香加皮","冬瓜皮"],"a":1,"e":"泽泻甘淡寒，入肾与膀胱经，功能利水渗湿、泄热，兼能化浊降脂，故高脂血症、痰浊眩晕者多用之。"},{"q":"能利水消肿，治水肿、脚气肿痛的药物是","o":["青皮","陈皮","苦楝皮","合欢皮","大腹皮"],"a":4,"e":"大腹皮辛微温，功能行气宽中、行水消肿，善治湿阻气滞之脘腹胀满、水肿胀满及脚气肿痛。"},{"q":"细辛的功效不包括","o":["祛风散寒","通窍","止痛","温中止呕","温肺化饮"],"a":3,"e":"细辛辛温，功能祛风散寒、通窍、止痛、温肺化饮；温中止呕为生姜、干姜、高良姜之类所主，细辛并无此功。"},{"q":"凉血不留瘀，活血不动血，又能退无汗骨蒸的药物是","o":["赤芍","白薇","生地黄","牡丹皮","郁金"],"a":3,"e":"牡丹皮苦辛微寒，凉血而不留瘀、活血而不动血，兼退虚热，善治温病后期之夜热早凉及无汗骨蒸。"},{"q":"血热所致的脱发，宜选用的药物是","o":["槐花","蒲黄","白及","侧柏叶","白茅根"],"a":3,"e":"侧柏叶苦涩微寒，功能凉血止血、生发乌发，故血热所致脱发、须发早白者宜用，常与何首乌、生地相配。"},{"q":"均可治疗湿热证的药组是","o":["黄芩、金银花","黄连、野菊花","黄柏、大血藤","黄芩、穿心莲","龙胆、败酱草"],"a":3,"e":"黄芩、穿心莲均能清热燥湿、泻火解毒，同可治湿热泻痢、湿温及湿热黄疸；金银花、野菊花偏于清热解毒而无燥湿之力。"},{"q":"薤白的功效除行气导滞外，还有以下哪项","o":["燥湿化痰","疏肝解郁","通阳散结","清热解毒","温肾助阳"],"a":2,"e":"薤白辛苦温，功能通阳散结、行气导滞，善治胸阳不振、痰浊痹阻之胸痹心痛及脘腹痞满胀痛。"},{"q":"下列药物的用法错误的是","o":["牡蛎入汤剂宜先煎","钩藤入汤剂不宜久煎","雷丸入汤剂宜先煎","砂仁入汤剂宜后下","附子入汤剂宜先煎"],"a":2,"e":"雷丸所含蛋白酶为有效成分，受热即破坏，故不入煎剂而宜入丸散；牡蛎、附子宜先煎，钩藤不宜久煎，砂仁宜后下。"},{"q":"具有清热凉血，养阴生津作用的药物是","o":["生地黄","紫草","水牛角","牡丹皮","赤芍"],"a":0,"e":"生地黄甘寒质润，入心肝肾经，功能清热凉血、养阴生津，为热入营血之斑疹吐衄及阴虚津伤口渴之要药。"},{"q":"为肺胃气逆之要药的是","o":["芥子","桔梗","旋覆花","川贝母","黄药子"],"a":2,"e":"旋覆花苦辛咸微温，善降肺胃之气，功能降气化痰、降逆止呕，为肺胃气逆咳喘呕恶之要药，入汤剂须包煎。"},{"q":"蝉蜕煎服时的用量是","o":["0、05～0、1g","3～6g","15～60g","0、002～0、004g","0、3～0、6g"],"a":1,"e":"蝉蜕质轻力薄，煎服用量3～6g，不宜过量；研末冲服每次1～2g，其性甘寒，表虚多汗者当慎用。"},{"q":"治气虚下陷，脱肛，子宫脱垂，崩漏下血的药物是","o":["菊花","淡豆豉","升麻","薄荷","蝉蜕"],"a":2,"e":"升麻辛微甘微寒，能发表透疹、清热解毒、升举阳气，故中气下陷之脱肛、子宫脱垂及崩漏下血用之，为补中益气汤要药。"},{"q":"南沙参具有而北沙参不具有的功效是","o":["化痰","生津","养胃阴","清肺热","补肺阴"],"a":0,"e":"南沙参甘微寒，功能养阴清肺、益胃生津、化痰益气；北沙参养阴清肺、益胃生津而无化痰之功，此为二者主要区别。"},{"q":"归经含义是指","o":["药物具有的升、降、浮、沉的作用趋向","药物具有的寒、热、温、凉四种性质","药物具有的辛、甘、酸、苦、咸五种滋味","药物对于机体某部分的选择性作用","药物对于机体有无毒副作用"],"a":3,"e":"归经指药物对机体某一部分的选择性作用，即药效所在部位，与四气、五味、升降浮沉共同构成药性理论。"},{"q":"土鳖虫的药性是","o":["辛，平","辛、苦，温","甘、咸，平","咸，寒；有小毒","苦，温；有大毒"],"a":3,"e":"土鳖虫咸寒，有小毒，功能破血逐瘀、续筋接骨，为跌打骨折筋伤及血瘀经闭、癥瘕痞块之常用药。"},{"q":"性平的补阴药是","o":["麦冬","枸杞子","北沙参","墨旱莲","明党参"],"a":1,"e":"枸杞子甘平，入肝肾经，功能滋补肝肾、益精明目，为补阴药中性平而不偏寒热者；墨旱莲甘酸寒，麦冬、北沙参偏微寒。"},{"q":"豆蔻与肉豆蔻均具有的功效是","o":["芳香化湿","涩肠止泻","理气安胎","疏肝理气","温中行气"],"a":4,"e":"豆蔻化湿行气、温中止呕，肉豆蔻温中行气、涩肠止泻，温中行气为二者共有之功，虚寒气滞之脘腹胀满者均可用。"},{"q":"下列除哪项外，均为龙骨的主治病症","o":["心神不宁","目暗不明","肝阳眩晕","滑脱不禁","疮疡不敛"],"a":1,"e":"龙骨甘涩平，功能镇惊安神、平肝潜阳、收敛固涩、收湿敛疮，主治心神不宁、肝阳眩晕、滑脱不禁及疮疡不敛；目暗不明非其所治。"},{"q":"既平肝又疏肝的药物是","o":["香附","柴胡","赭石","蒺藜","罗布麻"],"a":3,"e":"蒺藜入肝经，既能平抑肝阳，又能疏肝解郁，肝阳上亢兼肝气郁结者最宜；香附、柴胡无平肝之功，赭石、罗布麻无疏肝之力。"},{"q":"治疗肝肾亏虚，两目干涩，视物昏花，宜首选","o":["龟甲","黄精","鳖甲","枸杞子","墨旱莲"],"a":3,"e":"枸杞子甘平质润，入肝肾经，功能滋补肝肾、益精明目，故肝肾亏虚之两目干涩、视物昏花者首选。"},{"q":"驱虫药服用的适宜时间是","o":["饭前","饭后","空腹","睡前","随时"],"a":2,"e":"驱虫药宜空腹服用，此时胃肠空虚，药力能直接作用于虫体，疗效最佳；服药期间忌食油腻，以便药物吸收并观察排虫。"},{"q":"较之大黄，虎杖所独有的功效是","o":["止咳化痰","利胆退黄","清热解毒","活血化瘀","凉血止血"],"a":0,"e":"虎杖苦微寒，功能利湿退黄、清热解毒、散瘀止痛、止咳化痰、泻热通便；其中止咳化痰为大黄所不具。"},{"q":"辛味药临床一般治疗","o":["大便燥结","表证及气滞血瘀证","呕吐呃逆","瘿瘤瘰疬","久泻久痢"],"a":1,"e":"辛能散、能行，故辛味药多具发散表邪、行气行血之功，临床用于外感表证及气滞血瘀诸证，如麻黄、川芎。"},{"q":"治肝肾阴虚，腰膝酸软，潮热骨蒸，盗汗，遗精，消渴等，首选","o":["山药","地骨皮","白芍","黄精","熟地黄"],"a":4,"e":"熟地黄甘微温，入肝肾经，功能补血滋阴、益精填髓，为治肝肾阴虚、腰膝酸软、潮热盗汗、遗精消渴之要药。"},{"q":"栀子用治热淋涩痛，因其能","o":["泻火除烦","清热利湿","凉血解毒","消肿止痛","凉血止血"],"a":1,"e":"栀子苦寒，功能泻火除烦、清热利湿、凉血解毒，其清热利湿之力使湿热从小便而去，故治热淋涩痛与湿热黄疸。"},{"q":"既能疏肝破气，又能消积化滞的药物是","o":["陈皮","青皮","枳实","木香","香附"],"a":1,"e":"青皮苦辛温，入肝胆胃经，功能疏肝破气、消积化滞，善治肝郁气滞之胸胁胀痛及食积气滞之脘腹痞满。"},{"q":"白前与前胡均具有的功效是","o":["疏散风热","清热解毒","利水消肿","利咽开音","降气祛痰"],"a":4,"e":"白前辛苦微温、前胡苦辛微寒，二者均能降气祛痰，治肺气壅实之咳嗽痰多；前胡兼散风热，白前专于降气。"},{"q":"能回阳通脉，温中散寒，温肺化饮的药物是","o":["丁香","肉桂","干姜","小茴香","高良姜"],"a":2,"e":"干姜辛热，主入脾胃，功能温中散寒、回阳通脉、温肺化饮，为脾胃寒证及寒饮咳喘之要药，常配附子回阳救逆。"},{"q":"不具有利水消肿功效的药物是","o":["桑白皮","合欢皮","大腹皮","五加皮","茯苓皮"],"a":1,"e":"合欢皮甘平，功能解郁安神、活血消肿，并无利水消肿之功；桑白皮、大腹皮、五加皮、茯苓皮均能利水消肿。"},{"q":"能敛肺平喘，止带缩尿的药物是","o":["白果","枇杷叶","葶苈子","马兜铃","桑白皮"],"a":0,"e":"白果甘苦涩平，功能敛肺定喘、止带缩尿，故咳喘日久痰多及带下白浊、小便频数者用之，兼能收敛除湿。"},{"q":"远志的使用方法及注意点不包括","o":["用量不宜过大","胃溃疡者慎用","痰火内盛者慎用","化痰止咳多蜜炙用","痈疽疮毒患者慎用"],"a":4,"e":"远志功能安神益智、祛痰开窍、消散痈肿，痈疽疮毒正是其主治而非禁忌；其性温燥，用量不宜过大，胃溃疡及痰火内盛者慎用。"},{"q":"治疗疮痈肿毒宜首选的药物是","o":["薄荷","牛蒡子","蔓荆子","桑叶","蝉蜕"],"a":1,"e":"牛蒡子辛苦寒，能疏散风热、宣肺透疹、解毒利咽，兼可滑肠，善治疮痈肿毒、痄腮丹毒，故热毒疮痈首选。"},{"q":"传统加强药物的止血之功，常用的炮制方法是","o":["酒炙","蜜炙","炒炭","炒焦","盐水炙"],"a":2,"e":"炒炭使药物部分炭化，增强吸附与收敛之力，故大蓟、小蓟、地榆、艾叶等止血药多炒炭用，以加强止血之功。"},{"q":"人参、麦冬治疗热伤气阴、汗多口渴，常配伍的药是","o":["黄精","乌梅","天花粉","生地黄","五味子"],"a":4,"e":"人参、麦冬配五味子即生脉散，益气养阴、敛汗生津，治热伤气阴之汗多口渴、气短脉虚。"},{"q":"性味苦寒的药物大多具有的功效是","o":["祛风散寒","芳香化湿","清热燥湿","利水渗湿","活血温经"],"a":2,"e":"苦寒药能清热燥湿、泻火解毒，黄连、黄芩、黄柏为其代表，故性味苦寒者多具清热燥湿之功。"},{"q":"莲子与五味子均可用治","o":["久咳虚喘","自汗盗汗","津伤口渴","崩漏下血","心悸失眠"],"a":4,"e":"莲子补脾止泻、益肾涩精、养心安神，五味子敛肺滋肾、生津敛汗、涩精止泻、宁心安神，二者均可用治心悸失眠。"},{"q":"决明子用于润肠通便，应注意的是","o":["先煎","不宜久煎","包煎","另煎","烊化"],"a":1,"e":"决明子含大黄素等成分，久煎易破坏其润肠通便之力，故用于通便时不宜久煎，宜打碎入煎。"},{"q":"治疗丹毒，痄腮，宜首选的药物是","o":["葛根","柴胡","牛蒡子","蝉蜕","薄荷"],"a":2,"e":"牛蒡子能清热解毒、消肿散结，善治丹毒、痄腮、疮痈肿毒，为风热表证兼热毒肿痛者之首选。"},{"q":"增强延胡索止痛作用的炮制加工方法是","o":["蜜炙","醋炙","酒炙","盐水炙","姜汁炙"],"a":1,"e":"延胡索止痛有效成分为生物碱，醋炙后易于煎出，故醋炙能增强其止痛作用，为传统炮制方法。"},{"q":"五倍子、仙鹤草均具有的功效是","o":["收敛止血","解毒截疟","补虚强壮","敛肺降火","固精止遗"],"a":0,"e":"五倍子酸涩，敛肺降火、涩肠止泻、固精止遗、敛汗止血、收湿敛疮；仙鹤草收敛止血、补虚、消积、止痢，收敛止血为二者共有。"},{"q":"治疗痰浊痹阻、胸阳不振的胸痹，常与薤白配伍的药物是","o":["桔梗","丹参","瓜蒌","前胡","浙贝母"],"a":2,"e":"瓜蒌甘微苦寒，功能清热化痰、宽胸散结、润肠通便，与薤白相配即瓜蒌薤白白酒汤，为治胸痹之经典配伍。"},{"q":"皂荚不具有的功效是","o":["祛痰","开窍","散结","消肿","行气"],"a":4,"e":"皂荚辛咸温，有小毒，功能祛痰、开窍、散结消肿，善治顽痰阻肺、痰厥昏迷及疮肿未溃；行气非其所具。"},{"q":"既养心安神，又敛汗生津的药是","o":["远志","丹参","酸枣仁","合欢皮","夜交藤"],"a":2,"e":"酸枣仁甘酸平，功能养心益肝、安神敛汗、生津止渴，为心肝血虚之失眠及体虚多汗之要药。"},{"q":"治疗筋脉挛急疼痛的药物，大多是何味药","o":["酸","苦","甘","辛","咸"],"a":2,"e":"甘能补、能缓、能和，故甘味药能缓急止痛；筋脉挛急疼痛多由阴血不足、筋脉失养所致，治当以甘味缓之。"},{"q":"哪项不是确定药物剂量的依据","o":["药材的质量","药物的颜色","有毒无毒","患者的体质","患者的病势"],"a":1,"e":"确定剂量须依据药材质量、药物性质（有毒无毒、质地轻重）、剂型配伍及患者年龄体质病势等；药物颜色与用量无关。"},{"q":"功能活血化瘀，凉血解毒，解郁安神的药是","o":["川芎","桃仁","红花","西红花","益母草"],"a":3,"e":"西红花甘微寒，功能活血化瘀、凉血解毒、解郁安神，为活血药中兼能凉血、解郁安神者。"},{"q":"既能治疗温邪伤阴夜热早凉，又能治疗阴虚骨蒸潮热的药物是","o":["黄柏","青蒿","地骨皮","胡黄连","牡丹皮"],"a":1,"e":"青蒿苦辛寒，功能清透虚热、凉血除蒸、解暑、截疟，善治温邪伤阴之夜热早凉及阴虚骨蒸潮热。"},{"q":"小儿疳积，厌食，腹大，消瘦，毛发焦枯，现低热不退，首选的药物是","o":["地骨皮","山楂","槟榔","银柴胡","茯苓"],"a":3,"e":"银柴胡甘微寒，功能清虚热、除疳热，善治小儿疳积发热之腹大消瘦、毛发焦枯而低热不退者。"},{"q":"升药主含","o":["水银","氧化砷","硫酸钠","氧化铁","硫酸铝钾"],"a":0,"e":"升药系水银与火硝、白矾升炼而成的汞制剂，主含汞（水银），有大毒，外用拔毒去腐，不作内服。"},{"q":"主治疥癣、梅毒、疮疡溃烂的药物是","o":["硫黄","轻粉","硼砂","炉甘石","蛇床子"],"a":1,"e":"轻粉辛寒有毒，外用攻毒杀虫、敛疮，善治疥癣、梅毒及疮疡溃烂；内服则祛痰消积、逐水通便。"},{"q":"长于止痛，善治风寒头痛、牙痛、风湿痹痛等寒痛证及少阴头痛的药物是","o":["荆芥","防风","香薷","苍耳子","细辛"],"a":4,"e":"细辛辛温走窜，长于止痛，善治风寒头痛、牙痛、风湿痹痛，尤善治少阴头痛，为寒痛证之常用药。"},{"q":"紫菀的功效是","o":["止咳平喘，润肠通便","清肺止咳，降逆止呕","润肺下气，消痰止咳","润肺下气止咳，杀虫灭虱","化痰止咳平喘，润肠通便"],"a":2,"e":"紫菀苦甘微温，入肺经，功能润肺下气、消痰止咳，温而不燥、润而不腻，咳嗽无论新久虚实皆可配伍应用。"},{"q":"性平，能宣肺祛痰的药物是","o":["芥子","桔梗","前胡","白前","竹茹"],"a":1,"e":"桔梗苦辛平，功能宣肺、利咽、祛痰、排脓，性平不偏寒热，为宣肺祛痰、载药上行之常用药。"},{"q":"荆芥穗长于","o":["祛风","止血","透疹","消疮","止痛"],"a":0,"e":"荆芥穗为荆芥之花穗，芳香气烈，长于祛风解表，发汗之力较荆芥茎叶为胜，故外感风寒多用。"},{"q":"不属于珍珠母主治病症的是","o":["阳亢眩晕","目赤肿痛","视物昏花","惊悸失眠","惊痫抽搐"],"a":4,"e":"珍珠母咸寒，功能平肝潜阳、清肝明目、安神定惊，主治阳亢眩晕、目赤肿痛、视物昏花、惊悸失眠；息风止痉治惊痫抽搐非其所长。"},{"q":"薤白配瓜蒌善于治疗","o":["胸痹","胃肠气滞","肠燥便秘","肺热咳嗽","月经不调"],"a":0,"e":"薤白通阳散结、行气导滞，瓜蒌清热化痰、宽胸散结，二药相配善治痰浊痹阻、胸阳不振之胸痹心痛。"},{"q":"苏木的功效是","o":["活血定痛，止血生肌","活血续伤，补肾强骨","破血逐瘀，续筋接骨","散结消肿，通络止痛","活血祛瘀，消肿止痛"],"a":4,"e":"苏木甘咸辛平，入心肝脾经，功能活血祛瘀、消肿止痛，善治跌打损伤之瘀肿疼痛及血瘀经闭痛经。"},{"q":"《本草经集注》的作者是","o":["陶弘景","李时珍","赵学敏","唐慎微","葛洪"],"a":0,"e":"《本草经集注》为南朝陶弘景所著，载药730种，首创按自然属性分类，为本草学重要文献。"},{"q":"均有滋阴潜阳功效的药组是","o":["龟甲、鳖甲","龟甲、百合","鳖甲、麦冬","石斛、百合","天冬、龟甲"],"a":0,"e":"龟甲滋阴潜阳、益肾强骨、养血补心；鳖甲滋阴潜阳、退热除蒸、软坚散结，滋阴潜阳为二者共有之功。"},{"q":"味甘淡，性寒，善清下焦、膀胱湿热的药物是","o":["茯苓","泽泻","猪苓","香加皮","玉米须"],"a":1,"e":"泽泻甘淡寒，入肾与膀胱经，利水渗湿之中兼能泄热，善清下焦湿热，故下焦湿热、小便不利者宜之。"},{"q":"白芍不具有的功效是","o":["养血","润肺","敛阴","柔肝止痛","平抑肝阳"],"a":1,"e":"白芍苦酸微寒，功能养血调经、敛阴止汗、柔肝止痛、平抑肝阳；润肺为麦冬、百合之类所主，白芍无此功。"},{"q":"下列药组中均可活血、行气的是","o":["丹参、三七","莪术、红花","丹参、川芎","延胡索、三七","延胡索、莪术"],"a":4,"e":"延胡索活血行气止痛，莪术破血行气、消积止痛，二者均具活血与行气双重功效；丹参、三七、红花均无行气之力。"},{"q":"既能治疗肾虚作喘，又能治疗五更泄泻的药物是","o":["沉香","磁石","补骨脂","肉苁蓉","吴茱萸"],"a":2,"e":"补骨脂辛苦温，补肾壮阳、固精缩尿、温脾止泻、纳气平喘，故肾虚作喘与脾肾阳虚之五更泄泻均可用。"},{"q":"可助阳解表，可用于治疗阳虚外感风寒的药物是","o":["附子","花椒","胡椒","吴茱萸","高良姜"],"a":0,"e":"附子辛甘大热，能助阳解表，与麻黄、细辛相配治阳虚外感风寒，即麻黄附子细辛汤之义。"},{"q":"不属于白术药性及功效特点的是","o":["消食","燥湿","补脾气","归脾胃经","甘温苦燥"],"a":0,"e":"白术甘苦温，归脾胃经，功能健脾益气、燥湿利水、止汗、安胎，性甘温苦燥；消食非其所长。"},{"q":"温通经脉，擅治寒凝血瘀证的药物是","o":["肉桂","丁香","附子","吴茱萸","小茴香"],"a":0,"e":"肉桂辛甘大热，温通经脉、散寒止痛，善治寒凝血瘀之痛经、胸痹及腰腿冷痛，为温通经脉之要药。"},{"q":"性味辛平，有毒，性善走窜，搜风定搐力强，为息风止痉要药的是","o":["地龙","全蝎","蜈蚣","僵蚕","蕲蛇"],"a":1,"e":"全蝎辛平有毒，性善走窜，搜风定搐力强，为息风止痉要药，善治痉挛抽搐、破伤风及顽固性头痛。"},{"q":"肺热咳嗽，胃热呕吐，痰火内扰烦躁，宜用","o":["竹茹","百部","桔梗","瓜蒌","浙贝母"],"a":0,"e":"竹茹甘微寒，入肺胃经，功能清热化痰、除烦止呕，故肺热咳嗽、胃热呕吐及痰火内扰之烦躁者均宜。"},{"q":"属于“疗热以寒药”治疗原则的是","o":["用附子、干姜治疗腹中冷痛、脉沉无力","用茯苓、猪苓治疗水肿、小便不利","用黄芩、连翘治疗发热咽痛、舌红尿赤","用五味子、莲子治疗盗汗遗精","用麻黄、薄荷治疗外感表证"],"a":2,"e":"疗热以寒药即以寒凉药治热证，黄芩、连翘苦寒清热，用治发热咽痛、舌红尿赤之热证，正合此原则。"},{"q":"青黛的用法是","o":["入煎剂先煎","入煎剂后下","入煎剂包煎","入丸散冲服","入煎剂单煎"],"a":3,"e":"青黛难溶于水，入汤剂易漂浮、有效成分不易煎出，故不入煎剂，宜入丸散冲服，外用则可干撒或调敷。"},{"q":"内能宣通脏腑，通达气血，外能透达经络，散瘀消肿止痛的药是","o":["三棱","红花","桃仁","泽兰","乳香"],"a":4,"e":"乳香辛苦温，芳香走窜，内能宣通脏腑、通达气血，外能透达经络，功能活血止痛、消肿生肌。"},{"q":"温中止泻宜煨用的药物是","o":["五倍子","罂粟壳","肉豆蔻","石榴皮","海螵蛸"],"a":2,"e":"肉豆蔻辛温，生用滑肠，煨用可去其滑肠之性而增强温中止泻之力，故虚寒久泻、五更泄泻宜煨用。"},{"q":"能够减轻或消除热证的药物，其药性一般属于","o":["寒、热","寒、凉","温、凉","温、微寒","平"],"a":1,"e":"寒凉药能清热泻火、凉血解毒，减轻或消除热证，故能减轻或消除热证的药物，其药性一般属寒、凉。"},{"q":"治疗肝郁气滞有热诸痛，最宜选用","o":["青皮","木香","枳实","川楝子","荔枝核"],"a":3,"e":"川楝子苦寒，入肝经，功能疏肝泄热、行气止痛、杀虫，善治肝郁气滞化火之胸胁脘腹疼痛及疝痛。"},{"q":"下列哪味中药适用于寒湿痹证","o":["附子","花椒","胡椒","高良姜","荜澄茄"],"a":0,"e":"附子辛甘大热，能温经散寒、除湿止痛，善治寒湿痹证之骨节疼痛，常与桂枝、白术相配。"},{"q":"关于芳香化湿药的论述，错误的是","o":["多辛、温，主归脾、胃经","入汤剂多宜后下","多具利小便作用","主治湿阻中焦证","易耗伤气阴"],"a":2,"e":"芳香化湿药辛温香燥，主归脾胃经，善治湿阻中焦，入汤剂多后下，易耗气伤阴；其功在化湿，并无利小便作用。"},{"q":"既能凉血止血，又能散瘀消肿的药物是","o":["小蓟","茜草","白及","侧柏叶","白茅根"],"a":0,"e":"小蓟甘苦凉，功能凉血止血、散瘀解毒消痈，止血而不留瘀，故血热夹瘀之尿血、吐血及疮痈肿毒用之。"},{"q":"不属于郁金功效的是","o":["活血止痛","行气解郁","消肿生肌","利胆退黄","清心凉血"],"a":2,"e":"郁金辛苦寒，功能活血止痛、行气解郁、清心凉血、利胆退黄；消肿生肌为乳香、没药之功。"},{"q":"归经是指药物","o":["对机体某部分的选择性作用","对机体的作用趋向","与经络间的密切关系","与药物之间的功能差异","说明对某些经络的毒性"],"a":0,"e":"归经指药物对机体某一部分的选择性作用，表明药效所在脏腑经络部位，为药性理论的重要组成部分。"},{"q":"煅用能治疗胃痛泛酸的中药是","o":["钩藤","天麻","牡蛎","龙骨","牛黄"],"a":2,"e":"牡蛎煅用后收敛制酸之力增强，能中和胃酸、收敛止痛，故胃痛泛酸、胃及十二指肠溃疡者宜煅用。"},{"q":"治疗消渴属肺脾肾三脏不足，气阴两虚者，宜选用","o":["麦冬","黄芪","党参","山药","白术"],"a":3,"e":"山药甘平，入肺脾肾经，功能补脾养胃、生津益肺、补肾涩精，能补三脏之不足，故气阴两虚之消渴用之。"},{"q":"甘寒滑利，善清热利尿，渗湿止泻，治淋证、水肿无论虚实皆宜的药物是","o":["滑石","海金沙","车前子","木通","通草"],"a":2,"e":"车前子甘寒滑利，功能清热利尿通淋、渗湿止泻、明目、祛痰，利水而不伤正，故淋证、水肿无论虚实皆宜。"},{"q":"胃寒湿阻气滞呕吐，治宜首选的药物是","o":["生姜","半夏","豆蔻","竹茹","苍术"],"a":2,"e":"豆蔻辛温芳香，化湿行气、温中止呕，善治寒湿阻中之脘腹胀满及胃寒湿阻气滞之呕吐，为湿阻呕吐常用药。"},{"q":"可用于痰壅咳喘的清热解毒药是","o":["鱼腥草","射干","马勃","蒲公英","穿心莲"],"a":1,"e":"射干苦寒，功能清热解毒、消痰利咽，善治痰热壅盛之咽喉肿痛及痰壅咳喘，为清热解毒药中兼能消痰者。"},{"q":"既能解表散风，又能透疹消疮、止血的药物是","o":["生姜","细辛","桂枝","荆芥","紫苏叶"],"a":3,"e":"荆芥辛微温，功能解表散风、透疹消疮、止血，生用解表透疹，炒炭止血，为表证兼疮疡出血之常用药。"},{"q":"赤石脂、地榆的共同功效是","o":["涩肠止泻，解毒","涩肠止泻，生肌","凉血止血，敛疮","收敛止血，敛疮","解毒敛疮，止血"],"a":3,"e":"赤石脂甘酸涩温，涩肠止泻、收敛止血、敛疮生肌；地榆苦酸涩微寒，凉血止血、解毒敛疮，收敛止血与敛疮为二者共有。"},{"q":"能治疥癣及梅毒的中药是","o":["轻粉","白矾","硫黄","蛇床子","土荆皮"],"a":0,"e":"轻粉辛寒有毒，外用攻毒杀虫、敛疮，善治疥癣、梅毒及疮疡溃烂；内服则逐水通便、消积。"},{"q":"为引药入肝经宜","o":["蜜炙","酒炙","醋炙","盐水炙","姜汁炙"],"a":2,"e":"醋味酸入肝，醋炙可引药入肝经并增强疏肝止痛、活血散瘀之力，故引药入肝经宜用醋炙。"},{"q":"下列哪项不属于“十八反”的药物","o":["甘草反甘遂","乌头反贝母","藜芦反半夏","甘草反大戟","乌头反瓜蒌"],"a":2,"e":"十八反中藜芦反人参、沙参、丹参、玄参、细辛、芍药，反半夏者为乌头，故藜芦反半夏不属十八反。"},{"q":"下列除哪一味药物，均为孕妇慎用药","o":["车前子","滑石","木通","瞿麦","地肤子"],"a":4,"e":"车前子、滑石、木通、瞿麦均属利水通淋滑利之品，孕妇慎用；地肤子性平力缓，不在慎用之列。"},{"q":"为增强药物止呕的作用宜","o":["蜜炙","酒炙","醋炙","盐水炙","姜汁炙"],"a":4,"e":"生姜汁辛温，能温中止呕，姜汁炙可增强药物降逆止呕之功，故半夏、竹茹等止呕药多用姜汁炙。"},{"q":"具有发汗解表，温中止呕，温肺止咳功效的药物是","o":["麻黄","桂枝","紫苏叶","白芷","生姜"],"a":4,"e":"生姜辛微温，功能发汗解表、温中止呕、温肺止咳，为外感风寒、胃寒呕吐及寒痰咳嗽之常用药。"},{"q":"辛味药物的作用是","o":["发散，行气","补益，软坚","燥湿，通泄","收敛，固涩","软坚，缓急"],"a":0,"e":"辛能散、能行，故辛味药具有发散解表、行气行血的作用，多用于外感表证与气滞血瘀证，如麻黄、木香。"},{"q":"具有能补、能缓作用的药物是","o":["黄芪","党参","龙眼","甘草","当归"],"a":3,"e":"甘草味甘，功能补脾益气、缓急止痛、调和诸药，能补能缓最能体现甘味药的特点，故为甘味代表药。"},{"q":"功能解毒疗疮，杀虫止痒，为治疗疥疮要药的是","o":["硫黄","硼砂","白矾","苦参","蛇床子"],"a":0,"e":"硫黄酸温有毒，外用解毒疗疮、杀虫止痒，为治疥疮之要药；内服则补火助阳、通便，须入丸散。"},{"q":"功能祛风湿止痛，善治下半身风湿痹痛的药物是","o":["羌活","独活","牛膝","威灵仙","防风"],"a":1,"e":"独活辛苦微温，功能祛风湿、止痛、解表，其性下行，善治腰膝以下之风湿痹痛，故下半身痹痛首选。"},{"q":"关于薏苡仁健脾止泻的使用方法，叙述正确的是","o":["生用","炒用","蜜炙","先煎","研末冲服"],"a":1,"e":"薏苡仁生用偏于利水渗湿、清热排脓，炒用则健脾止泻之力增强，故脾虚泄泻者宜炒用，常配白术、茯苓。"},{"q":"薏苡仁除能利水渗湿，健脾止泻，除痹外，还能","o":["宁心","泄热","排脓","强筋骨","解暑"],"a":2,"e":"薏苡仁甘淡微寒，功能利水渗湿、健脾止泻、除痹、清热排脓，故肺痈、肠痈脓已成者多用。"},{"q":"药性具有升降两向性，功能上行头目、下行血海的药是","o":["肉桂","牛膝","川芎","益母草","鸡血藤"],"a":2,"e":"川芎辛温，其性升散，上行头目而止痛，又能下行血海而调经，为血中之气药，善治头痛与月经不调。"},{"q":"功能补益心脾、养血安神的药物是","o":["当归","阿胶","何首乌","龙眼肉","熟地黄"],"a":3,"e":"龙眼肉甘温，入心脾经，功能补益心脾、养血安神，善治心脾两虚之心悸怔忡、失眠健忘。"},{"q":"黄柏与苍术的共同功效是","o":["祛风","发汗","解毒","泻火","燥湿"],"a":4,"e":"黄柏苦寒，清热燥湿、泻火除蒸、解毒疗疮；苍术辛苦温，燥湿健脾、祛风散寒，燥湿为二者共有，即二妙散之义。"},{"q":"薄荷和牛蒡子不具有，而蝉蜕具有的功效是","o":["解毒，祛痰","退翳，止痉","利咽，透疹","宣肺，润肠","清肝，疏肝"],"a":1,"e":"蝉蜕甘寒，除疏散风热、利咽透疹外，尚能明目退翳、息风止痉，故退翳、止痉为薄荷、牛蒡子所不具。"},{"q":"常用于治疗肾阳虚衰、筋骨痿软、风湿痹痛、麻木拘挛的药物是","o":["蛤蚧","益智仁","阳起石","威灵仙","淫羊藿"],"a":4,"e":"淫羊藿辛甘温，补肾阳、强筋骨、祛风湿，善治肾阳虚衰之筋骨痿软、风湿痹痛、麻木拘挛。"},{"q":"既能透散外邪，又能宣散邪热的药物是","o":["菊花","柴胡","蝉蜕","淡豆豉","牛蒡子"],"a":3,"e":"淡豆豉辛甘微苦，能透散外邪、宣散郁热，故外感表证及邪热郁于胸中者用之，常与栀子相配。"},{"q":"知母用于阴虚肠燥便秘，因其能","o":["清热泻火","除烦止渴","滋阴润燥","清热凉血","养阴清热"],"a":2,"e":"知母苦甘寒，质润多液，功能清热泻火、滋阴润燥，故阴虚肠燥便秘用之，取其滋阴润燥以滑肠。"},{"q":"称为交通心肾，安定神志之佳品的药物是","o":["朱砂","远志","酸枣仁","柏子仁","夜交藤"],"a":1,"e":"远志苦辛温，入心肾经，能开心气、通肾气，交通心肾而安定神志，故为交通心肾、安神定志之佳品。"},{"q":"有良好的降血压作用，临床多用于高血压的药物是","o":["夏枯草","半边莲","淡竹叶","天花粉","鸭跖草"],"a":0,"e":"夏枯草苦辛寒，入肝胆经，功能清肝泻火、明目、散结消肿，兼有良好降压作用，为高血压眩晕之常用药。"},{"q":"既能清心豁痰，又能开窍醒神，为凉开之品的是","o":["黄连","牛黄","珍珠","石菖蒲","羚羊角"],"a":1,"e":"牛黄苦凉，功能清心豁痰、开窍醒神、凉肝息风、清热解毒，为凉开之品，善治热闭神昏、痰热惊风。"},{"q":"下列关于天麻来源、使用部位正确的是","o":["兰科，根","兰科，块根","兰科，块茎","百合科，块根","百合科，块茎"],"a":2,"e":"天麻为兰科植物天麻的干燥块茎而非根，功能息风止痉、平抑肝阳、祛风通络，为治眩晕抽搐之要药。"},{"q":"中药炮制的常用固体辅料不含以下哪项","o":["麦麸","米","砂","泥","土"],"a":3,"e":"固体辅料常用麦麸、米、砂、土、蛤粉、滑石粉等，泥不属炮制辅料，不作固体辅料使用。"},{"q":"黄连与胡黄连均能治疗","o":["肺热咳嗽","小儿疳热","湿热泻痢","高热神昏","阴虚骨蒸潮热"],"a":2,"e":"黄连与胡黄连均苦寒，能清热燥湿，同可用治湿热泻痢；胡黄连偏退虚热除疳热，黄连偏泻心胃之火。"},{"q":"车前子的用法是","o":["先煎","后下","研末冲服","泡服","包煎"],"a":4,"e":"车前子含大量黏液质，煎煮易糊锅并使药液浑浊，用纱布包煎可保证煎出且不碍口，为含黏液质种子类药的通用煎法。"},{"q":"功擅清热解毒，凉血止痢的药物是","o":["穿心莲","连翘","白头翁","山豆根","熊胆粉"],"a":2,"e":"白头翁苦寒，归大肠经，功能清热解毒、凉血止痢，为治热毒血痢、下痢脓血之要药，亦可治阴痒带下。"},{"q":"白芍与熟地黄的共同适应证为","o":["表虚自汗","须发早白","疮疡肿毒","腰膝酸软","阴虚盗汗"],"a":4,"e":"白芍养血敛阴、柔肝止痛，熟地黄补血滋阴、益精填髓，阴虚盗汗为二者共有的阴亏失敛之证。"},{"q":"养阴而不滋腻恋邪，善治阴虚外感的药物是","o":["麦冬","天冬","玉竹","百合","鳖甲"],"a":2,"e":"玉竹甘微寒，养阴润燥而生津，滋而不腻、养阴不恋邪，故阴虚外感最宜，方如加减葳蕤汤。"},{"q":"治疗风湿痹证日久，累及肝肾的最佳药物组合是","o":["防己、独活","五加皮、桑寄生","黄柏、苍术","秦艽、薏苡仁","苍术、桑枝"],"a":1,"e":"五加皮、桑寄生均祛风湿而兼补肝肾、强筋骨，痹证日久伤及肝肾、腰膝酸软无力者最宜。"},{"q":"硼砂内服可用治","o":["胃热呕吐","痰热咳嗽","肝火头痛","寒痰寒饮","热淋涩痛"],"a":1,"e":"硼砂甘咸凉，内服清热消痰，主治痰热咳嗽、痰黄黏稠；外用则清热解毒、消肿防腐，治咽喉肿痛。"},{"q":"既能袪风湿，又能利水而性寒的药物是","o":["五加皮","秦艽","防己","豨莶草","雷公藤"],"a":2,"e":"防己苦寒，祛风除湿、利水消肿，性寒兼清湿热，故湿热痹兼水肿、小便不利者尤宜。，配黄芪可益气利水。"},{"q":"外用可以治疗斑秃的药物有","o":["淫羊藿","肉苁蓉","吴茱萸","补骨脂","益智仁"],"a":3,"e":"补骨脂辛温，补肾壮阳、温脾止泻、纳气平喘，其酊剂外涂可治白癜风与斑秃，为脾肾阳虚常用药。"},{"q":"被誉为“呕家圣药”的药物是","o":["紫苏叶","生姜","香薷","桂枝","荆芥"],"a":1,"e":"生姜辛温，温中止呕，随配伍可疗寒热虚实诸呕，素有呕家圣药之称，又能解鱼蟹毒。，并可解半夏之毒。"},{"q":"以下哪项关于剂量确定依据的说法不妥的是","o":["入汤剂用药剂量较大，入丸散剂量较小","质轻之品用量宜少，质重之品用量宜大","祛邪为主时，用量宜重；补虚为主时，用量宜轻","一般来说，男女用量差别不大","单味药成方用量宜大，复方中药物用量宜小"],"a":2,"e":"祛邪与补虚的用量须视邪正盛衰而定，祛邪量重、补虚量轻之说失之绝对，补虚药常需量稍大而久服。"},{"q":"患者风寒湿痹，肢体麻木，关节疼痛，治以活血行气，祛风止痛。最宜选用的药是","o":["艾叶","川芎","羌活","郁金","延胡索"],"a":1,"e":"川芎辛温，活血行气、祛风止痛，为血中气药，善治风寒湿痹、肢体麻木、关节疼痛，又能上行头目。"},{"q":"患者产后乳汁不下，乳房红肿疼痛，诊为乳痈。最宜选用的药是","o":["赤芍","泽兰","木通","鸡血藤","王不留行"],"a":4,"e":"王不留行苦平，活血通经、下乳消肿，善治产后乳汁不下及乳痈肿痛，为通乳要药，常与穿山甲同用。"},{"q":"具有补肾助阳、固精缩尿功效的药物是","o":["车前子","决明子","牛蒡子","使君子","沙苑子"],"a":4,"e":"沙苑子甘温，补肾助阳、固精缩尿、养肝明目，主治肾虚腰痛、遗精尿频、目暗不明，为平补肝肾之品。"},{"q":"苦杏仁的功效是","o":["止咳平喘，润肠通便","止咳平喘，解痉止痛","止咳平喘，降气化痰","止咳平喘，利水消肿","止咳平喘，清肠消痔"],"a":0,"e":"苦杏仁苦微温，主入肺经，降肺气而止咳平喘；又富含油脂，能润肠通便，治肠燥便秘。，为治咳喘要药。"},{"q":"用于阳虚外感及寒痰停饮、鼻渊的药物是","o":["荆芥","紫苏叶","生姜","苍耳子","细辛"],"a":4,"e":"细辛辛温，外散风寒、内温肺化饮，兼能助阳解表，故阳虚外感、寒痰停饮及鼻渊头痛均可用。"},{"q":"蒲黄的用药部位为","o":["叶","花粉","果实","根茎","花穗"],"a":1,"e":"蒲黄为香蒲科植物水烛香蒲等的干燥花粉，故药用部位为花粉，生用化瘀、炒用止血，为化瘀止血代表药。"},{"q":"当归的道地产区是","o":["山东","云南","甘肃","四川","广西"],"a":2,"e":"当归道地产区为甘肃岷县一带，所产质优，素称岷当归，为甘肃道地药材，销用最广。，为补血要药。"},{"q":"马勃的功效是","o":["清肺利咽","清热凉血","清心安神","清肝明目","清热燥湿"],"a":0,"e":"马勃辛平，清热解毒、利咽止血，善治咽喉肿痛、咳嗽失音及吐血衄血，外用可敷疮肿。，又可外敷止血。"},{"q":"尤善清中上焦湿热的药物是","o":["黄连","黄芩","黄柏","龙胆","秦皮"],"a":1,"e":"黄芩苦寒，善清肺与中上焦湿热，黄连偏清中焦、黄柏偏清下焦，三者清热部位各有侧重。"},{"q":"具有清热泻火，养肝明目，退翳功效的药物是","o":["夏枯草","密蒙花","蝉蜕","决明子","鸭跖草"],"a":1,"e":"密蒙花甘微寒，清热泻火、养肝明目、退翳，为肝热目赤肿痛、翳障遮睛之常用药，可配菊花、石决明。"},{"q":"根据脏腑经络病变部位而选药的药性理论是","o":["四气","五味","升降浮沉","归经","有毒无毒"],"a":3,"e":"归经标示药物作用的脏腑经络部位，按脏腑经络病变部位选药，正是归经理论的运用。，如黄连归心经。"},{"q":"能截疟， 用治疟疾的药物不包括","o":["槟榔","仙鹤草","大青叶","青蒿","草果"],"a":2,"e":"槟榔、仙鹤草、青蒿、草果均能截疟以治疟疾，大青叶清热解毒、凉血消斑，无截疟之功。"},{"q":"治疗中风偏瘫，胸痹心痛，眩晕头痛，首选的药物是","o":["葛根","淡豆豉","牛蒡子","薄荷","蝉蜕"],"a":0,"e":"葛根解肌退热、生津升阳，其黄酮成分能扩张血管，善治中风偏瘫、胸痹心痛及眩晕头痛。"},{"q":"多服、久服易导致肝功能损害的药物是","o":["皂荚","礞石","黄药子","苦杏仁","天南星"],"a":2,"e":"黄药子苦寒有毒，多服久服易致肝功能损害，甚则中毒性肝炎，须严控剂量与疗程，肝功能不全者忌用。"},{"q":"既能解毒明目退翳，又能收湿止痒的药物是","o":["砒石","滑石","硼石","炉甘石","寒水石"],"a":3,"e":"炉甘石甘平，解毒明目退翳、收湿止痒敛疮，为眼科翳障与湿疮瘙痒所常用之外用药。，煅用则收湿力强。"},{"q":"葶苈子的功效是","o":["清肺止咳，降逆止呕","泻肺平喘，行水消肿","止咳平喘，解痉止痛","润肺下气，消痰止咳","降气止咳平喘，润肠通便"],"a":1,"e":"葶苈子辛苦大寒，专泻肺中痰饮而平喘，兼利水消肿，治痰涎壅盛、喘息不得卧之实证。，泻肺力峻。"},{"q":"止血药主要归何经","o":["心、肝、脾经","肺、脾、肾经","心、脾、肾经","肝、脾、肾经","心、肝、肾经"],"a":0,"e":"止血药多入心、肝、脾经，因心主血、肝藏血、脾统血，三经与血的生成运行密切相关。，故善治血证。"},{"q":"三棱与莪术多醋制后用，目的是为了加强什么作用","o":["祛瘀止痛","生津止渴","收敛固涩","引药入肝","消食化积"],"a":0,"e":"三棱、莪术醋制可引药入肝，增强破血祛瘀之力，故醋炙后祛瘀止痛、消积之功加强。，为破血要药。"},{"q":"何首乌炮制的目的是","o":["便于贮藏","便于制剂","改变性能","矫味矫臭","引药入经"],"a":2,"e":"生首乌解毒截疟、润肠通便，制首乌补肝肾、益精血、乌须发，炮制后性能由泻转补。，为炮制改变性能之例。"},{"q":"外用具有消风祛斑功效的药物有","o":["菟丝子、补骨脂","菟丝子、沙苑子","补骨脂、益智仁","补骨脂、沙苑子","菟丝子、益智仁"],"a":0,"e":"菟丝子与补骨脂均能补肾固精，外用又可消风祛斑，用于白癜风、斑秃及皮肤色素脱失。，为平补之品。"},{"q":"治温病热陷心包，最适宜的药物是","o":["寒水石","芦根","知母","石膏","竹叶卷心"],"a":4,"e":"竹叶卷心清心泻火，善治温病热陷心包、神昏谵语，常与连翘心、莲子心配伍同用。，为清心要药。"},{"q":"长于滋阴退热除蒸的药物是","o":["鳖甲","青蒿","牡丹皮","枸杞子","女贞子"],"a":0,"e":"鳖甲咸寒，滋阴潜阳、退热除蒸、软坚散结，长于治阴虚发热、骨蒸劳热及久疟疟母。，为退虚热要药。"},{"q":"有小毒，孕妇禁用的是","o":["苏木","雪竭","儿茶","土鳖虫","自然铜"],"a":3,"e":"土鳖虫咸寒有小毒，破血逐瘀、续筋接骨，孕妇及月经过多者禁用，内服不宜过量。，为伤科常用药。"},{"q":"既能平肝潜阳，又能软坚散结的药物是","o":["钩藤","蒺藜","牡蛎","天麻","珍珠母"],"a":2,"e":"牡蛎咸微寒，质重沉降，平肝潜阳、软坚散结，兼收敛固涩、制酸止痛，煅用收敛力强。，为潜阳要药。"},{"q":"既能补脾益肺，又能养血生津的药物是","o":["山药","党参","白术","甘草","西洋参"],"a":1,"e":"党参甘平，补脾益肺、养血生津，性平力缓，为脾肺气虚兼气血两亏者常用之品。，常代替人参用之。"},{"q":"药性平和而不峻，归肝、脾经，既善活血调经 ，又芳香舒脾而行水消肿的药是","o":["牛膝","泽兰","苏木","鸡血藤","王不留行"],"a":1,"e":"泽兰苦辛微温，活血调经、祛瘀消痈、利水消肿，性较平和，芳香舒脾而能行水，妇科常用。"},{"q":"止血不留瘀，化瘀不伤正，为外伤科要药的是","o":["白及","蒲黄","地榆","三七","白茅根"],"a":3,"e":"三七甘微苦温，化瘀止血、活血定痛，止血而不留瘀、化瘀而不伤正，为伤科要药，内服外用皆效。"},{"q":"下列哪项不是薄荷的功效","o":["疏散风热","清利头目","利咽","除湿","透疹"],"a":3,"e":"薄荷辛凉，疏散风热、清利头目、利咽透疹、疏肝行气，除湿非其功效，除湿多属藿香、佩兰。"},{"q":"温通经脉，散寒止痛，可治阳虚寒凝之阴疽的药组是","o":["麻黄、肉桂","附子、干姜","乌药、花椒","丁香、小茴香","桂枝、吴茱萸"],"a":0,"e":"麻黄辛温散寒、通阳散结，肉桂温通经脉、散寒止痛，合用治阳虚寒凝之阴疽，如阳和汤。"},{"q":"具有活血化瘀，敛肺平喘，化浊降脂功效的药物是","o":["山楂","泽泻","虎杖","丹参","银杏叶"],"a":4,"e":"银杏叶甘苦涩平，活血化瘀、通络止痛、敛肺平喘、化浊降脂，治胸痹心痛、咳喘及高脂血症。"},{"q":"通草甘淡渗湿，微寒清降，功效是","o":["利尿通利，清心除烦","利尿通淋，清热解暑","利尿通淋，渗湿止泻","清热利湿，通气下乳","清热利湿，祛风止痒"],"a":3,"e":"通草甘淡微寒，清热利湿、通气下乳，治湿热淋证、水肿尿少及产后乳汁不下，质轻力缓。"},{"q":"治三焦热盛，高热烦躁，火毒疮疡，目赤肿痛，小便短赤，首选的药物是","o":["石膏","知母","栀子","天花粉","芦根"],"a":2,"e":"栀子苦寒，清泻三焦火邪、凉血解毒，善治高热烦躁、火毒疮疡、目赤肿痛及小便短赤。，为清热泻火要药。"},{"q":"治肝风内动证，蜈蚣常与之相须为用的是","o":["地龙","钩藤","蕲蛇","僵蚕","全蝎"],"a":4,"e":"全蝎与蜈蚣同入肝经，均息风止痉、攻毒散结、通络止痛，相须为用治肝风内动、痉挛抽搐。"},{"q":"朱砂、轻粉的主要毒性成分是","o":["汞","皂苷","内脂","强心苷","毒蛋白"],"a":0,"e":"朱砂主含硫化汞，轻粉主含氯化亚汞，二者毒性成分均为汞，久服可致汞蓄积中毒。，故须严格控量。"},{"q":"硫黄、蛇床子均适用的病症是","o":["虚喘","疮疡","寒湿带下","肾虚阳痿","寒湿痹痛"],"a":3,"e":"硫黄补火助阳，蛇床子温肾壮阳，二者均可治肾虚阳痿，又均能杀虫止痒而疗疥癣湿疮。，为外科常用药。"},{"q":"下列除哪项外，均为苦味药的作用","o":["清泻火热","淡渗利湿","泻火存阴","通泄大便","降泄逆气"],"a":1,"e":"苦能泄、能燥、能坚，故有清泻火热、降泄逆气、通泄大便、泻火存阴之用，淡渗利湿属淡味。"},{"q":"北沙参和麦冬都具有的功效是","o":["清心肺之热","清心肝之热","补心肾之阴","补肝肾之阴","养肺胃之阴"],"a":4,"e":"北沙参养阴清肺、益胃生津，麦冬养阴润肺、益胃生津，二者共同功效为养肺胃之阴。，为养阴常用药对。"},{"q":"不属于青皮主治病证的是","o":["胸胁胀痛","乳房胀痛","食积腹痛","疝气疼痛","呕吐呃逆"],"a":4,"e":"青皮疏肝破气、消积化滞，治胸胁乳房胀痛、疝气疼痛及食积腹痛，呕吐呃逆非其所主，该证属陈皮。"},{"q":"既能滋阴，又能止血的药是","o":["阿胶","白芍","当归","龙眼肉","熟地黄"],"a":0,"e":"阿胶甘平，补血滋阴、润燥止血，为止血要药，善治阴血亏虚之吐血、尿血、崩漏。，为补血要药。"},{"q":"既能祛风湿，通经络，止痹痛，又能清虚热，退黄疸的药物是","o":["威灵仙","秦艽","独活","防己","徐长卿"],"a":1,"e":"秦艽苦辛微寒，祛风湿、通络止痛，兼退虚热、清湿热而退黄疸，为风药中之润剂。，寒热痹皆可用。"},{"q":"广藿香的功效是","o":["行气，温中","燥湿，消积","化湿，行气","化湿，解暑","温中，除痰"],"a":3,"e":"广藿香辛微温，芳香化湿、和中止呕、发表解暑，为暑湿、湿温初起之常用药，又能止呕。"},{"q":"土鳖虫除破血逐瘀外，尚能","o":["补肝肾","活血消肿","通络止痛","生肌敛疮","续筋接骨"],"a":4,"e":"土鳖虫咸寒，破血逐瘀、续筋接骨，善治跌打损伤、筋伤骨折及瘀滞经闭、产后腹痛。，为破血疗伤要药。"},{"q":"麻黄与香薷均有的功效是","o":["和胃","止痉","止咳","平喘","利水"],"a":4,"e":"麻黄宣肺平喘、利水消肿，香薷化湿和中、利水消肿，二者共有利水消肿之功，可治水肿。"},{"q":"中药剂量，通常是指","o":["每味药的成人一日量","一剂药的成人一次量","重病患者的成人一日量","轻病患者的成人一次量","每味药的儿童一日量"],"a":0,"e":"中药剂量一般指每味药成人的一日用量，丸散剂则指一次量，须依剂型分别说明，鲜品加倍。"},{"q":"枇杷叶的主治证不包括","o":["肺热咳嗽","胃热呕逆","烦热口渴","水肿尿少","气逆喘急"],"a":3,"e":"枇杷叶清肺止咳、降逆止呕，治肺热咳嗽、气逆喘急及胃热呕逆，无利水消肿之功，水肿当用桑白皮。"},{"q":"有生肌敛疮功效，外用可治手足皴裂的药物是","o":["艾叶","蒲黄","白及","三七","仙鹤草"],"a":2,"e":"白及苦甘涩微寒，收敛止血、消肿生肌，外用生肌敛疮，可治手足皲裂、疮口不敛，为收敛止血要药。"},{"q":"朱砂入药的正确炮制方法是","o":["水飞","炙","煅","煨","淬"],"a":0,"e":"朱砂质重含汞，水飞可除去可溶性杂质、降低游离汞并研成极细粉，故入药须水飞。，以免汞中毒。"},{"q":"眼科外治目赤翳障，烂弦风眼，最宜选用","o":["砒石","升药","铅丹","硫磺","炉甘石"],"a":4,"e":"炉甘石明目退翳、收湿止痒，制成眼药点眼，可治目赤翳障、烂弦风眼及眼睑湿烂，为眼科外治要药。"},{"q":"治风寒感冒，巅顶头痛，最宜选用的药物是","o":["羌活","防风","白芷","柴胡","藁本"],"a":4,"e":"藁本辛温，祛风散寒、除湿止痛，善达巅顶，为治风寒感冒巅顶头痛之要药，也可治风湿痹痛。"},{"q":"在治疗风寒咳喘时，苦杏仁配伍麻黄主要起下列何项作用","o":["止咳化痰，降气平喘","发散风寒，宣肺平喘","发汗解表，化痰止咳","发散风寒，泻肺平喘","宣肺止咳，化痰平喘"],"a":1,"e":"麻黄发散风寒、宣肺平喘，杏仁降气止咳平喘，一宣一降，共奏散寒宣肺、止咳平喘之效。"},{"q":"能化痰止咳，清利湿热，活血化瘀的药物是","o":["枇杷叶","矮地茶","葶苈子","马兜铃","桑白皮"],"a":1,"e":"矮地茶苦辛平，化痰止咳、清利湿热、活血化瘀，治咳嗽痰多、湿热黄疸及跌打损伤，为治咳常用药。"},{"q":"石斛善治","o":["肺气虚证","肝血虚证","胃阴虚证","肾阳虚证","气阴两虚证"],"a":2,"e":"石斛甘微寒，益胃生津、滋阴清热，善治胃阴不足之口干烦渴、胃脘嘈杂及舌干无苔。，为益胃生津要药。"},{"q":"涩味药物与下列何种药物作用相似","o":["苦味","咸味","酸味","辛味","甘味"],"a":2,"e":"涩味与酸味作用相似，均能收敛固涩，用于自汗盗汗、久泻久痢、遗精滑泄等滑脱诸证。，为治滑脱之常法。"},{"q":"味辛行散，长于行气除胀的消食药是","o":["附子","莲子","白芥子","莱菔子","紫苏子"],"a":3,"e":"莱菔子辛甘平，消食除胀、降气化痰，味辛行散，长于行气除胀，治食积气滞、脘腹胀满。"},{"q":"不宜与赤石脂同用的药物是","o":["乌头","人参","肉桂","硫黄","禹余粮"],"a":2,"e":"十九畏载官桂畏石脂，肉桂与赤石脂同用属相畏配伍，故不宜同方，以免降低药效。，十九畏所载。"},{"q":"具有纳气平喘、温脾止泻功效的药物是","o":["淫羊藿","巴戟天","肉苁蓉","益智仁","补骨脂"],"a":4,"e":"补骨脂辛苦温，补肾壮阳、固精缩尿、温脾止泻、纳气平喘，为脾肾阳虚之常用药，外用可消风祛斑。"},{"q":"汤剂需要先煎，久煎的药物是","o":["肉桂","附子","薄荷","吴茱萸","车前子"],"a":1,"e":"附子有毒，其所含乌头碱经久煎水解而减毒，故须先煎、久煎至口尝无麻辣感为度。，先煎可减毒。"},{"q":"穿心莲有泻火解毒之功，善治的病证是","o":["肠痈","肺痈","乳痈","疔疮","口疮"],"a":1,"e":"穿心莲苦寒，清热解毒、凉血消肿，善治肺痈咳吐脓血，亦可治肠痈、疮疖肿毒，燥湿止痢。"},{"q":"黄连用治湿热泻痢，腹痛里急后重，常配伍的药物是","o":["陈皮","龙胆","青皮","木香","香附"],"a":3,"e":"黄连清热燥湿、泻火解毒，木香行气止痛，二者配伍调气厚肠，治湿热泻痢、里急后重，如香连丸。"},{"q":"被誉为“东方医学巨典”的著作是","o":["《本草纲目拾遗》","《神农本草经》","《本草纲目》","《新修本草》","《本草经集注》"],"a":2,"e":"李时珍《本草纲目》载药一千八百余种，集明代以前本草之大成，被誉为东方医学巨典。，为纲目体例之始。"},{"q":"以下哪个是江苏的道地药材","o":["薄荷","山药","菊花","麦冬","白术"],"a":0,"e":"江苏为薄荷著名道地产区，所产薄荷脑含量高、质量优，故薄荷属江苏道地药材，称苏薄荷。"},{"q":"既能清泄三焦火邪，又善清心泻火而除烦的药物是","o":["石膏","芦根","知母","天花粉","栀子"],"a":4,"e":"栀子苦寒清降，通泻三焦火邪，又入心经清心除烦，治热病心烦、火毒诸证，为清热除烦要药。"},{"q":"使用化痰药治疗癫痫惊厥者，最常配伍","o":["清热药、消食药","补虚药、消食药","安神药、理气药","安神药、泻下药","平肝息风药、安神药"],"a":4,"e":"化痰药治癫痫惊厥，须配平肝息风药以止抽搐、安神药以定惊，标本兼顾而取效，如配全蝎、琥珀。"},{"q":"功效生津止渴，能治疗热病口渴，消渴的药物是","o":["葛根","淡豆豉","牛蒡子","薄荷","蝉蜕"],"a":0,"e":"葛根甘辛凉，解肌退热、生津止渴、升阳止泻，善治热病烦渴及阴虚消渴，又能透疹。，为解肌要药。"},{"q":"七情配伍中，可以降低药物功效的是","o":["相须","相使","相杀","相畏","相恶"],"a":4,"e":"相恶指两药合用，一种药物使另一种药物功效降低甚至丧失，如人参恶莱菔子，故当避免同用。"},{"q":"辛香透散，既清虚热，又解暑热的药物是","o":["黄柏","知母","青蒿","白薇","薄荷"],"a":2,"e":"青蒿苦辛寒，芳香透散，清透虚热、凉血除蒸、解暑热、截疟，为暑热外感之常用药。，又可截疟退热。"},{"q":"附子的主治证不包括","o":["亡阳四肢厥冷","风寒湿痹疼痛","虚寒脘腹冷痛","寒饮伏肺喘嗽","阳虚外感风赛"],"a":3,"e":"附子回阳救逆、补火助阳、散寒止痛，寒饮伏肺喘嗽非其所主，该证多选干姜、细辛、五味子。"},{"q":"属于“十八反”的配伍药对是","o":["甘草与海藻","丁香与郁金","人参与五灵脂","川芎与牛膝","三棱与莪术"],"a":0,"e":"十八反载藻戟遂芫俱战草，甘草与海藻相反；丁香畏郁金、人参畏五灵脂则属十九畏。，二者不可混同。"},{"q":"牛膝除可逐瘀通经外又能","o":["行气解郁","引火归元","利水通淋","祛风通络","消积止痛"],"a":2,"e":"牛膝苦甘酸平，逐瘀通经、补肝肾强筋骨、利尿通淋、引血下行，为活血通经常用药。，为引血下行之品。"},{"q":"淫羊藿具有的功效是","o":["补肾阳、安胎元","补肾阳、祛风湿","祛风湿、退虚热","补肾阳、止咳喘","祛风湿、止泻痢"],"a":1,"e":"淫羊藿辛甘温，补肾阳、强筋骨、祛风湿，治肾阳虚衰之阳痿尿频及风寒湿痹，又名仙灵脾。"},{"q":"既用于治疗肺痈，又可治疗肠痈的药是","o":["桃仁","赤芍","大血藤","鱼腥草","牡丹皮"],"a":0,"e":"桃仁苦甘平，活血祛瘀、润肠通便，又善治肺痈、肠痈，方如苇茎汤、大黄牡丹汤，为破血行滞要药。"},{"q":"紫草的药用部分是","o":["根","全草","花粉","果实","种子"],"a":0,"e":"紫草为紫草科植物新疆紫草或内蒙紫草的干燥根，故药用部位为根，而非全草或花粉。，质松气特异。"},{"q":"内能燥湿健脾，外能散风寒，除痹发表的药物是","o":["白术","独活","藁本","苍术","广藿香"],"a":3,"e":"苍术辛苦温，燥湿健脾、祛风散寒、明目，内可健脾燥湿，外能除痹发表，为湿阻中焦要药。"},{"q":"蜂房具有的功效是","o":["截疟杀虫","祛痰平喘","开窍醒神","祛风止痛","燥湿止带"],"a":3,"e":"蜂房甘平有毒，攻毒杀虫、祛风止痛，治疮疡肿毒、风湿痹痛及牙痛、癣疮，外用适量。，疮疡初起者忌用。"},{"q":"《名医别录》有“主妇人生子不下”的记载，故孕妇慎用的药物是","o":["薄荷","牛蒡子","蝉蜕","升麻","柴胡"],"a":2,"e":"《名医别录》载蝉蜕主妇人生子不下，其性寒下行，故孕妇当慎用，不可过服，为解表药中特例。"},{"q":"治疗肝阳上亢，头晕头痛，首选的药物是","o":["菊花","升麻","牛蒡子","蝉蜕","薄荷"],"a":0,"e":"菊花甘苦微寒，疏散风热、平肝明目、清热解毒，肝阳上亢之眩晕头痛多以为首选。，为平肝明目要药。"},{"q":"砂仁不具备的功效是","o":["安胎","化湿","平喘","温中","行气"],"a":2,"e":"砂仁辛温，化湿开胃、温脾止泻、理气安胎，无平喘之功，平喘多属蛤蚧、补骨脂之类。，注意鉴别。"},{"q":"可用治肺痈、肠痈的药物是","o":["茯苓","泽泻","冬瓜皮","猪苓","薏苡仁"],"a":4,"e":"薏苡仁甘淡微寒，利水渗湿、健脾止泻、除痹排脓，善治肺痈、肠痈及水肿脚气，药食两用。"},{"q":"下面为相反配伍的药物是","o":["大戟与乌头","芫花与海藻","乌头与半夏","贝母与瓜蒌","丹参与芍药"],"a":2,"e":"十八反中半蒌贝蔹及攻乌，乌头与半夏相反；大戟、芫花、甘遂与甘草相反亦属十八反。，当严格避免。"},{"q":"咳喘兼大便秘结者，宜选用","o":["紫苏叶","紫苏梗","紫苏子","车前子","葶苈子"],"a":2,"e":"紫苏子辛温，降气化痰、止咳平喘、润肠通便，故咳喘而兼肠燥便秘者最为适宜，为三子养亲汤主药。"},{"q":"既可用于血热出血，又可用于热壅血滞的药物是","o":["赤芍","青黛","生地黄","玄参","贯众"],"a":0,"e":"赤芍苦微寒，清热凉血、散瘀止痛，既治血热吐衄，又治热壅血滞之疼痛、经闭，与白芍功用有别。"},{"q":"地肤子药性苦降辛散，寒清，主入肾、膀胱经，其功效是","o":["清利湿热，利胆退黄","清利湿热，通淋止痛","利尿通淋，清热解暑","利湿退黄，利尿通淋","清热利湿，祛风止痒"],"a":4,"e":"地肤子辛苦寒，清热利湿、祛风止痒，内服治淋证涩痛，外洗治皮肤瘙痒、湿疹，为皮肤科常用药。"},{"q":"治少阳证之要药是","o":["菊花","柴胡","牛蒡子","蝉蜕","薄荷"],"a":1,"e":"柴胡苦辛微寒，和解退热、疏肝解郁、升举阳气，为治邪在少阳、寒热往来之要药，如小柴胡汤。"},{"q":"既可用于惊风癫痫，又能用于淋证，癃闭的药物是","o":["琥珀","龙骨","车前子","柏子仁","酸枣仁"],"a":0,"e":"琥珀甘平，镇惊安神、活血散瘀、利尿通淋，既治惊风癫痫，又治淋证癃闭，并可活血消肿。"},{"q":"车前子是常用利尿通淋药，其主治病证不包括","o":["湿热淋证","小便不利之水泻","脾虚湿盛泄泻","寒湿痹证","暑湿泄泻"],"a":3,"e":"车前子清热利尿通淋、渗湿止泻、清肝明目、清肺化痰，寒湿痹证非其所主，痹证多选独活、威灵仙。"},{"q":"花椒为药食两用中药，作为药用时煎服的用量为","o":["1～3g","1～5g","2～5g","3～6g","3～10g"],"a":3,"e":"花椒辛温有毒，温中止痛、杀虫止痒，煎服用量三至六克，外用适量，不可过量，以免中毒。"},{"q":"五味子和乌梅的共同功效是","o":["益气滋阴","补肾宁心","安蛔止痛","敛肺生津","涩精止遗"],"a":3,"e":"五味子敛肺滋肾、生津敛汗，乌梅敛肺止咳、生津止渴，二者共有敛肺生津之功，又均能涩肠止泻。"},{"q":"升药的功效是","o":["杀虫止痒","止血敛疮","拔毒去腐","清热解毒","消痈散结"],"a":2,"e":"升药由水银、火硝、白矾炼成，功能拔毒去腐，治痈疽溃后脓出不畅、腐肉不去，只作外用。"},{"q":"治疗阳明腑实，大黄、芒硝配伍甘草的主要目的是","o":["缓急止痛","健脾益气","调和药性","清热解毒","行气止痛"],"a":2,"e":"调胃承气汤中甘草甘缓，调和大黄、芒硝苦寒峻下之性，使泻下而不伤正气，此即调和药性。"},{"q":"治肺热伤阴，燥咳无痰，最适宜的药物是","o":["石膏","寒水石","知母","栀子","淡竹叶"],"a":2,"e":"知母苦甘寒，清热泻火、滋阴润燥，善治肺热伤阴、燥咳无痰及骨蒸潮热，为清润并行之品。"},{"q":"炒用可使其苦寒及滑肠之性略减的药物是","o":["菊花","升麻","牛蒡子","蝉蜕","柴胡"],"a":2,"e":"牛蒡子辛苦寒，疏散风热、宣肺透疹、解毒利咽，炒后苦寒及滑肠之性略减，脾胃虚寒者宜炒用。"},{"q":"桑枝的功效是","o":["祛风除湿，通络止痛，杀虫止痒","袪风通络，凉血消肿","祛风湿，通经络，止泻痢","祛风，通络，活血，下乳","袪风湿，利关节"],"a":4,"e":"桑枝苦平，祛风湿、利关节，善达上肢，治风湿痹痛、肩臂酸痛麻木，尤宜热痹，可配防己。"},{"q":"其气清芬，能清热利湿，治疗湿温暑湿的是","o":["滑石","金钱草","虎杖","茵陈","木通"],"a":3,"e":"茵陈苦辛微寒，气清香，清利湿热、利胆退黄，兼治湿温、暑湿及湿疮瘙痒，为治黄疸要药。"},{"q":"尤善治疔毒的药物是","o":["蒲公英","鱼腥草","紫花地丁","重楼","大青叶"],"a":2,"e":"紫花地丁苦辛寒，清热解毒、凉血消肿，善治疔疮肿毒、痈疽发背，为治疔之要药。，为疔疮专药。"},{"q":"运用凉血止血药时，常配何类药以加强疗效","o":["清热凉血药","滋阴润燥药","收敛止血药","化瘀止血药","活血化瘀药"],"a":0,"e":"凉血止血药治血热出血，常配清热凉血药以清血分之热，标本同治而增强止血之效，如配生地、丹皮。"},{"q":"擅长通经下乳，为治产后乳汁不下之要药的是","o":["水蛭","三棱","莪术","穿山甲","蒲公英"],"a":3,"e":"穿山甲咸微寒，活血消癥、通经下乳、消肿排脓，为治产后乳汁不下之要药，又能通络。，为通乳要药。"},{"q":"妊娠禁用药应除外","o":["牵牛","桃仁","巴豆","莪术","水蛭"],"a":1,"e":"妊娠禁用药多为毒性峻烈或破血堕胎之品，牵牛、巴豆、莪术、水蛭皆属禁用，桃仁为慎用。"},{"q":"慎用温经止血药的病证为","o":["瘀血之出血证","气虚之出血证","阳虚之出血证","脾虚之出血证","血热妄行之出血证"],"a":4,"e":"温经止血药性温，适用于虚寒性出血，血热妄行者用之反助热动血，故当慎用，忌用于实热证。"},{"q":"既能解表散寒、行气宽中安胎，又能解鱼蟹毒的药物是","o":["紫苏叶","砂仁","黄芩","桑寄生","白术"],"a":0,"e":"紫苏叶辛温，解表散寒、行气宽中、安胎、解鱼蟹毒，宜风寒感冒兼气滞胸闷者，又能止呕。"},{"q":"龟甲、鳖甲的煎煮方法是","o":["先煎","后下","包煎","烊化","冲服"],"a":0,"e":"龟甲、鳖甲为甲壳类质重难煎，须打碎先煎，以充分煎出有效成分，一般先煎半小时。，以免浪费药材。"},{"q":"可随时采收的药材是","o":["矿物药","动物药","根类植物药","叶类植物药","果实类植物药"],"a":0,"e":"矿物药受季节气候影响小，成分稳定，全年均可随时采收，不必限定采集时间，如石膏、磁石。"},{"q":"清虚热药的药性特点是","o":["性寒凉，主归肺、胃经","性寒凉，主归肝、肾经","性温热，主归肺、肝经","性温热，主归心、肺经","性寒凉，主归胃、肾经"],"a":1,"e":"清虚热药性多寒凉，主归肝、肾经，功能清虚热、退骨蒸，治阴虚内热、骨蒸潮热，如青蒿、地骨皮。"},{"q":"在“十八反”中，下列除哪味药物外均与乌头相反","o":["玄参","白及","贝母","瓜蒌","半夏"],"a":0,"e":"十八反载乌头反半夏、瓜蒌、贝母、白及、白蔹，玄参不属乌头所反之品，反药同用增毒。"},{"q":"五加皮的功效是","o":["袪风湿，补肝肾，安胎","袪风湿，补肝肾，调冲任","袪风湿，补肝肾，利水","袪风湿，强筋骨，补肾阳","袪风湿，强筋骨，止血"],"a":2,"e":"五加皮辛苦温，祛风湿、补肝肾、强筋骨、利水消肿，治风湿痹痛兼水肿、筋骨痿软。，为痹证常用药。"},{"q":"不具有生津止渴功效的药是","o":["麦冬","山药","鳖甲","玉竹","天花粉"],"a":2,"e":"麦冬、玉竹、天花粉、山药均能生津止渴，鳖甲滋阴潜阳、软坚散结，无生津止渴之功。，注意据此鉴别。"},{"q":"大剂量久服可导致水钠潴留，引起浮肿的药物是","o":["黄芪","人参","甘草","党参","白术"],"a":2,"e":"甘草长期大剂量服用，其甘草酸具盐皮质激素样作用，可致水钠潴留、浮肿及血压升高。，湿盛者忌用。"},{"q":"既能润肠通便，又能润肺止咳的药物是","o":["火麻仁","郁李仁","松子仁","柏子仁","决明子"],"a":2,"e":"松子仁甘温质润，既能润肠通便，又能润肺止咳，宜肠燥便秘兼肺燥干咳者，如三仁丸。，润而不腻。"},{"q":"外敷能发泡，皮肤过敏者忌用的药物是","o":["芥子","桔梗","半夏","天南星","白附子"],"a":0,"e":"芥子辛温，温肺豁痰、利气散结、通络止痛，外敷可发泡，皮肤过敏者忌用，敷之宜慎。，内服须炒制。"},{"q":"枇杷叶止咳平喘的机制是","o":["宣肺","润肺","清肺","敛肺","泻肺"],"a":2,"e":"枇杷叶苦微寒，清肺止咳、降逆止呕，其止咳平喘机制在于清降肺热，故肺热咳嗽最宜。，非宣肺润肺。"},{"q":"味甘，性凉，善走肌肤以利尿消肿，治疗夏日水肿胀满，小便不利的药物是","o":["香加皮","猪苓","茯苓","薏苡仁","冬瓜皮"],"a":4,"e":"冬瓜皮甘凉，利水消肿、清热解暑，善走肌肤，治夏日水肿胀满、小便不利，药食两用。，为水肿常用药。"},{"q":"治蛔虫、绦虫及虫积腹痛者，宜选用","o":["甘遂","京大戟","芫花","巴豆霜","牵牛子"],"a":4,"e":"牵牛子苦寒有毒，泻下逐水、去积杀虫，可驱蛔虫、绦虫并治虫积腹痛、大便秘结。，体虚者慎用。"},{"q":"香附醋制的目的是","o":["减低毒性","便于制剂","加强防腐","加强止痛作用","加强活血作用"],"a":3,"e":"香附醋制可引药入肝、增强疏肝止痛之力，故醋香附多用于肝郁气滞之胸胁脘腹疼痛。，为妇科要药。"},{"q":"穿心莲可用治湿热泻痢、湿疹，主要是因其能","o":["泻火解毒","清热燥湿","清利湿热","凉血消肿","祛风除湿"],"a":1,"e":"穿心莲苦寒，能清热燥湿，故治湿热泻痢、湿疹瘙痒，又清热解毒而治肺痈、咽喉肿痛。，故能治痢止痒。"},{"q":"芡实与白芷均可用治","o":["头痛","带下","遗精滑精","脾虚久泻","疮痈肿毒"],"a":1,"e":"芡实益肾固精、健脾止泻、除湿止带，白芷燥湿止带，二者均可治带下病，一补一散。，为带下常用药。"},{"q":"海螵蛸与赤石脂均具有的功效是","o":["收敛止血，敛疮","收敛止血，制酸","涩肠止泻，敛疮","涩肠止泻，生肌","固精缩尿，止血"],"a":0,"e":"海螵蛸收敛止血、收湿敛疮，赤石脂涩肠止泻、收敛止血、生肌敛疮，共有收敛止血、敛疮之功。"},{"q":"下列哪项不是甘草的归经","o":["脾经","肺经","胃经","肝经","心经"],"a":3,"e":"甘草归心、肺、脾、胃经，功能补脾益气、清热解毒、祛痰止咳、缓急止痛、调和诸药，不归肝经。"},{"q":"均可治水肿、脚气的药物是","o":["防己、五加皮、独活","防己、五加皮、木瓜","五加皮、蕲蛇、防己","防己、威灵仙、木瓜","桑寄生、防己、五加皮"],"a":1,"e":"防己利水消肿，五加皮利水，木瓜化湿舒筋，三者均可治水肿、脚气浮肿，为治脚气常用。"},{"q":"血竭、儿茶的相同功效是","o":["活血止血，生肌敛疮","活血疗伤，通络止痛","活血定痛，清肺化痰","活血疗伤，补肾强骨","散瘀止痛，消食化积"],"a":0,"e":"血竭活血定痛、化瘀止血、生肌敛疮，儿茶活血止痛、止血生肌，共有活血止血、生肌敛疮之效。"},{"q":"下列哪项是淡味药的作用","o":["软坚散结","活血祛瘀","疏肝理气","利水渗湿","泻下通便"],"a":3,"e":"淡味药能渗能利，作用为利水渗湿，多用于水肿、小便不利及淋证，如茯苓、猪苓。，淡附于甘。"},{"q":"最早采用图文对照编写方法的本草著作是","o":["《神农本草经》","《证类本草》","《本草经集注》","《本草拾遗》","《新修本草》"],"a":4,"e":"唐代《新修本草》附药图与图经，首创图文对照体例，为世界上最早的国家药典，载药八百余种。"},{"q":"黄芩治疗血热便血，常配伍的药是","o":["地榆","三七","黄连","白及","艾叶"],"a":0,"e":"黄芩善清大肠湿热而治便血，地榆凉血止血、尤善下焦，二者配伍可增强凉血止血之效。，为治便血常用配伍。"},{"q":"缓和甘遂、大戟、芫花毒烈之性，宜选用","o":["甘草","大枣","白芍","生姜","花椒"],"a":1,"e":"十枣汤以大枣十枚煎汤送服甘遂、大戟、芫花，取其甘缓，缓和诸药毒烈之性并护胃。，为攻补兼施之法。"},{"q":"既能开窍醒神，又能凉肝息风的药物是","o":["冰片","钩藤","牛黄","石菖蒲","苏合香"],"a":2,"e":"牛黄苦凉，清心豁痰、开窍醒神、凉肝息风，治热病神昏、中风痰迷、惊痫抽搐，为凉开要药。"},{"q":"确定归经学说的理论基础是","o":["阴阳学说","脏腑经络理论","药性理论","药味理论","五行学说"],"a":1,"e":"归经学说以脏腑经络理论为基础，依药物疗效所及脏腑经络部位确定其归属，如黄连归心、大肠经。"},{"q":"善治阴虚劳嗽，肺燥咳嗽的药对为","o":["知母、黄柏","桑叶、菊花","金银花、连翘","知母、川贝母","天花粉、栀子"],"a":3,"e":"知母清热滋阴润燥，川贝母润肺化痰，合用善治阴虚劳嗽、肺燥干咳少痰，如二母散。，为润燥止咳常用药对。"},{"q":"性微寒的行气药是","o":["木香","香附","沉香","薤白","枳实"],"a":4,"e":"枳实苦辛酸，性微寒，破气消积、化痰除痞，为行气药中少见的微寒之品，余多偏温。，为破气消积要药。"},{"q":"主治妇女虚寒证崩漏下血、胎漏的药是","o":["白及","艾叶","三七","大蓟","白茅根"],"a":1,"e":"艾叶辛苦温，温经止血、散寒止痛，为妇科虚寒性崩漏下血、胎漏之要药，又可安胎。，炒炭止血力增。"},{"q":"具有调和营卫之效的配伍是","o":["金银花与连翘","大黄与芒硝","麻黄与桂枝","桂枝与白芍","桂枝与甘草"],"a":3,"e":"桂枝解肌发表、温通卫阳，白芍敛阴和营，一散一收，共奏调和营卫之功，如桂枝汤。，为调和营卫之基础方。"},{"q":"既能温经止血，又能温中止痛的药物是","o":["干姜","炮姜","生姜","白及","艾叶"],"a":1,"e":"炮姜苦辛温，温经止血、温中止痛，善治虚寒性吐血便血、崩漏及脘腹冷痛，为干姜炮制品。"},{"q":"苦泄性平，袪风湿而善达四肢经络，通利关节，尤宜于风湿热痹，肩臂、关节酸痛麻木的药物是","o":["桑枝","防己","豨莶草","秦艽","威灵仙"],"a":0,"e":"桑枝苦平，祛风湿、利关节，善达四肢经络而走上肢，尤宜风湿热痹、肩臂酸痛麻木。，为治上肢痹痛要药。"},{"q":"味咸辛，性平，息风止痉兼能化痰，适用于惊风、癫痫夹有痰热的是","o":["地龙","全蝎","蜈蚣","僵蚕","钩藤"],"a":3,"e":"僵蚕咸辛平，息风止痉、祛风止痛、化痰散结，善治惊风癫痫夹痰热及风热头痛，又可退目翳。"},{"q":"海藻的功效是","o":["消痰软坚","降逆止呕","泻肺平喘","燥湿化痰","祛风止痛"],"a":0,"e":"海藻苦咸寒，消痰软坚散结、利水消肿，为治瘿瘤、瘰疬之常用药，如海藻玉壶汤。，反甘草。"},{"q":"补骨脂具有的功效是","o":["重镇安神、纳气平喘","温肾助阳、纳气平喘","疏肝理气、纳气平喘","温肾助阳、润肠通便","温肾助阳、燥湿止带"],"a":1,"e":"补骨脂辛苦温，温肾助阳、固精缩尿、温脾止泻、纳气平喘，治肾阳虚之喘咳，为治五更泻要药。"},{"q":"治疗瘰疬、瘿瘤等证的药物具有的药味是","o":["苦","甘","咸","涩","淡"],"a":2,"e":"咸能软坚散结、泻下，故瘰疬、瘿瘤、痰核等结块之证多用咸味药，如牡蛎、海藻。，为软坚散结之依据。"},{"q":"具有行气、燥湿、消积、降气平喘功效的药物是","o":["紫苏叶","厚朴","砂仁","香附","白豆蔻"],"a":1,"e":"厚朴苦辛温，燥湿消痰、下气除满，兼具行气、燥湿、消积、降气平喘之功，为消胀要药。"},{"q":"如下炮制后不能降低毒副作用的中药是","o":["斑蝥米炒","砒石升华","巴豆制霜","马兜铃蜜炙","千金子制霜"],"a":1,"e":"砒石升华是提纯精制过程，使三氧化二砷纯度更高，毒性并未降低，反更峻烈，不可视为减毒。"},{"q":"既可凉血止血，又能清肝明目的药物是","o":["大蓟","槐花","白及","苎麻根","白茅根"],"a":1,"e":"槐花苦微寒，凉血止血、清肝泻火，既治血热便血痔血，又治肝热目赤头痛，善清下焦。，为痔血要药。"},{"q":"防风的功效不包括","o":["胜湿","止痉","止痛","祛风","止呕"],"a":4,"e":"防风辛甘微温，祛风解表、胜湿止痛、止痉，无止呕之功，止呕多属生姜、半夏、藿香。，为祛风通用之品。"},{"q":"治感冒夹惊，风热头痛，最宜选用的药是","o":["僵蚕","天麻","钩藤","珍珠","羚羊角"],"a":2,"e":"钩藤甘凉入肝，清热平肝、息风定惊，药典明载其治感冒夹惊、小儿惊啼，又清头目风热而止头痛，故兼风热头痛者最宜。"},{"q":"外感风热，应选择何种性味的药物","o":["辛、温","辛、凉","甘、寒","苦、寒","甘、温"],"a":1,"e":"辛能发散、凉可清热，辛凉之品疏散风热而不助热，正合外感风热邪在卫表、宜辛以散之、凉以清之的病机。"},{"q":"石膏煎服的用量是","o":["5～10g","10～15g","10～20g","10～30g","15～60g"],"a":4,"e":"石膏质重沉降，非大剂不能胜热，煎服15～60g，宜打碎先煎，量小则力薄难奏清热泻火之效。"},{"q":"能祛风痰，善治中风，口眼㖞斜的药物是","o":["前胡","白前","旋覆花","白附子","胖大海"],"a":3,"e":"白附子辛温，善祛风痰、止痉搐，其性上行，为治中风口眼㖞斜、痰厥头痛之要药，故风痰阻络者首选。"},{"q":"既能补血，又能活血的药是","o":["红花","当归","川芎","何首乌","熟地黄"],"a":1,"e":"当归甘辛温，补血之中兼能活血，补而不滞，为补血活血、调经止痛之要药，血虚兼瘀者尤宜。"},{"q":"治疗心阴虚，虚热上扰之心悸、失眠者，宜选用","o":["黄精","天冬","鳖甲","百合","南沙参"],"a":3,"e":"百合甘寒，入心肺经，养阴润肺、清心安神，善治心肺阴虚、虚热内扰之心悸失眠、精神恍惚。"},{"q":"半夏与陈皮合用可以增强燥湿化痰的作用，属于哪种配伍关系","o":["相畏","相杀","相须","相反","相恶"],"a":2,"e":"两药同属辛温燥湿化痰之品，性能功效相似，合用则协同增效，此即七情中的相须；相使为主辅相配、辅药增效。"},{"q":"下列不属于硫黄适用范围的是","o":["疥癣","湿疹","阴疽疮疡","虚寒便秘","虫蛇咬伤"],"a":4,"e":"硫黄酸温有毒，外用解毒杀虫止痒，内服补火助阳、润肠通便，故疥癣、湿疹、阴疽疮疡与虚寒便秘均在其适用范围。"},{"q":"可以作为麻醉剂使用的止咳平喘药是","o":["川乌","草乌","姜黄","蟾酥","洋金花"],"a":4,"e":"洋金花辛温有毒，所含东莨菪碱能阻断M胆碱受体，故有麻醉止痛之功，可用于手术麻醉，又能止咳平喘。"},{"q":"药物四气确定的依据是","o":["从人体的感官感觉出来的","从疾病的性质中总结出来的","从药物作用于机体所发生的反应概括出来的","从药物生长的气候环境总结出来的","从药物的主治中总结出来的"],"a":2,"e":"四气由药物作用于人体后所出现的反应概括而来，服后身热者为温、身冷者为寒，与药物的形色及生长环境无关。"},{"q":"能祛风止痛，可用治风湿痹痛的药物是","o":["菊花","柴胡","桑叶","淡豆豉","蔓荆子"],"a":4,"e":"蔓荆子辛苦微寒，体轻上浮，善疏散风热、清利头目，兼能祛风止痛而通利关节，故风湿痹痛可用。"},{"q":"妊娠禁用的药物不包括的是","o":["巴豆","肉桂","莪术","三棱","麝香"],"a":1,"e":"妊娠禁用药多为毒性峻烈或破血逐瘀之品，巴豆、莪术、三棱、麝香皆属之；肉桂辛热助阳动血，列为慎用而非禁用。"},{"q":"气滞妊娠呕恶、不思饮食、脘腹胀闷、胎动不安者，治应首选的药物是","o":["生姜","厚朴","竹茹","砂仁","黄芩"],"a":3,"e":"砂仁辛温芳香，化湿醒脾、行气宽中，兼能理气安胎，气机调畅则呕恶止、胎自安，为气滞胎动不安之要药。"},{"q":"琥珀入药用法多为","o":["先煎","包煎","另煎","烊化兑服","研末冲服"],"a":4,"e":"琥珀为化石样树脂，质地坚脆难溶，入煎剂有效成分不易煎出，故研末冲服，每次1.5～3g。"},{"q":"合欢皮与首乌藤的安神作用特点是","o":["合欢皮祛痰开窍，首乌藤养血补心","合欢皮解郁悦心，首乌藤补养阴血","合欢皮清心凉肝，首乌藤滋养心肝","合欢皮潜纳浮阳，首乌藤补气养血","合欢皮交通心肾，首乌藤疏肝理气"],"a":1,"e":"合欢皮甘平，善解肝郁、悦心安神；首乌藤甘平，养血安神而补养阴血，二药安神途径一解郁、一养虚。"},{"q":"具强心利尿作用，但有毒，服用不宜过量的药物是","o":["滑石","通草","香加皮","泽泻","猪苓"],"a":2,"e":"香加皮辛苦温有毒，含强心苷，能强心利尿、祛风湿，作用峻烈，用量宜小，过量可致心律失常。"},{"q":"生地黄与玄参除能清热凉血外，又均能","o":["定惊","养阴","活血","散结","透疹"],"a":1,"e":"二药皆甘苦寒，清热凉血之外均能养阴生津；生地偏于凉血养阴，玄参长于降火解毒散结。"},{"q":"肺虚久咳、咽痛失音，最宜选用的药是","o":["蝉蜕","射干","青果","桔梗","诃子"],"a":4,"e":"诃子苦酸涩平，归肺与大肠经，能敛肺止咳、利咽开音，又涩肠止泻，故肺虚久咳、咽痛失音者最宜。"},{"q":"黄连与石膏的共同主治是","o":["胃火牙痛","湿热泻痢","血热吐衄","目赤肿痛","骨蒸劳热"],"a":0,"e":"黄连大苦大寒清胃火，石膏辛甘大寒清胃热，二药皆入胃经，故同可治胃火炽盛之牙痛、头痛。"},{"q":"具有发散作用的药味是","o":["咸","酸","苦","辛","甘"],"a":3,"e":"辛味能散能行，主发散、行气行血，解表透邪之品多取辛味；酸收、苦泄、甘缓、咸软各有所主。"},{"q":"既能止血，又具补虚之功的药物是","o":["白及","蒲黄","地榆","侧柏叶","仙鹤草"],"a":4,"e":"仙鹤草苦涩平，收敛止血之馀能补虚强壮，故出血日久兼气虚体倦者尤宜，为止血药中兼补之品。"},{"q":"地锦草与马齿苋相同的功效是","o":["清热燥湿","收敛止血","利湿退黄","凉血止痢","清肝明目"],"a":3,"e":"二药皆酸寒入大肠，清热解毒而凉血止痢，为热毒血痢、泄泻之常用；利湿退黄仅为地锦草之长。"},{"q":"山茱萸急救固脱的用量是","o":["1～3g","3～6g","6～12g","20～30g","60～120g"],"a":3,"e":"山茱萸酸涩微温，固脱须用大剂，急救固脱20～30g，常规煎服仅6～12g，量小则固摄无力。"},{"q":"桑螵蛸与海螵蛸的共同功效是","o":["收敛止血","制酸止痛","固精止遗","收湿敛疮","补肾助阳"],"a":2,"e":"桑螵蛸补肾固精缩尿，海螵蛸涩精止带，二药皆能固精止遗；制酸止痛、收湿敛疮独属海螵蛸。"},{"q":"柴胡的功效是","o":["利咽","透疹","疏肝解郁","凉血止血","清利头目"],"a":2,"e":"柴胡辛苦微寒，入肝胆经，能疏散退热、疏肝解郁、升举阳气，故肝郁气滞、月经不调常用。"},{"q":"治疗外感风热，咳嗽痰多，咽痛音哑，胸闷不舒者，应首选的药物是","o":["百部","桔梗","川贝母","苦杏仁","旋覆花"],"a":1,"e":"桔梗苦辛平，专入肺经，开宣肺气、祛痰利咽，又能载药上行，故外感咳嗽痰多、咽痛音哑者首选。"},{"q":"枳实配白术常用于治疗","o":["肝郁气滞","脾虚气滞","痰湿阻滞","寒凝气滞","肺气壅滞"],"a":1,"e":"枳实破气消痞，白术健脾燥湿，一消一补，行气而不伤正，为治脾虚气滞、食少腹胀之枳术丸法。"},{"q":"消食化积，又能疏肝理气的药物是","o":["青皮","香附","瓜蒌","郁金","麦芽"],"a":4,"e":"麦芽甘平，消食健胃之中兼能疏肝解郁、回乳消胀，尤宜米面薯芋食积及肝郁胁痛、断乳胀痛。"},{"q":"泻水逐饮，药力峻猛，尤“能泄脏腑之水湿”的药物是","o":["甘遂","京大戟","芫花","巴豆霜","牵牛子"],"a":1,"e":"京大戟苦寒有毒，泻水逐饮而力峻，善泄脏腑之水湿，主治水肿臌胀、胸胁停饮；甘遂则偏行经隧之水。"},{"q":"砂仁入汤剂煎煮时应","o":["先煎","后下","另煎","包煎","烊化"],"a":1,"e":"砂仁气味芳香，有效成分含挥发油，久煎则香气散失、药力大减，故宜后下，于群药煎好前5～10分钟投入。"},{"q":"具有化湿、解暑功效的药组是","o":["广藿香、佩兰","苍术、厚朴","砂仁、白豆蔻","陈皮、青皮","茯苓、玉竹"],"a":0,"e":"广藿香、佩兰皆辛香微温，芳香化湿而解暑发表，为暑湿、湿温初起及湿阻中焦之要药。，故夏月感寒挟湿者多用之。"},{"q":"下列药物尤善治寒邪偏盛之风湿痹痛的是","o":["独活","川乌","木瓜","乌梢蛇","威灵仙"],"a":1,"e":"川乌辛苦热，有大毒，祛风除湿、温经止痛之力峻，其性疏利开通，善逐寒湿，故寒邪偏盛之痹痛用之最宜。"},{"q":"可用治久泻、久痢的药组是","o":["山茱萸、桑螵蛸","覆盆子、桑螵蛸","金樱子、覆盆子","金樱子、石榴皮","山茱萸、石榴皮"],"a":3,"e":"金樱子酸涩，固精缩尿、涩肠止泻；石榴皮酸涩温，涩肠止泻、杀虫，二药同能涩肠，故久泻久痢可投。"},{"q":"既可以疏肝气，又可以理脾胃之气的药物是","o":["枳实","沉香","薤白","柿蒂","佛手"],"a":4,"e":"佛手辛苦温，气清香，能疏肝解郁、理气和中、燥湿化痰，肝胃气滞与脾胃气滞皆可调之，故兼理两焦之气。"},{"q":"胸腹水肿实证兼喘咳者，宜选用","o":["茯苓","泽泻","昆布","海藻","葶苈子"],"a":4,"e":"葶苈子辛苦大寒，专泻肺中痰水，泻肺平喘、利水消肿，故胸腹积水而兼喘咳、不得平卧者用之。"},{"q":"乳香、没药均有的功效是","o":["活血定痛、行气解郁","活血止痛、通经活络","活血定痛、消肿生肌","活血定痛、凉血消痈","祛风通络，行气解郁"],"a":2,"e":"乳香、没药皆辛苦温，同入心肝血分，活血止痛、消肿生肌，为跌打疮疡常用；行气解郁唯乳香有之。"},{"q":"干姜配伍附子，可降低附子的毒性，属于","o":["相须","相使","相恶","相杀","相反"],"a":3,"e":"干姜与附子同用，能减附子之毒而制其峻烈，属于相杀；相畏则指附子畏干姜，为被减毒一方的表述。"},{"q":"能益气活血、通脉平喘的药物是","o":["饴糖","沙棘","红景天","绞股蓝","刺五加"],"a":2,"e":"红景天甘涩寒，益气活血、通脉平喘，用于气虚血瘀之胸痹心痛、中风偏瘫及肺虚喘咳。，高原缺氧者亦常用。"},{"q":"治疗噫气，呕吐，旋覆花配伍赭石，可增强","o":["凉血止血之功","消痰行水之功","平肝潜阳之功","降逆下气之功","重镇安神之功"],"a":3,"e":"旋覆花降气消痰、行水止呕，赭石质重沉降、重镇降胃，二药一宣一降，协同使上逆之气下行。"},{"q":"祛风湿药的主要功效是","o":["祛除风湿，舒筋活络","祛除风湿，活血止痛","祛除风湿，强筋健骨","祛除风湿，解除痹痛","祛除风湿，温经止痛"],"a":3,"e":"祛风湿药味多辛苦，能祛除留着于肌肉、经络、筋骨的风湿之邪，解除痹痛，兼有舒筋、通络、强筋骨之别。"},{"q":"下列各项中，用药方法错误的是","o":["薄荷后下","车前子包煎","龙骨先煎","人参另煎","旋覆花烊化"],"a":4,"e":"旋覆花有绒毛，入煎易刺激咽喉致咳，故须包煎；烊化专用于阿胶等胶类药，二者不可混用。"},{"q":"能燥湿化痰，治顽痰咳嗽宜用","o":["百部","款冬花","浙贝母","天南星","桑白皮"],"a":3,"e":"天南星苦辛温燥，燥湿化痰之力强，善治顽痰胶结之咳嗽痰多、胸膈痞闷，故顽痰者宜之。"},{"q":"既能发汗解表，又能平冲降气的药物是","o":["荆芥","防风","细辛","白芷","桂枝"],"a":4,"e":"桂枝辛甘温，发汗解肌以解表，又能温通经脉、平冲降逆，故气上冲逆、心悸奔豚者用之。"},{"q":"石膏治疮疡不敛，湿疹，水火烫伤，其用法是","o":["生石膏，外用","生石膏，冲服","煅石膏，内服","煅石膏，外用","生石膏，打碎先煎"],"a":3,"e":"石膏生用清热泻火，煅后寒性减而收湿敛疮生肌之力著，故疮疡不敛、湿疹、烫伤宜取煅者研末外撒。"},{"q":"半边莲的功效是","o":["利湿退黄","利尿消肿","祛瘀止痛","祛风止痒","利湿通淋"],"a":1,"e":"半边莲甘淡寒，清热解毒而利尿消肿，内服外用皆可治毒蛇咬伤、疔疮肿毒及水肿、腹水。"},{"q":"风寒表证、风热表证均常配伍使用的药对是","o":["麻黄，桂枝","羌活，白芷","紫苏叶，生姜","荆芥，防风","藁本，苍耳子"],"a":3,"e":"荆芥、防风皆辛而微温，药性平和，发散风寒而兼散风热，故风寒、风热表证皆可配用。，为解表通用之药对。"},{"q":"为增强牡丹皮的活血祛瘀作用，入汤剂宜","o":["盐水炙","酒炙","醋炙","姜汁炙","蜜炙"],"a":1,"e":"牡丹皮生用清热凉血，酒炙则借酒力上行入血，活血祛瘀之力增强，故欲行瘀者宜酒炙。，与生用凉血之功各有专主。"},{"q":"内服能散寒劫痰平喘、截疟的药是","o":["砒石","硫黄","铅丹","升药","轻粉"],"a":0,"e":"砒石辛大热有大毒，内服能劫痰平喘、截疟，虚寒哮喘、疟疾可用，然极毒须慎，用量以毫厘计。"},{"q":"不具止血和利尿双重功效的药物是","o":["大蓟","小蓟","蒲黄","白茅根","血余炭"],"a":0,"e":"大蓟专于凉血止血、散瘀解毒消痈，并无利尿之力；兼能通淋利尿者是小蓟、白茅根、蒲黄与血余炭。"},{"q":"金银花清热解暑，治暑热烦渴，宜选用","o":["制露","生用","蜜炙","酒炙","研粉"],"a":0,"e":"金银花露系花经蒸馏制得，气味清轻，长于清热解暑、清利头目，故暑热烦渴、小儿热疖宜之。"},{"q":"两药合用，一种药物能使另一种药物原有的功效降低或丧失，这种配伍关系是","o":["相反","相畏","相杀","相恶","相使"],"a":3,"e":"相恶指两药合用，一药使另一药原有功效降低甚至丧失，如人参恶莱菔子；相反则是配伍后产生毒性反应。"},{"q":"生地黄不具有的功效是","o":["凉血","养阴","生津","清热","解毒"],"a":4,"e":"生地黄甘苦寒，功能清热凉血、养阴生津，并无解毒散结之力，解毒散结系玄参所长。，二者临床常相须为用。"},{"q":"旋覆花配赭石同用，可增强","o":["行水之功","潜阳之功","凉血止血之功","镇惊安神之功","降逆下气之功"],"a":4,"e":"旋覆花苦降，善降气消痰止呕；赭石重镇降胃。二药相须，使上逆之气下行，降逆下气之功显著增强。"},{"q":"陈皮与佛手相同的功效是","o":["疏肝破气","理气消积","祛寒止痛","燥湿化痰","健脾利水"],"a":3,"e":"陈皮理气健脾、燥湿化痰，佛手疏肝和胃、燥湿化痰，二药同具燥湿化痰之功，皆治痰湿咳嗽、胸闷。"},{"q":"既能敛肺止咳，又能生津止渴的药物是","o":["乌梅","诃子","石榴皮","肉豆蔻","赤石脂"],"a":0,"e":"乌梅酸涩平，敛肺止咳、涩肠止泻、安蛔止痛，又能生津止渴，故肺虚久咳、虚热消渴皆宜。"},{"q":"瞿麦为治淋证常用药，除利尿通淋外，还能","o":["祛风止痒","杀虫，止痒","通气下乳","活血通经","清心除烦"],"a":3,"e":"瞿麦苦寒，利尿通淋而性较猛，兼能活血通经，故血瘀经闭、淋证涩痛均可选用，孕妇忌用。"},{"q":"龙眼肉的功效是","o":["健脾益气，养血滋阴","益气复脉，滋阴养血","滋阴补血，生津润燥","养心益肝，宁心安神","补益心脾，养血安神"],"a":4,"e":"龙眼肉甘温，归心脾经，补益心脾、养血安神，为治心脾两虚、气血不足之失眠健忘、心悸怔忡之良品。"},{"q":"劳嗽久咳，倦怠乏力，食欲不振、神疲体倦、舌干苔少者，宜首选","o":["石斛","黄精","百合","麦冬","玉竹"],"a":1,"e":"黄精甘平，补气养阴、健脾润肺益肾，气阴两虚而见劳嗽久咳、倦怠食少、舌干苔少者最为合宜。"},{"q":"既能燥湿祛风，又能杀虫止痒的药物是","o":["硫黄","苦参","白矾","土槿皮","蛇床子"],"a":4,"e":"蛇床子辛苦温，燥湿祛风、杀虫止痒，又能温肾壮阳，故阴痒湿疹、湿痹腰痛及阳痿宫冷皆可用。"},{"q":"气味芳香、成分易挥发的药物宜","o":["先煎","后下","布包煎","另煎","烊化兑服"],"a":1,"e":"气味芳香、含挥发油之品久煎则有效成分挥散，故宜后下，如薄荷、砂仁、豆蔻，于群药煎成前投入。"},{"q":"治疗肾阴亏虚，眩晕耳鸣，内热消渴，最宜选用药物是","o":["麦冬","天冬","百合","玉竹","南沙参"],"a":1,"e":"天冬甘苦寒，养阴润燥、清肺生津，又能滋肾阴、退虚热，故肾阴亏虚之眩晕耳鸣、内热消渴宜之。"},{"q":"下列哪一组性味的药物，作用趋向一般属于升浮","o":["甘、辛、凉","辛、苦、热","辛、甘、温","甘、淡、寒","酸、咸、热"],"a":2,"e":"辛甘温热之品，辛能发散、甘能补益升提、温能助阳行散，其性向上向外，故作用趋向属升浮。"},{"q":"枳实可用于治疗","o":["月经不调","虫积腹痛","胁肋疼痛","胃寒呕吐","胃肠积滞"],"a":4,"e":"枳实苦辛微寒，破气消积、化痰除痞，善通胃肠积滞，故痞满胀痛、便秘后重者用之。，此其破气导滞之力所主。"},{"q":"能益气助阳的药物是","o":["党参","人参","附子","太子参","吴茱萸"],"a":1,"e":"人参甘微苦微温，大补元气、复脉固脱，元气充则阳气自复，故气虚欲脱、阳衰肢冷者赖以益气助阳。"},{"q":"自然铜的功效是","o":["活血疗伤，散瘀止痛","破血逐瘀，续筋接骨","散瘀止痛，续筋接骨","活血消肿，舒筋活络","散结消肿，通络止痛"],"a":2,"e":"自然铜辛平，入肝经血分，散瘀止痛、续筋接骨，为骨折筋伤、瘀肿疼痛之要药，多煅用研末。"},{"q":"外用蚀疮去腐，内服劫痰平喘的药物是","o":["升药","砒石","轻粉","硼砂","红升丹"],"a":1,"e":"砒石辛大热大毒，外用蚀疮去腐、攻毒杀虫，内服劫痰平喘、截疟，腐蚀之力峻猛，用量极微。"},{"q":"马钱子的功效是","o":["活血疗伤，散瘀止痛","破血逐瘀，续筋接骨","散瘀止痛，接骨疗伤","活血消肿，舒筋活络","散结消肿，通络止痛"],"a":4,"e":"马钱子苦寒大毒，散结消肿、通络止痛，善治跌打损伤、痈疽肿毒及风湿顽痹、麻木瘫痪。"},{"q":"治外感风寒夹湿表证，头痛身痛者，首选的药物是","o":["荆芥","生姜","薄荷","紫苏叶","羌活"],"a":4,"e":"羌活辛苦温，气雄而散，发散风寒、祛风除湿止痛，善治风寒夹湿之表证及上半身头痛身痛。"},{"q":"雪莲花的功效是","o":["祛风湿，壮筋骨，解毒","祛风湿，强筋骨，补肾阳","祛风湿，强筋骨，安胎元","祛风湿，强筋骨，利水","祛风湿，补肝肾，强腰膝"],"a":1,"e":"雪莲花甘苦温，祛风湿、强筋骨、补肾阳，兼能调经止血，故痹痛、腰膝软弱、阳痿及月经不调可用。"},{"q":"既能解毒、除湿，又能通利关节的药物是","o":["金银花","蒲公英","鱼腥草","薏苡仁","土茯苓"],"a":4,"e":"土茯苓甘淡平，解毒除湿、通利关节，为治梅毒及汞中毒之要药，亦治湿热淋浊、带下、疮毒。"},{"q":"患者便秘，头晕头痛，烦躁易怒，惊痫抽搐，宜选用清肝泻火之","o":["大黄","芒硝","番泻叶","石膏","芦荟"],"a":4,"e":"芦荟苦寒，泻下通便而清肝火，故热结便秘兼肝经实火之头晕头痛、烦躁易怒、惊痫抽搐者宜之。"},{"q":"佩兰的功效是","o":["燥湿行气，温中止呕","燥湿行气，消积平喘","化湿行气，温中止呕","化湿开胃，发表解暑","燥湿温中，除痰截疟"],"a":3,"e":"佩兰辛平，芳香化湿、醒脾开胃，又能发表解暑，为治湿阻中焦、口中甜腻及暑湿表证之品。"},{"q":"五味子的主治病证不包括","o":["自汗盗汗","便血崩漏","遗精滑精","久泻不止","失眠多梦"],"a":1,"e":"五味子酸甘温，收敛固涩、益气生津、补肾宁心，主治久咳虚喘、自汗盗汗、遗精久泻及心悸失眠，便血崩漏非其所主。"},{"q":"治疗外感风寒兼脾胃气滞胸脘满闷、恶心呕逆者，宜首选","o":["荆芥","防风","白芷","细辛","紫苏"],"a":4,"e":"紫苏辛温，发表散寒、行气宽中，兼能安胎，故风寒表证而兼胸脘满闷、恶心呕逆者最为合宜。"},{"q":"能沉降的药物性味多为","o":["辛、酸、温","苦、咸、温","辛、甘、凉","甘、辛、温","酸、苦、寒"],"a":4,"e":"酸能收、苦能泄降、寒能清热，其性向下向内，故多主沉降；辛甘温热之品则主升浮。，故升降之性可由性味推断。"},{"q":"在补益气血方中，能发挥鼓舞气血生长作用的药物是","o":["干姜","附子","肉桂","丁香","吴茱萸"],"a":2,"e":"肉桂辛甘大热，补火助阳、引火归元，于补益气血方中少佐之，能鼓舞气血生长，取“阳生阴长”之意。"},{"q":"不具有安胎功效的药物是","o":["黄芩","黄连","紫苏叶","砂仁","杜仲"],"a":1,"e":"黄芩、紫苏叶、砂仁、杜仲皆能安胎；黄连大苦大寒，功能清热燥湿、泻火解毒，并无安胎之用。"},{"q":"既治水肿，小便不利，又治风湿痹证日久，腰膝酸痛的药物是","o":["千年健","桑寄生","五加皮","猪苓","防己"],"a":2,"e":"五加皮辛苦温，祛风湿、补肝肾、强筋骨，兼能利水，故痹证日久腰膝酸痛及水肿小便不利皆宜。"},{"q":"能破气消积功效的药物是","o":["陈皮","香附","枳实","沉香","川楝子"],"a":2,"e":"枳实苦辛微寒，破气之力峻，消积导滞、化痰除痞，气机壅实之胸腹胀满、食积便秘用之。"},{"q":"温肺化饮，善治寒饮喘咳的药物是","o":["花椒","干姜","肉桂","吴茱萸","小茴香"],"a":1,"e":"干姜辛热，温中散寒、回阳通脉，又能温肺化饮，寒饮伏肺之咳嗽气喘、痰多清稀者赖以温化。"},{"q":"骨碎补可用于腰痛脚弱、耳鸣耳聋，取其哪个功效","o":["通络止痛","活血疗伤","补肾强骨","散结消肿","破血逐瘀"],"a":2,"e":"骨碎补苦温，补肾强骨、续伤止痛，肾主骨生髓，肾充则骨健，故腰痛脚弱、耳鸣耳聋、牙痛久泻皆用之。"},{"q":"肉桂煎服的用量为","o":["1～3g","1～5g","3～6g","3～10g","3～15g"],"a":1,"e":"肉桂辛热，用量宜轻，煎服1～5g，宜后下或焗服；研末冲服每次1～2g，量过则助火伤阴。"},{"q":"性寒，滑肠通便，气虚便溏者慎用的药物是","o":["薄荷","牛蒡子","蝉蜕","升麻","柴胡"],"a":1,"e":"牛蒡子辛苦寒，疏散风热、宣肺透疹、解毒利咽，其性寒滑肠，故气虚便溏者慎用。，脾虚泄泻者尤当避之。"},{"q":"川乌的功效是","o":["祛风止痛，活血通络","祛风通络，凉血消肿","祛风通络，定惊止痉","祛风除湿，散寒止痛","祛风除湿，活血通络"],"a":3,"e":"川乌辛苦热有大毒，祛风除湿、温经止痛，为治风寒湿痹之猛药，须制用先煎以减毒。，不可生用内服。"},{"q":"长于清泻下焦湿热的药是","o":["黄芩","黄连","黄柏","马尾连","白鲜皮"],"a":2,"e":"黄柏苦寒沉降，善清下焦湿热，故湿热带下、热淋、足膝肿痛、湿疹湿疮多用，与黄芩清上、黄连清中相对。"},{"q":"少妇产后，因感冒未哺乳，致一侧乳房肿硬疼痛，因不愿服中药，外敷宜首选的药物是","o":["芒硝","大黄","鱼腥草","紫花地丁","大血藤"],"a":0,"e":"芒硝咸苦寒，外用清热消肿、软坚散结，研末外敷可消乳痈初起之肿硬疼痛，故不愿服药者取之外治。"},{"q":"功似火麻仁，兼行大肠气滞的药物是","o":["柏子仁","松子仁","桃仁","苦杏仁","郁李仁"],"a":4,"e":"郁李仁辛苦甘平，润肠通便类似火麻仁，兼能行大肠气滞而下气，又利水消肿，故肠燥便秘兼气滞者宜。"},{"q":"具有清热，解毒，滋阴功效的药物是","o":["生地黄","玄参","赤芍","牡丹皮","紫草"],"a":1,"e":"玄参甘苦咸寒，清热凉血、滋阴降火、解毒散结，故清热、解毒、滋阴三功兼备，为咽喉肿痛、瘰疬常用。"},{"q":"艾叶的道地产地是","o":["辽宁","广东","青海","四川","湖北"],"a":4,"e":"艾叶以湖北蕲州产者为佳，称蕲艾，其叶厚而香气浓，温经止血、散寒止痛之力著。，故处方多标蕲艾。"},{"q":"下列哪项不是温热性能所表示的作用","o":["温里","开窍","补火","温经","回阳"],"a":1,"e":"温热药多能温里散寒、补火助阳、温经通脉、回阳救逆；开窍乃辛香走窜、开通心窍之功，不属温热性能所表示的作用。"},{"q":"善祛经络风痰的药物是","o":["半夏","白前","芥子","天南星","旋覆花"],"a":3,"e":"天南星苦辛温，燥湿化痰而善走经络，祛风痰、止痉搐，故中风痰壅、口眼㖞斜、癫痫及经络风痰多用。"},{"q":"既能涩肠止泻，又能清热燥湿的药物是","o":["椿皮","刺猬皮","白鲜皮","石榴皮","地骨皮"],"a":0,"e":"椿皮苦涩寒，清热燥湿、收敛止带，兼能涩肠止泻、止血，故湿热带下、久泻久痢及崩漏便血可用。"},{"q":"功效有某种共性的药物配合应用，辅药能增强主药的疗效","o":["相反","相恶","相杀","相畏","相使"],"a":4,"e":"相使指功效有某种共性的两药配伍，以一味为主、另一味为辅，辅药能提高主药疗效，如黄芪配茯苓。"},{"q":"龟甲与鳖甲的共同功效是","o":["养血补心","益肾强骨","软坚散结","固经止崩","滋阴潜阳"],"a":4,"e":"龟甲滋阴潜阳、益肾强骨、养血补心；鳖甲滋阴潜阳、退热除蒸、软坚散结，滋阴潜阳为二者共有。"},{"q":"既能祛风通络，又能定惊止痉的药物是","o":["独活","防己","蕲蛇","海风藤","木瓜"],"a":2,"e":"蕲蛇甘咸温，性善走窜，内走脏腑、外彻皮肤，祛风通络而止痉，故顽痹麻木、口眼㖞斜、破伤风用之。"},{"q":"胃十二指肠溃疡者慎服，用量过大易致恶心呕吐的药物是","o":["半夏","桔梗","黄药子","苦杏仁","天南星"],"a":1,"e":"桔梗苦辛平，升散上行，过量易刺激胃气上逆而恶心呕吐，故胃及十二指肠溃疡者慎服。，入煎剂用量亦不宜过大。"},{"q":"下列哪项不属沉降药性范畴","o":["利水","潜阳","收敛","开窍","清火"],"a":3,"e":"沉降之性主下行向内，能利水渗湿、潜阳降逆、收敛固涩、清热泻火；开窍为辛香走窜上行之性，属升浮。"},{"q":"能渗湿利水，分清泌浊，治疗湿盛小便不利之水泻的药物是","o":["滑石","车前子","木通","通草","瞿麦"],"a":1,"e":"车前子甘寒，利水通淋而能分清泌浊，即“利小便以实大便”，故湿盛水泻、小便不利者用之最宜。"},{"q":"不属于解表药使用注意的是","o":["体虚汗多者忌服","淋病者慎用","热病津亏者忌服","疮疡初起兼表证者忌服","失血兼表证者慎服"],"a":3,"e":"解表药能发散透邪，疮疡初起兼表证者正宜用之，使邪从表解，故列其为忌服与常理相悖。"},{"q":"能温中降逆，补肾助阳的药物是","o":["丁香","附子","生姜","细辛","紫苏"],"a":0,"e":"丁香辛温，温中降逆、散寒止痛，又温肾助阳，故胃寒呃逆呕吐、脘腹冷痛及肾虚阳痿可用。"},{"q":"治疗痰热咳喘，中风痰迷，惊痫癫狂首选的药物是","o":["半夏","竹茹","竹沥","瓜蒌","川贝母"],"a":2,"e":"竹沥甘寒滑利，善清热豁痰、定惊利窍，痰热咳喘、中风痰迷、惊痫癫狂者取之；寒痰及脾虚便溏者忌。"},{"q":"既能清热凉血，又能活血化瘀的药物是","o":["紫花地丁","生地黄","玄参","牡丹皮","水牛角"],"a":3,"e":"牡丹皮苦辛微寒，清热凉血之中兼能活血化瘀，使热清而血行不致留瘀，故血热兼瘀者宜之。"},{"q":"陈皮主要用于","o":["脾胃气滞证","肝郁气滞证","肝寒气滞证","寒凝气滞证","食积气滞证"],"a":0,"e":"陈皮辛苦温，理气健脾、燥湿化痰，主入脾胃，故脾胃气滞之脘腹胀满、食少吐泻最为适用。"},{"q":"反映药物影响人体阴阳盛衰倾向的中药性能是","o":["四气","五味","升降浮沉","归经","毒性"],"a":0,"e":"四气即寒热温凉，反映药物对人体阴阳盛衰、寒热病理变化的影响倾向，寒凉清热、温热散寒。"},{"q":"善治胃痛吐酸、湿疮湿疹的药是","o":["山茱萸","覆盆子","桑螵蛸","金樱子","海螵蛸"],"a":4,"e":"海螵蛸咸涩微温，收敛止血、涩精止带、制酸止痛、收湿敛疮，故胃痛吐酸与湿疮湿疹皆宜。"},{"q":"主入中焦，功能温经止血的药物是","o":["生姜","干姜","炮姜","艾叶","三七"],"a":2,"e":"炮姜苦辛温，主入中焦脾胃，温经止血、温中止痛，为虚寒性出血及脾胃虚寒之要药。，与生姜、干姜同源而异用。"},{"q":"乳香的入药部位是","o":["树脂","根茎","果实","树皮","花粉"],"a":0,"e":"乳香系橄榄科植物乳香树皮部渗出的干燥树脂，与没药同属树脂类，功能活血止痛、消肿生肌。"},{"q":"功能补气升阳，善治中气下陷的药物是","o":["升麻","柴胡","黄芪","党参","人参"],"a":2,"e":"黄芪甘温，补气升阳、益卫固表，善升举清阳，故中气下陷之脏器脱垂、久泻脱肛者以之为要药。"},{"q":"酸枣仁的主治病症不包括","o":["惊悸多梦","虚烦不眠","津伤口渴","体虚多汗","肠燥便秘"],"a":4,"e":"酸枣仁甘酸平，养心益肝、安神敛汗，主治虚烦不眠、惊悸多梦、体虚多汗；肠燥便秘为柏子仁所主。"},{"q":"下列哪味是治疗肝肾亏虚胎动不安之要药","o":["络石藤","香加皮","桑寄生","五加皮","千年健"],"a":2,"e":"桑寄生苦甘平，补肝肾、强筋骨、祛风湿，又能安胎，故肝肾亏虚、冲任不固之胎动不安用之最宜。"},{"q":"具有止血、安胎功效的药组是","o":["紫苏叶、桑寄生","砂仁、菟丝子","黄芩、苎麻根","杜仲、续断","白术、小蓟"],"a":2,"e":"黄芩清热安胎，苎麻根凉血止血安胎，二药皆能止血安胎，故血热胎动不安、胎漏下血者宜之。"},{"q":"淫羊藿、巴戟天的相同功效是","o":["补肾阳、强筋骨、祛风湿","补肾阳、益精血、托疮毒","补肾阳、止咳喘、退虚热","补肝肾、强筋骨、安胎元","补肝肾、止崩漏、益气血"],"a":0,"e":"二药皆辛甘温，补肾阳、强筋骨、祛风湿，故肾阳虚之阳痿不孕、筋骨痿软及风湿痹痛皆可用。"},{"q":"外用具有腐蚀赘疣作用的药物是","o":["鸦胆子","青蒿","白头翁","马齿苋","地锦草"],"a":0,"e":"鸦胆子苦寒有毒，外用腐蚀赘疣，寻常疣、鸡眼可捣烂敷之；内服则清热解毒、截疟止痢。"},{"q":"下列除哪项外均是概括中药作用的基本性质和特征","o":["归经","四气五味","升降浮沉","毒性","配伍七情"],"a":4,"e":"中药性能包括四气、五味、升降浮沉、归经与毒性，概括药物的基本性质与特征；配伍七情属配伍关系，不属性能。"},{"q":"陈皮、枳实的共同功效为","o":["健脾","化痰","散寒","杀虫","利水"],"a":1,"e":"陈皮理气健脾、燥湿化痰，枳实破气消积、化痰除痞，二药理气之中同能化痰，故痰湿中阻者常相配。"},{"q":"生姜解生半夏毒的配伍关系是","o":["相使","相须","相杀","相恶","相反"],"a":2,"e":"生姜能杀生半夏之毒，故属相杀；从被减毒一方而言则称半夏畏生姜，即相畏，二者为同一配伍的不同表述。"},{"q":"为凉肝息风止痉之要药，因其清热力强，心肝火盛，热极生风者尤宜的是","o":["天麻","牛黄","蜈蚣","钩藤","羚羊角"],"a":4,"e":"羚羊角咸寒，平肝息风、清肝明目、清热解毒，清热力峻，心肝火盛、热极生风之惊厥抽搐者尤宜。"},{"q":"为治泻痢要药的药物是","o":["知母","黄芩","黄连","白术","茯苓"],"a":2,"e":"黄连大苦大寒，清热燥湿、泻火解毒之力强，尤善清胃肠湿热，故为治湿热泻痢之要药。，后世治痢方多以为君药。"},{"q":"因气味香烈，入煎剂需炮制去油减少对消化道刺激的药是","o":["莪术","苏木","没药","血竭","延胡索"],"a":2,"e":"没药为树脂，气味香烈，含挥发油，入煎易刺激消化道而致呕恶，故多炮制去油后入药。，醋制后刺激性更减。"},{"q":"治寒湿偏重之腰腿疼痛较著者，宜选","o":["羌活","络石藤","独活","豨莶草","防己"],"a":2,"e":"独活辛苦微温，性善下行，祛风湿、止痛，主入肾经而走下焦，故腰腿疼痛、下肢痹痛较著者宜之。"},{"q":"骨碎补可用于治疗","o":["皮肤瘙痒","痈疽疮毒","风湿顽痹","血瘀经闭","肾虚牙痛久泻"],"a":4,"e":"骨碎补苦温，补肾强骨，肾主骨、齿为骨之余，故肾虚牙痛、久泻及腰痛脚弱、跌扑骨折皆可用。"},{"q":"不属于百合功效的是","o":["养肺阴","润肺燥","滋肾阴","养胃阴","清心安神"],"a":2,"e":"百合甘寒，养肺阴、润肺燥、养胃阴、清心安神，并无滋肾之力，滋肾阴者当属天冬、熟地之类。"},{"q":"大剂量使用会损害视神经的药物是","o":["蒲公英","紫花地丁","贯众","野菊花","板蓝根"],"a":2,"e":"贯众苦微寒，清热解毒、止血杀虫，含绵马酸类成分，大剂量或久服可损害视神经而致视力障碍。"},{"q":"黄芩不具有的功效是","o":["燥湿","泻火","解毒","止血","除蒸"],"a":4,"e":"黄芩苦寒，清热燥湿、泻火解毒、止血、安胎；除蒸退虚热为知母、黄柏、青蒿之功。，故血热胎动不安者亦用之。"},{"q":"治疗湿热带下，苦参常配伍的药组是","o":["瞿麦、黄芩","茵陈、石韦","木通、金银花","白鲜皮、地肤子","硼砂、土荆皮"],"a":3,"e":"苦参苦寒，清热燥湿、杀虫止痒，治湿热带下常与白鲜皮、地肤子相配，以增燥湿止痒之力。"},{"q":"应用麻黄根时宜注意的是","o":["孕妇忌用","儿童忌用","肺虚者忌用","有表邪者忌用","年老体弱者忌用"],"a":3,"e":"麻黄根甘涩平，功专止汗，敛汗之力强，表邪未解者用之有闭门留寇之弊，故忌用。，虚人自汗盗汗方为的对。"},{"q":"中药驱虫药宜","o":["睡前服","小剂量频服","空腹顿服","饭后服","随时服"],"a":2,"e":"驱虫药宜空腹顿服，使药力直接作用于虫体而集中驱杀，服药期间忌食油腻肥甘。，且宜清晨空腹时服用。"},{"q":"内服涩肠止泻，外用收湿敛疮的药物是","o":["乌梅","禹余粮","赤石脂","罂粟壳","金樱子"],"a":2,"e":"赤石脂甘涩温，内服涩肠止泻、收敛止血，外用收湿敛疮生肌，为久泻久痢、疮疡不敛常用。"},{"q":"不具备解毒消肿之功的药物是","o":["大蓟","小蓟","白及","大黄","紫珠叶"],"a":2,"e":"白及苦涩微寒，收敛止血、消肿生肌，其消肿在于生肌敛疮而非解毒，故不具解毒消肿之功。"},{"q":"硫黄性温，具有补火助阳功效，内服适用于下列哪项病证","o":["疥癣","湿疹","疮疡","阳痿","风寒湿痹"],"a":3,"e":"硫黄酸温，内服补火助阳，故肾阳不足之阳痿、虚寒便秘可用；疥癣湿疹疮疡则取外用解毒杀虫之功。"},{"q":"知母用治阴虚火旺之骨蒸潮热，是因其能","o":["清热泻火","除烦止渴","润燥通便","滋阴降火","收湿敛疮"],"a":3,"e":"知母苦甘寒，既能清热泻火，又能滋阴润燥，故阴虚火旺、骨蒸潮热者取其滋阴降火之功。"},{"q":"青皮的功效为","o":["行气止痛","降气止呃","行气宽中","开郁醒脾","疏肝破气"],"a":4,"e":"青皮苦辛温，性较峻烈，疏肝破气、消积化滞，故肝郁气滞之胸胁胀痛、食积腹痛及癥瘕积聚用之。"},{"q":"风湿痹痛，腰膝酸软，小儿行迟，宜选用","o":["五加皮","木瓜","桑枝","络石藤","海风藤"],"a":0,"e":"五加皮辛温，祛风湿、补肝肾、强筋骨，故痹证日久腰膝酸软、小儿行迟及水肿小便不利皆宜。"},{"q":"鹿茸的药性是","o":["甘、咸，温","甘、苦，温","辛、苦，温","酸、苦，温","辛、甘，温"],"a":0,"e":"鹿茸甘咸温，归肾肝经，补肾阳、益精血、强筋骨，温而不燥，为温补肾阳、生精益髓之要药。"},{"q":"肉豆蔻治泻痢，是取其何功效","o":["燥湿，健脾","燥湿，升阳","温中，涩肠","温中，升阳","温中，燥湿"],"a":2,"e":"肉豆蔻辛温，温中行气、涩肠止泻，故脾胃虚寒之久泻久痢用之，煨用则涩肠之力更著。，又能温中行气以消胀满。"},{"q":"桑叶用于风热感冒，或温病初起，温热犯肺，发热、咽痒、咳嗽等症，常相须为用的药物是","o":["菊花","柴胡","升麻","淡豆豉","葛根"],"a":0,"e":"桑叶、菊花皆甘苦微寒，疏散风热、清肺润燥、平肝明目，二药相须为用，为风热犯肺之常用配伍。"},{"q":"医生用桔梗治疗癃闭、便秘，因其能","o":["利水消肿","润肠通便","开宣肺气","荡涤肠胃","釜底抽薪"],"a":2,"e":"桔梗开宣肺气，肺气宣通则水道通调，故能通利小便、下气通便，此即“提壶揭盖”之法。"},{"q":"具有燥湿化痰作用的药物是","o":["青皮","枳实","陈皮","檀香","川楝子"],"a":2,"e":"陈皮辛苦温，理气健脾、燥湿化痰，为治痰湿壅滞、咳嗽痰多及脾胃气滞之常用药。，二陈汤即以其为君药。"},{"q":"既能平肝、息风止痉，又可内清肝热，外散风热的是","o":["天麻","牛黄","蜈蚣","钩藤","羚羊角"],"a":3,"e":"钩藤甘凉，轻清透达，能平肝息风止痉，又清肝经之热，兼散上焦风热，故肝热动风兼风热者宜之。"},{"q":"栀子外用的功效是","o":["泻火除烦","清热利湿","凉血解毒","消肿止痛","凉血止血"],"a":3,"e":"栀子苦寒，外用研末调敷，能清热消肿止痛，故扭挫伤痛、疮疡肿毒可外敷取效。，内服则清泻三焦之火。"},{"q":"患者身发斑疹，色紫黯，最宜选用的药是","o":["桃仁","川芎","泽兰","血竭","红花"],"a":4,"e":"红花辛温，活血通经、散瘀止痛，善化滞血，热郁血滞而斑疹色暗者用之可活血化斑。，孕妇及月经过多者忌用。"},{"q":"既治痰多喘咳，又治肾虚遗尿，宜选用","o":["白果","百部","款冬花","桑白皮","马兜铃"],"a":0,"e":"白果甘苦涩平，敛肺定喘、止带缩尿，故痰多喘咳及肾虚遗尿、带下白浊皆可用，生用有毒须慎。"},{"q":"治咽喉肿痛，阳毒发斑，首选的药物是","o":["葛根","升麻","蔓荆子","柴胡","薄荷"],"a":1,"e":"升麻辛微甘微寒，发表透疹、清热解毒、升举阳气，善清阳明热毒，故咽喉肿痛、阳毒发斑首选。"},{"q":"香附可用于治疗","o":["咳嗽痰多","月经不调","胸痹心痛","湿热痢疾","脚气肿痛"],"a":1,"e":"香附辛微苦微甘平，疏肝解郁、理气宽中、调经止痛，为妇科调经之要药，故月经不调、痛经用之。"},{"q":"具有养阴生津功效的药物是","o":["生地黄","牡丹皮","赤芍","紫草","金银花"],"a":0,"e":"生地黄甘苦寒，清热凉血、养阴生津，故热病伤阴之舌绛烦渴、阴虚发热及肠燥便秘皆宜。"},{"q":"白鲜皮治风湿热痹，常配伍的药是","o":["独活","薏苡仁","羌活","黄连","茯苓"],"a":1,"e":"白鲜皮苦寒，清热燥湿、祛风解毒，治风湿热痹关节红肿常配薏苡仁、苍术以增除湿通痹之力。"},{"q":"石膏治气分实热证，常与其相须为用的药物是","o":["寒水石","芦根","知母","天花粉","淡竹叶"],"a":2,"e":"石膏辛甘大寒，清泻肺胃实热；知母苦甘寒，清热而滋阴。二药相须，清热之中兼护阴液，为气分热盛之主药对。"},{"q":"我国现存最早的本草专著是","o":["《神农本草经》","《本草纲目》","《证类本草》","《本草品汇精要》","《本草经集注》"],"a":0,"e":"《神农本草经》成书于东汉，载药365种，首创上中下三品分类，为现存最早的本草专著。"},{"q":"赤痢日久，体虚者，宜选用的药物是","o":["槐花","仙鹤草","白头翁","苎麻根","侧柏叶"],"a":1,"e":"仙鹤草苦涩平，收敛止血、止痢、补虚，故痢久不止而正气已虚者用之，止血止痢之中兼能强壮。"},{"q":"既能凉血散瘀，又善清泻肝火的药物是","o":["石膏","赤芍","牡丹皮","黄连","栀子"],"a":1,"e":"赤芍苦微寒，清热凉血、散瘀止痛，专入肝经血分，善清泻肝火，故肝热目赤肿痛、胁痛及血热瘀滞者宜。"},{"q":"既能消痰下气，又能平肝镇惊的药物是","o":["竹沥","礞石","瓦楞子","海浮石","天竺黄"],"a":1,"e":"礞石甘咸平，质重沉降，善消痰下气、平肝镇惊，为治顽痰胶结、癫狂惊痫之要药。竹沥、天竺黄偏清热化痰，无镇惊之能。"},{"q":"硫黄内服的用量范围为","o":["0、5～1、5g","1、5～3g","1、5～3、5g","3～6g","3、5～6g"],"a":1,"e":"硫黄内服1.5～3g，入丸散用，能补火助阳、通便；外用适量杀虫疗疮。其性温有毒，不可过量久服。"},{"q":"药性甘平，质润多脂，兼有滋养补虚作用的润肠通便药是","o":["火麻仁","郁李仁","松子仁","柏子仁","苦杏仁"],"a":0,"e":"火麻仁甘平，质润多脂，既润肠通便又滋养补虚，尤宜老人、产妇及津亏体虚之肠燥便秘。郁李仁则兼下气利水。"},{"q":"舒筋活络，又能化湿和胃的药物是","o":["独活","伸筋草","海风藤","青风藤","木瓜"],"a":4,"e":"木瓜酸温，归肝脾经，舒筋活络而化湿和胃，为治湿痹筋脉拘挛、吐泻转筋之要药。独活、海风藤无化湿和胃之功。"},{"q":"防己的功效是","o":["祛风湿，舒筋络，止痒","祛风湿，清虚热，安胎","祛风湿，止痛，化湿和胃","祛风湿，止痛，安胎","祛风湿，止痛，利水"],"a":4,"e":"防己苦辛寒，能祛风湿、止痛、利水消肿，尤宜风湿热痹及水肿、小便不利。安胎为黄芩、白术之功，非防己所具。"},{"q":"性味甘平的药物是","o":["钩藤","珍珠","僵蚕","天麻","羚羊角"],"a":3,"e":"天麻甘平，归肝经，息风止痉、平抑肝阳、祛风通络，药性平和，寒热虚实皆可配用。钩藤、羚羊角性凉，珍珠、僵蚕亦非甘平。"},{"q":"既能凉血止血，又兼收敛止血的药物是","o":["大蓟","白及","地榆","三七","白茅根"],"a":2,"e":"地榆苦酸微寒，凉血止血而兼收敛之性，尤宜下焦血热之便血、痔血、崩漏。大蓟、白茅根凉血而无收敛，白及偏收敛生肌。"},{"q":"既能袪风湿，又能消骨鲠的药物是","o":["威灵仙","蚕沙","防己","桑寄生","秦艽"],"a":0,"e":"威灵仙辛咸温，性善走窜，祛风湿、通络止痛，又能软坚消骨鲠，治诸骨鲠咽。防己、秦艽、桑寄生均无消骨鲠之效。"},{"q":"具有化湿行气，温中止呕功效的药物是","o":["苍术","白术","砂仁","广藿香","佩兰"],"a":2,"e":"砂仁辛温，化湿行气、温中止泻、安胎，其气芳香，尤善温中行气而止呕止泻。苍术、广藿香、佩兰化湿而无温中止呕之专功。"},{"q":"擅治米面薯芋等淀粉类食物积滞证的药物是","o":["山楂","神曲","麦芽","莱菔子","鸡内金"],"a":2,"e":"麦芽甘平，消食健胃而尤善消化米面薯芋等淀粉类食物，兼能回乳。山楂偏消肉食油腻，神曲善消酒谷陈腐之积。"},{"q":"治肺热喘咳，宜选用的药物是","o":["石膏","淡竹叶","栀子","决明子","夏枯草"],"a":0,"e":"石膏辛甘大寒，入肺胃经，清泄肺热而平喘，治肺热喘咳常配麻黄、杏仁。淡竹叶、栀子、夏枯草均无清肺平喘之专效。"},{"q":"治疗阳明头痛，牙痛，鼻渊，风湿痹痛宜选用的药物是","o":["防风","葛根","柴胡","羌活","白芷"],"a":4,"e":"白芷辛温芳香，善入阳明经，祛风止痛、通鼻窍，为治阳明头痛、牙痛、鼻渊及风湿痹痛之要药。羌活偏太阳，柴胡偏少阳。"},{"q":"无清热解毒之功的药物是","o":["大蓟","小蓟","大黄","地榆","侧柏叶"],"a":4,"e":"侧柏叶苦涩微寒，凉血止血、化痰止咳、生发乌发，而无清热解毒之功。大蓟、小蓟、地榆、大黄均能清热解毒而治疮痈肿毒。"},{"q":"车前子、旋覆花入汤剂宜","o":["久煎","先煎","布包煎","另行溶化","另煎"],"a":2,"e":"车前子与旋覆花分别含黏液与绒毛，入汤剂宜布包煎，以免糊锅或刺激咽喉。先煎用于矿石贝壳，后下用于气味芳香之品。"},{"q":"桔梗的功效是","o":["润肺，止咳，下气，化痰","宣肺，利咽，清肺，化痰","宣肺，利咽，祛痰，排脓","降气，止咳，祛痰，排脓","降气，止呕，祛痰，排脓"],"a":2,"e":"桔梗苦辛平，专入肺经，宣肺利咽、祛痰排脓，为治咳嗽痰多、咽痛失音及肺痈吐脓之要药，又能载药上行。"},{"q":"既能袪风湿，又有通经络，平肝功效的药物是","o":["桑枝","臭梧桐叶","防己","秦艽","豨莶草"],"a":1,"e":"臭梧桐叶辛苦甘凉，祛风湿、通经络，又能平肝降压，治风湿痹痛兼肝阳上亢者。桑枝、秦艽、防己均无平肝之功。"},{"q":"生大黄攻下，宜","o":["先煎","后下","久煎","包煎","另煎"],"a":1,"e":"大黄生用泻下力猛，久煎则致泻成分破坏而力减，故攻下宜后下；若取其泻火解毒、活血化瘀之功则可同煎。"},{"q":"既能清热化痰，又能清心定惊的药物是","o":["瓜蒌","礞石","竹茹","海蛤壳","天竺黄"],"a":4,"e":"天竺黄甘寒，归心肝经，清热化痰、清心定惊，为治痰热惊风、中风痰壅之良药。竹茹偏清胃热止呕，瓜蒌偏宽胸散结。"},{"q":"既能补阴，又能补气的药物是","o":["百合","玉竹","石斛","黄精","天冬"],"a":3,"e":"黄精甘平，归脾肺肾经，既补气又养阴，兼能健脾、润肺、益肾，为平补气阴之品。百合、玉竹、石斛、天冬均补阴而不补气。"},{"q":"下列除哪项外，均属于药性升降沉浮的确定依据","o":["药物的剂型","药物的效用","药物的性味","药物的质地轻重","入药部位"],"a":0,"e":"升降浮沉的确定依据为药物的性味、质地轻重、效用及入药部位，与剂型无关。剂型只影响给药与吸收，不决定作用趋向。"},{"q":"麦冬的功效是","o":["滋补肝肾，益精明目","养阴生津，润肺清心","滋阴补血，生津润燥","润肺化痰，养阴和胃","滋补肝肾，凉血止血"],"a":1,"e":"麦冬甘微苦微寒，归心肺胃经，养阴生津、润肺清心，治肺燥干咳、胃阴不足及心阴亏虚之心烦失眠。"},{"q":"桂枝不适宜的病证是","o":["风寒表实证","血热出血证","痰饮证","阳虚胸痹","血滞经闭"],"a":1,"e":"桂枝辛甘温，发汗解肌、温通经脉、助阳化气，性温助热，血热妄行之出血证当忌用。风寒表实、痰饮、阳虚胸痹、血滞经闭皆其所宜。"},{"q":"常与连翘相须为用，治疗风热表证、温热初起的药物是","o":["金银花","大青叶","板蓝根","穿心莲","薄荷"],"a":0,"e":"金银花与连翘相须为用，清热解毒、疏散风热，为治风热表证及温病初起发热微恶寒、咽痛之要药对。板蓝根、穿心莲偏解毒利咽。"},{"q":"下列哪味药物善温助心肾之阳，可用于治疗心阳不足之胸痹心痛，心悸气短","o":["附子","丁香","吴茱萸","小茴香","高良姜"],"a":0,"e":"附子辛甘大热，峻补元阳，上助心阳、中温脾阳、下补肾阳，故治心阳不足之胸痹心痛、心悸气短。丁香、吴茱萸只温中焦。"},{"q":"苦参与蛇床子的共同功效是","o":["清热，止痢","杀虫，燥湿","利尿，清热","温阳，止痛","祛风，解毒"],"a":1,"e":"苦参苦寒，清热燥湿、杀虫止痒、利尿；蛇床子辛苦温，燥湿祛风、杀虫止痒、温肾壮阳。二者共有杀虫、燥湿之功，为治湿疹瘙痒所常用。"},{"q":"治热病气津两伤所致的口渴、多汗、脉大无力，除用石膏、知母外，还宜配伍","o":["人参","牡蛎","黄连","酸枣仁","山茱萸"],"a":0,"e":"热病气津两伤而口渴、多汗、脉大无力，属阳明热盛兼气津耗伤，宜石膏、知母配人参，益气生津以扶正，即白虎加人参汤。"},{"q":"莲子、远志的共同功效是","o":["平肝安神","交通心肾","补脾止泻","益肾涩精","祛痰止咳"],"a":1,"e":"莲子甘涩平，补脾止泻、益肾涩精、养心安神；远志苦辛温，安神益智、祛痰开窍，又能交通心肾。二者共有交通心肾之功，治心肾不交。"},{"q":"不宜与半夏、瓜蒌、贝母、白及、白蔹同用的药物是","o":["肉桂","人参","丁香","附子","吴茱萸"],"a":3,"e":"十八反载“半蒌贝蔹及攻乌”，半夏、瓜蒌、贝母、白及、白蔹均与乌头相反，附子为乌头子根，故不宜同用。"},{"q":"治疗肠燥便秘，宜选用","o":["桑叶","桑枝","桑椹","桑寄生","桑白皮"],"a":2,"e":"桑椹甘酸寒，滋阴补血、生津润燥，质润多液，善治阴血亏虚之肠燥便秘。桑叶、桑枝、桑白皮、桑寄生均无润肠之效。"},{"q":"下列药物中，无安胎功效的药物是","o":["紫苏叶","砂仁","黄芩","桑寄生","广藿香"],"a":4,"e":"紫苏叶、砂仁、黄芩、桑寄生均能安胎，分别用于气滞、气滞湿阻、血热及肝肾不足之胎动不安。广藿香化湿解暑，无止胎之功。"},{"q":"鳖甲的临床应用不包括","o":["阴虚阳亢","阴虚风动","失眠健忘","阴虚内热","癥瘕积聚"],"a":2,"e":"鳖甲咸寒，滋阴潜阳、退热除蒸、软坚散结，治阴虚阳亢、阴虚风动、阴虚内热及癥瘕积聚。失眠健忘为龟甲、远志等所主。"},{"q":"能清热解毒，消痈，下乳，舒筋通脉的药物是","o":["金银花","蚤休","漏芦","蒲公英","紫花地丁"],"a":2,"e":"漏芦苦寒，清热解毒、消痈散结、通经下乳、舒筋通脉，为治乳痈肿痛、乳汁不下及湿痹拘挛之要药。"},{"q":"治温热病热入营血，神昏舌绛，宜首选的药组是","o":["金银花、连翘","大青叶、板蓝根","穿心莲、贯众","大青叶、青黛","贯众、青黛"],"a":0,"e":"金银花、连翘善清热解毒、透营转气，为治温病热入营血、神昏舌绛之首选药对，清营汤即取二药透热转气。"},{"q":"常用于治疗肝肾不足、腰膝酸软、妊娠漏血、胎动不安的药物","o":["黄芩","竹茹","白术","生姜","杜仲"],"a":4,"e":"杜仲甘温，补肝肾、强筋骨、安胎，治肝肾不足之腰膝酸软、筋骨无力及妊娠漏血、胎动不安。黄芩、白术安胎而无补肝肾之力。"},{"q":"治疗元气大脱兼冷汗淋漓、四肢厥冷、脉微欲绝者，人参常配伍","o":["麦冬","白术","附子","黄芪","五味子"],"a":2,"e":"元气大脱兼冷汗淋漓、四肢厥冷、脉微欲绝，属阳气暴脱之候，人参配附子即参附汤，大补元气、回阳救逆。"},{"q":"不具有清肝明目作用的药物是","o":["车前子","决明子","青葙子","紫苏子","羚羊角"],"a":3,"e":"紫苏子降气化痰、止咳平喘、润肠通便，无清肝明目之功。车前子、决明子、青葙子、羚羊角均能清肝明目，治目赤肿痛。"},{"q":"贯众性寒，有凉血止血之功，炒炭后具有的功效是","o":["涩肠止泻","收敛止血","固精缩尿","固表止汗","敛肺止咳"],"a":1,"e":"贯众苦微寒，清热解毒、凉血止血、杀虫；炒炭后寒性减而涩性增，长于收敛止血，用于崩漏下血等出血证。"},{"q":"下列除哪项外，均是莪术的主治病证","o":["癥瘕积聚","心腹瘀痛","血瘀经闭","风湿痹痛","食积脘腹胀痛"],"a":3,"e":"莪术辛苦温，破血行气、消积止痛，主治癥瘕积聚、血瘀经闭、心腹瘀痛及食积脘腹胀痛。风湿痹痛非其所主。"},{"q":"广藿香最适于治疗哪种呕吐","o":["胃寒呕吐","胃热呕吐","胃虚呕吐","胃有湿热呕吐","脾胃湿浊呕吐"],"a":4,"e":"广藿香辛微温，芳香化湿、和中止呕，尤善治湿浊中阻、脾胃不和之呕吐，其化浊力强，为暑湿吐泻所常用。"},{"q":"具有清肝泻火，明目退翳功效的药物是","o":["夏枯草","野菊花","青葙子","决明子","鸭跖草"],"a":2,"e":"青葙子苦微寒，专入肝经，清肝泻火、明目退翳，治肝火上炎之目赤肿痛、目生翳障。决明子兼润肠，夏枯草兼散结。"},{"q":"治头虱、阴道滴虫，宜选用","o":["百部","紫菀","枇杷叶","苦杏仁","洋金花"],"a":0,"e":"百部甘苦微温，润肺下气止咳，又能杀虫灭虱，外用治头虱、体虱及阴道滴虫。紫菀、枇杷叶、苦杏仁、洋金花均无杀虫之功。"},{"q":"下列哪味中药可用治中焦寒凝气滞之脘腹胀痛","o":["肉桂","丁香","花椒","吴茱萸","小茴香"],"a":4,"e":"小茴香辛温，散寒止痛、理气和胃，善治寒凝气滞之脘腹胀痛，尤长于下焦寒疝、睾丸偏坠。丁香偏降逆止呕，吴茱萸偏厥阴头痛。"},{"q":"为引药入肾及增强药物补肾的作用宜","o":["蜜炙","酒炙","醋炙","盐水炙","姜汁炙"],"a":3,"e":"盐味咸入肾，盐水炙能引药下行入肾，增强补肝肾之效，杜仲、黄柏、知母、补骨脂多用此法。醋炙入肝止痛，酒炙上行活血。"},{"q":"可用治热毒血痢，便下脓血的药物是","o":["金银花","连翘","大青叶","鱼腥草","蒲公英"],"a":0,"e":"金银花甘寒，清热解毒、疏散风热，兼能凉血止痢，单用浓煎或配黄连、黄芩治热毒血痢、便下脓血。"},{"q":"治疗肾虚小儿鸡胸，囟门不合，宜首选","o":["鳖甲","麦冬","龟甲","玉竹","百合"],"a":2,"e":"龟甲咸甘微寒，滋阴潜阳、益肾强骨、养血补心，善治肾虚骨痿、小儿囟门不合、鸡胸龟背。鳖甲偏软坚散结、退虚热。"},{"q":"荆芥的功效是","o":["解表透疹，消疮止血","发表通窍，胜湿止痛","发表止痉，消疮止泻","发表止痛，利水消肿","消疮止泻，透疹止血"],"a":0,"e":"荆芥辛微温，发表散风、透疹消疮，炒炭又能止血，治便血、崩漏。其性平和，风寒风热表证皆可配伍应用。"},{"q":"下列配伍中属于“十九畏”的药物是","o":["大戟与甘草","贝母与乌头","乌头与瓜萎","官桂与赤石脂","芍药与藜芦"],"a":3,"e":"十九畏载“官桂善能调冷气，若逢石脂便相欺”，官桂即肉桂，与赤石脂相畏。大戟与甘草、贝母与乌头属十八反。"},{"q":"马勃与马齿苋的共同功效是","o":["止痢","止血","止汗","止痒","止痛"],"a":1,"e":"马勃辛平，清热解毒、利咽止血；马齿苋酸寒，清热解毒、凉血止血、止痢。二者共有止血之功，均可用于出血证。"},{"q":"菊花与升麻均具有的功效是","o":["生津止渴","通经活络","升举阳气","清热解毒","清肝明目"],"a":3,"e":"菊花疏散风热、平肝明目、清热解毒；升麻发表透疹、清热解毒、升举阳气。二者共有清热解毒之效，治疮疡肿毒、咽喉肿痛。"},{"q":"用治肝阳上亢的头痛眩晕，宜选用的药是","o":["白芍","当归","川芎","白芷","熟地黄"],"a":0,"e":"白芍苦酸微寒，养血敛阴、柔肝止痛、平抑肝阳，治肝阳上亢之头痛眩晕，常配天麻、钩藤、石决明。川芎、白芷偏祛风止痛。"},{"q":"清泄的含义是","o":["栀子、黄芩清热泻火，用治火热上炎、目赤口苦之证","大黄泻下通便，用治热结便秘","枇杷叶降泄胃气，用治胃气上逆的呕吐呃逆","黄连、黄柏清热燥湿，用治湿热证","杏仁降泄肺气，用治肺气上逆的咳喘"],"a":0,"e":"清泄指清泄火热之邪，药性寒凉而入气分，能清热泻火，治火热上炎之目赤、口苦、烦躁，栀子、黄芩为其代表。"},{"q":"优质大黄的典型特点是","o":["狮子头","菊花心","蟾蜍皮","锦纹","云锦花团"],"a":3,"e":"优质大黄表面黄棕色，可见类白色菱形网状纹理，习称“锦纹”，为品质鉴别特征。菊花心多指黄芪、甘草的断面特征。"},{"q":"大黄配伍茵陈、栀子治疗黄疸，是因其功能","o":["清热解毒","清热泻火","除湿退黄","泻下攻积","活血化瘀"],"a":2,"e":"大黄苦寒，泻下攻积、清热泻火、凉血解毒，又能利湿退黄，配茵陈、栀子即茵陈蒿汤，治湿热黄疸。"},{"q":"七情配伍中，可以降低药物毒副作用的是","o":["相恶、相使","相杀、相反","相须、相恶","相杀、相畏","相须、相使"],"a":3,"e":"相畏指一药毒性被另一药减轻，相杀指一药能减轻另一药毒性，二者均属降低毒副作用的配伍。相恶为削弱功效，相反为增毒。"},{"q":"长于温脾胃之阳，祛脾胃之寒，为温中散寒之要药的是","o":["干姜","丁香","花椒","胡椒","小茴香"],"a":0,"e":"干姜辛热，主入脾胃，温中散寒、回阳通脉、温肺化饮，长于温脾胃之阳而祛脾胃之寒，为温中散寒之要药。"},{"q":"药物的升降浮沉是指","o":["药物有无毒副作用","作用部位的选择性","作用趋向性","药物有无补泻作用","药物作用的峻猛与否"],"a":2,"e":"升降浮沉指药物对人体作用的不同趋向性，升浮者上行向外，沉降者下行向内。归经言作用部位，有毒无毒言安全性。"},{"q":"黄柏与生地黄的共同主治是","o":["肺热咳嗽","骨蒸劳热","肠燥便秘","疮痈肿毒","津伤口渴"],"a":1,"e":"黄柏苦寒，清热燥湿、泻火除蒸、解毒疗疮，善退虚热；生地黄甘寒，清热凉血、养阴生津。二者共有清退骨蒸劳热之功。"},{"q":"具有活血止痛，止咳平喘功效的药物是","o":["穿山龙","老鹳草","丝瓜络","络石藤","路路通"],"a":0,"e":"穿山龙苦微寒，祛风除湿、活血通络、止痛，又能止咳平喘，治风湿痹痛、跌打损伤及咳嗽气喘。"},{"q":"外用可杀虫疗疮的泻水逐饮药是","o":["甘遂","京大戟","芫花","商陆","番泻叶"],"a":2,"e":"芫花辛苦温，有毒，泻水逐饮、祛痰止咳，外用能杀虫疗疮，治头疮、白秃、顽癣。甘遂、京大戟逐饮而无杀虫疗疮之用。"},{"q":"以下哪项不是沉降药物的作用","o":["清热泻火","收敛固涩","平肝潜阳","开通心窍","镇惊安神"],"a":3,"e":"沉降药下行向内，多具清热泻火、收敛固涩、平肝潜阳、镇惊安神、降逆止呕之功。开通心窍属升浮之性，芳香开窍药多升浮。"},{"q":"杜仲具有的功效是","o":["补肝肾、安胎","补肾阳、止汗","补肾阳、平喘","补肝肾、明目","退虚热、安胎"],"a":0,"e":"杜仲甘温，补肝肾、强筋骨、安胎，治肝肾不足之腰膝酸痛、筋骨无力及胎动不安、习惯性堕胎。"},{"q":"除哪味药物外，孕妇当慎用","o":["干姜","肉桂","附子","丁香","吴茱萸"],"a":3,"e":"干姜、肉桂、附子、吴茱萸皆辛热燥烈，易助火伤胎，孕妇当慎用。丁香温中降逆、温肾助阳，性较平和，不属慎用之列。"},{"q":"清热药的性味多是","o":["苦寒","辛寒","咸寒","甘寒","酸寒"],"a":0,"e":"清热药性多寒凉，味多苦，故以苦寒为主，能清热泻火、燥湿解毒。甘寒者多为养阴清热之品，如芦根、天花粉。"},{"q":"以下哪个是东北的道地药材","o":["枸杞","山药","牛膝","当归","鹿茸"],"a":4,"e":"关药指山海关以北所产道地药材，鹿茸、人参、五味子、细辛为其代表。枸杞属宁夏，当归属甘肃，山药、牛膝属怀药。"},{"q":"蒲黄、旋覆花等药入汤剂宜","o":["包煎","后下","先煎","烊化","冲服"],"a":0,"e":"蒲黄为花粉，质轻细小易漂浮；旋覆花带绒毛易刺激咽喉，二者入汤剂均宜包煎，以免糊锅或致呛咳。"},{"q":"百部止咳平喘的机制是","o":["宣肺","润肺","清肺","敛肺","泻肺"],"a":1,"e":"百部甘苦微温，专入肺经，功善润肺下气止咳，新久咳嗽、肺痨咳嗽及百日咳均可应用，润肺为其止咳平喘之理。"},{"q":"善疏散少阳半表半里之邪的药物是","o":["薄荷","牛蒡子","夏枯草","升麻","柴胡"],"a":4,"e":"柴胡苦辛微寒，善入少阳，和解退热、疏肝解郁、升举阳气，为治邪在少阳、寒热往来之要药。"},{"q":"川楝子除具有行气止痛作用外，尚能","o":["疏肝泄热","纳气平喘","清热解毒","活血化瘀","行气消积"],"a":0,"e":"川楝子苦寒，行气止痛、疏肝泄热、杀虫，治肝郁化火之胸胁脘腹胀痛及虫积腹痛，为金铃子散之主药。"},{"q":"治目赤多泪，目暗不明，齿龈肿痛，首选的药物是","o":["葛根","桑叶","牛蒡子","蔓荆子","薄荷"],"a":3,"e":"蔓荆子辛苦微寒，疏散风热、清利头目，善治风热上攻之目赤多泪、目暗不明及齿龈肿痛，兼能祛风止痛。"},{"q":"属于鹿茸临床主治病证的是","o":["胎动不安，五更泄泻","冲任虚寒，崩漏带下","肠燥便秘，崩漏带下","虚喘气促，骨蒸劳嗽","症瘕积聚，产后少乳"],"a":1,"e":"鹿茸甘咸温，补肾阳、益精血、强筋骨、调冲任、托疮毒，治肾阳不足、精血亏虚及冲任虚寒之崩漏带下。"},{"q":"入汤剂需先煎的药物是","o":["薄荷、豆蔻","蒲黄、海金沙","人参、阿胶","磁石、牡蛎","龙骨、钩藤"],"a":3,"e":"磁石、牡蛎属矿物贝壳类，质地坚硬，有效成分难溶，须先煎以取其味。薄荷、钩藤宜后下，阿胶宜烊化，人参宜另煎。"},{"q":"续断具有的功效是","o":["补肝肾、止咳喘","补肾阳、消水肿","补肾阳、益气血","补肝肾、续折伤","祛风湿、止泻痢"],"a":3,"e":"续断苦辛微温，补肝肾、强筋骨、续折伤、止崩漏，为治跌打损伤、筋骨折伤及胎漏下血之常用药。"},{"q":"既能祛风湿，止痛，又能解表的药物是","o":["威灵仙","木瓜","五加皮","桑枝","独活"],"a":4,"e":"独活辛苦微温，祛风湿、止痛、解表，善治下半身风湿痹痛及风寒表证兼湿，与羌活相比其性偏于下行。"},{"q":"既能治疗烦躁不安，心悸失眠，又能治疗瘰疬痰核，瘿瘤的中药是","o":["天麻","钩藤","牡蛎","白僵蚕","羚羊角"],"a":2,"e":"牡蛎咸微寒，重镇安神、平肝潜阳、软坚散结、收敛固涩，既治心悸失眠、烦躁不安，又治痰火郁结之瘰疬痰核、瘿瘤。"},{"q":"党参的主治病证不包括","o":["脾气虚","肺气虚","心气虚","气血两虚","气津两伤"],"a":2,"e":"党参甘平，补中益气、健脾益肺、养血生津，治脾肺气虚及气血两虚、气津两伤。其补气偏于中上二焦，不主心气虚。"},{"q":"川楝子的入药部位是","o":["种子","种仁","果实","孢子","果穗"],"a":2,"e":"川楝子为楝科植物川楝的干燥成熟果实，故入药部位为果实。其种子称苦楝子，功用有别，不可混称。"},{"q":"善治寒疝，睾丸偏坠，少腹冷痛，痛经的药物是","o":["丁香","胡椒","花椒","小茴香","高良姜"],"a":3,"e":"小茴香辛温，入肝肾经，散寒止痛、理气和胃，善暖下焦而治寒疝腹痛、睾丸偏坠、少腹冷痛及寒凝痛经。"},{"q":"具有消积化滞作用的药物是","o":["陈皮","青皮","薤白","大腹皮","川楝子"],"a":1,"e":"青皮苦辛温，疏肝破气、消积化滞，性较峻烈，善治肝气郁结之胸胁胀痛及食积气滞之脘腹胀痛。"},{"q":"治疗肺热咳嗽不用","o":["石膏","寒水石","知母","芦根","天花粉"],"a":1,"e":"石膏、知母、芦根、天花粉均能清肺热而治肺热咳嗽。寒水石咸大寒，清热泻火、除烦止渴，多用于高热烦渴，不主肺热咳喘。"},{"q":"苍术尤其善治的痹证证型是","o":["热痹","寒痹","着痹","行痹","顽痹"],"a":2,"e":"苍术辛苦温，燥湿健脾、祛风散寒，其燥湿力强，善治湿邪偏胜、肢体沉重酸痛之着痹，配薏苡仁、独活更佳。"},{"q":"既能温经止血、散寒调经，外用又能祛湿止痒的是","o":["炮姜","生姜","艾叶","茜草","侧柏叶"],"a":2,"e":"艾叶辛苦温，有小毒，温经止血、散寒调经、安胎，外用祛湿止痒，治虚寒性出血、宫冷不孕及湿疹瘙痒。"},{"q":"既可用于治疗血瘀证，又可治疗出血证的药是","o":["姜黄","五灵脂","川芎","红花","延胡索"],"a":1,"e":"五灵脂苦咸甘温，活血止痛、化瘀止血，既治瘀血阻滞之胸腹疼痛、痛经，又治瘀血内阻、血不归经之出血。"},{"q":"下列除哪味药物外，均是妊娠禁用药物","o":["牵牛","桃仁","巴豆","莪术","水蛭"],"a":1,"e":"牵牛、巴豆、莪术、水蛭毒性峻烈或破血力猛，属妊娠禁用药。桃仁活血祛瘀而力较缓，列为妊娠慎用药，故不属禁用之列。"},{"q":"补益药其煎煮方法宜选用的是","o":["武火久煎","武火急煎","文火慢煎","武火慢煎","文火略煎"],"a":2,"e":"补益药多味厚滋补，宜文火慢煎久煮，使有效成分充分溶出。解表药则宜武火急煎，以免挥发性成分散失。"},{"q":"薄荷的功效不包括","o":["清热凉血","疏肝行气","利咽透疹","疏散风热","清利头目"],"a":0,"e":"薄荷辛凉，疏散风热、清利头目、利咽透疹、疏肝行气，为疏散风热之要药，而无清热凉血之功。"},{"q":"尤宜治各种虚汗兼有口渴者的药是","o":["莲子","浮小麦","麻黄根","石榴皮","糯稻根须"],"a":4,"e":"糯稻根须甘平，益胃生津、止汗退虚热，既能止虚汗又兼生津止渴，故尤宜虚汗兼口渴者。麻黄根、浮小麦止汗而不生津。"},{"q":"紫苏子的功效是","o":["润肺下气，止咳平喘","清肺止咳，降逆止呕","止咳平喘，解痉止痛","润肺下气止咳，杀虫灭虱","降气化痰，止咳平喘，润肠通便"],"a":4,"e":"紫苏子辛温，降气化痰、止咳平喘、润肠通便，治痰壅气逆之咳嗽气喘及肠燥便秘，为三子养亲汤之主药。"},{"q":"可治多种饮食积滞之证，尤善消化油腻，为治肉食积滞的要药是","o":["山楂","神曲","麦芽","莱菔子","鸡内金"],"a":0,"e":"山楂酸甘微温，消食健胃、行气散瘀，善消化油腻肉食，为治肉食积滞之要药，炒焦后消食之力更强。"},{"q":"既归胃经，又归心经的药物是","o":["石斛","麦冬","桑椹","楮实子","北沙参"],"a":1,"e":"麦冬甘微苦微寒，归心、肺、胃经，既养胃阴、生津止渴，又清心除烦安神，故既归胃经又归心经。石斛、北沙参不入心经。"},{"q":"功能凉血止血，善治血淋、尿血的药物是","o":["大蓟","小蓟","茜草","槐花","白及"],"a":1,"e":"小蓟甘苦凉，凉血止血、散瘀解毒消痈，其性下行，尤善治下焦血热之血淋、尿血，小蓟饮子即以其为主药。"},{"q":"具有解毒散结功效的药物是","o":["玄参","牡丹皮","赤芍","石膏","生地黄"],"a":0,"e":"玄参甘苦咸微寒，清热凉血、养阴生津、泻火解毒、软坚散结，治温毒发斑、咽喉肿痛及瘰疬痰核。牡丹皮、赤芍无散结之功。"},{"q":"从病证相宜角度，艾叶的最宜主治证是","o":["带下","阴虚咯血","血热出血","肺寒咳喘","下焦虚寒之月经不调，痛经"],"a":4,"e":"艾叶辛苦温，暖胞宫、散寒邪，为温经止血、散寒调经之要药，最宜下焦虚寒所致月经不调、痛经及宫冷不孕。"},{"q":"不宜与藜芦配伍的药物是","o":["黄连","黄芩","黄柏","龙胆草","苦参"],"a":4,"e":"十八反载“诸参辛芍叛藜芦”，苦参属参类，与藜芦相反，不宜同用。黄连、黄芩、黄柏、龙胆草不在此列。"},{"q":"腹部、肛门疾病手术前，或X线腹部摄片，借泻下导滞，清洁肠道，常选用的药物是","o":["番泻叶","牵牛子","巴豆","火麻仁","芒硝"],"a":0,"e":"番泻叶苦甘寒，泻热行滞、通便、利水，作用迅速，小量即可泻下导滞，故常用于术前或腹部X线摄片前清洁肠道。"},{"q":"治疗出血证兼见阴虚、血虚者，宜选用","o":["艾叶","阿胶","三七","茜草","白及"],"a":1,"e":"阿胶甘平，补血滋阴、润燥止血，为血肉有情之品，故出血证兼阴虚、血虚者最宜，尤善治虚劳咯血、崩漏。"},{"q":"苍术的性味是","o":["辛、甘，温","苦、甘，温","辛、甘，寒","辛、苦，寒","辛、苦，温"],"a":4,"e":"苍术辛苦温，归脾胃经，辛能发散、苦能燥湿、温能胜寒，故其性味为辛、苦，温，正合燥湿运脾之用。"},{"q":"外祛风湿，内燥脾湿的药物是","o":["秦艽","白术","独活","木通","苍术"],"a":4,"e":"苍术辛苦温而芳香，既能外散风湿之邪，治风湿痹痛，又能内燥脾湿、健脾运中，治湿阻中焦之脘痞腹胀。"},{"q":"对于下部出血病证，应用相应的止血药同时，为增强疗效，常配伍","o":["行气药","活血药","温经药","升阳药","降气药"],"a":3,"e":"下部出血多因气虚下陷、血随气下，故于止血药中配升阳举陷之品，如黄芪、升麻、柴胡，以升提阳气、助血归经。"},{"q":"患者内服50g中药后，症见心悸、恶心、呕吐、腹泻、头晕等强心苷样中毒反应，可能因服用过量的药物是","o":["白薇","槟榔","胡黄连","青蒿","远志"],"a":0,"e":"白薇含强心苷，内服过量可致心悸、恶心呕吐、腹泻、头晕等强心苷样中毒反应，故用量不宜过大。"},{"q":"擅治风热外感，咽喉肿痛的药物是","o":["薄荷","蔓荆子","柴胡","淡豆豉","葛根"],"a":0,"e":"薄荷辛凉，疏散风热、清利头目、利咽透疹，其利咽之功尤著，为治风热外感、咽喉肿痛之常用药。"},{"q":"长于祛痰，又能降气，为肺家要药，咳喘痰多，无论寒热皆可用的药物是","o":["柿蒂","百部","白前","北沙参","苦杏仁"],"a":2,"e":"白前辛苦微温，降气化痰止咳，性温而不燥、质润而不腻，凡肺气壅实、咳喘痰多者无论寒热皆可配伍应用。"},{"q":"下列哪一项不属于血竭的功效","o":["化痰","止血","生肌","活血","敛疮"],"a":0,"e":"血竭甘咸平，活血定痛、化瘀止血、生肌敛疮，为伤科要药，内服外用皆宜，而无化痰之功。"},{"q":"木香的功效是","o":["行气止痛，祛寒","行气止痛，醒脾","行气止痛，利水","行气止痛，调中","行气止痛，解毒"],"a":3,"e":"木香辛苦温，芳香行散，行气止痛、调中导滞，善治脾胃气滞之脘腹胀痛、泻痢后重，为行气调中之要药。"},{"q":"在“十八反”中，下列药物除哪种外均与甘草相反","o":["大戟","海藻","党参","芫花","甘遂"],"a":2,"e":"十八反载“藻戟遂芫俱战草”，海藻、大戟、甘遂、芫花均与甘草相反。党参不在其列，故不属相反之药。"},{"q":"不宜与郁金同用的药物是","o":["白芍","丁香","甘草","半夏","细辛"],"a":1,"e":"十九畏载“丁香莫与郁金见”，二者相畏，不宜同用。郁金行气解郁、活血止痛，与丁香温中降逆之性相悖。"},{"q":"功专利水渗湿，力胜茯苓，性平而无补益之功的利水消肿药是","o":["薏苡仁","泽泻","香加皮","滑石","猪苓"],"a":4,"e":"猪苓甘淡平，专于利水渗湿，其力胜于茯苓，而无健脾宁心之补益作用，故水肿、小便不利、淋浊带下多用。"},{"q":"治疗五更泄泻常选用的药物是","o":["沙苑子","补骨脂","肉苁蓉","韭菜子","核桃仁"],"a":1,"e":"补骨脂辛苦温，补肾壮阳、固精缩尿、温脾止泻，善治脾肾阳虚之五更泄泻，配肉豆蔻即四神丸之意。"},{"q":"善治头面部风痰，口眼㖞斜的药物是","o":["半夏","芥子","白前","白附子","旋覆花"],"a":3,"e":"白附子辛温有毒，祛风痰、定惊搐、解毒散结止痛，其性上行，善治头面部风痰之口眼㖞斜、偏头痛及痰厥头痛。"},{"q":"火麻仁入药，宜","o":["打碎入煎","后下","包煎","另煎","久煎"],"a":0,"e":"火麻仁为富含油脂的种仁，外有硬壳，须打碎后入煎，使有效成分充分溶出，否则药力难以发挥，润肠之力大减。"},{"q":"既能润肠通便，又能下气利水的药物是","o":["火麻仁","郁李仁","松子仁","柏子仁","苦杏仁"],"a":1,"e":"郁李仁辛苦甘平，润燥滑肠、下气利水，既治肠燥便秘，又治水肿胀满、脚气浮肿，与火麻仁之纯润肠者不同。"},{"q":"解乌头类药物毒性，宜选用","o":["白蔹","紫苏","半夏","蜂蜜","白扁豆"],"a":3,"e":"蜂蜜甘平，能缓急解毒，与乌头同煎可减其毒性，故乌头类中毒常以蜂蜜、甘草、生姜等解之。"},{"q":"与乌头相反的药物应除外","o":["玄参","白及","贝母","瓜蒌","半夏"],"a":0,"e":"十八反载“半蒌贝蔹及攻乌”，半夏、瓜蒌、贝母、白及、白蔹与乌头相反。玄参不在其列，故不属相反。"},{"q":"下列金钱草的主治病证中错误的是","o":["湿热黄疸","石淋，热淋","经闭，癥瘕","痈肿疔疮","毒蛇咬伤"],"a":2,"e":"金钱草甘咸微寒，利湿退黄、利尿通淋、解毒消肿，治湿热黄疸、石淋热淋、痈肿疔疮及毒蛇咬伤。经闭癥瘕非其所主。"},{"q":"一种药物能够削弱另一种药物的功效的配伍属于","o":["相反","相畏","相杀","相恶","相侮"],"a":3,"e":"相恶指两药合用，一种药物使另一种药物原有功效降低甚至丧失，属配伍关系之一。相畏、相杀为减毒，相反为增毒。"},{"q":"按照归经理论，下列哪味药不归心经","o":["栀子","藿香","牛黄","龙眼肉","丹参"],"a":1,"e":"藿香辛微温，归脾、胃、肺经，芳香化湿、和中止呕、发表解暑，不入心经。栀子、牛黄、丹参、龙眼肉均归心经。"},{"q":"陈皮配半夏的作用是","o":["理气调中","降逆止呕","燥湿化痰","消痞散结","清热化痰"],"a":2,"e":"陈皮理气健脾、燥湿化痰，半夏燥湿化痰、降逆止呕，二药相配即二陈汤之意，共奏燥湿化痰之功，治湿痰咳嗽。"},{"q":"能上清心火，下利小便，善导邪热从小便而出的药物是","o":["石膏","知母","芦根","淡竹叶","决明子"],"a":3,"e":"淡竹叶甘淡寒，归心胃小肠经，上能清心除烦，下能利尿通淋，善导心与小肠之热从小便而出。"},{"q":"属于“疗寒以热药”治疗原则的是","o":["用附子、干姜治疗腹中冷痛、脉沉无力","用茯苓、猪苓治疗水肿、小便不利","用黄芩、连翘治疗发热咽痛、舌红尿赤","用五味子、莲子治疗盗汗遗精","用麻黄、薄荷治疗外感表证"],"a":0,"e":"“疗寒以热药”指寒证当用温热药。附子、干姜辛热，温中散寒、回阳救逆，正治腹中冷痛、脉沉无力之里寒证。"},{"q":"鹿茸的临床常用剂量为","o":["0、05～0、1g","0、2～0、5g","1～2g","5～9g","10～30g"],"a":2,"e":"鹿茸甘咸温，为血肉有情之品，药力峻猛，常用量1～2g，研末冲服，不可骤用大量，以免助火动血。"},{"q":"下列除哪项外，均为猪苓的临床应用","o":["水肿，小便不利","泄泻","淋证","带下","心悸失眠"],"a":4,"e":"猪苓利水渗湿，主治水肿、小便不利、泄泻、淋证及带下。心悸失眠属安神药所主，非猪苓之适应证。"},{"q":"药物的副作用是指","o":["配伍不当出现的反应","药不对证出现的不适反应","达不到常规用量不能控制病情","超过常规用量时出现的不良反应","在常规剂量时出现的与疗效无关的不适反应"],"a":4,"e":"副作用指药物在常用剂量下出现的与治疗目的无关的不适反应，其产生与药物作用选择性低有关，一般轻微且可预知。"},{"q":"治疗肺热咳嗽，燥热咳嗽，宜首选的药物是","o":["桑叶","升麻","牛蒡子","蝉蜕","柴胡"],"a":0,"e":"桑叶苦甘寒，疏散风热、清肺润燥、平肝明目，既能清肺热又能润肺燥，故肺热咳嗽、燥热咳嗽均宜，常配杏仁、沙参。"},{"q":"下列息风止痉药中，均有毒的药组是","o":["蜈蚣、全蝎","全蝎、僵蚕","天麻、钩藤","蜈蚣、僵蚕","羚羊角、牛黄"],"a":0,"e":"全蝎、蜈蚣均辛平有毒，息风止痉、攻毒散结、通络止痛。天麻、钩藤、僵蚕、羚羊角、牛黄均无毒。"},{"q":"白果治疗咳喘时，宜配伍何药达到既开肺散邪而不耗肺气，又敛肺平喘而无留邪之弊","o":["百部","杏仁","麻黄","紫菀","款冬花"],"a":2,"e":"白果甘苦涩平，敛肺定喘、止带缩尿，其性收敛易留邪，配麻黄宣肺散邪，一开一敛，既平喘又不耗肺气、不留邪。"},{"q":"车前子性降滑利，慎用者除肾虚精滑者外，还有","o":["肺热咳痰者","老年体弱者","怀孕妇女","阴虚火旺者","脾胃虚寒者"],"a":2,"e":"车前子甘淡微寒，利水通淋、渗湿止泻、清肝明目、清肺化痰，性降滑利，肾虚精滑者及孕妇均当慎用。"},{"q":"用治正气不足滑脱证者，常用龙骨配","o":["磁石","牡蛎","珍珠","琥珀","珍珠母"],"a":1,"e":"龙骨甘涩平，镇惊安神、平肝潜阳、收敛固涩；牡蛎咸微寒，重镇安神、平肝潜阳、软坚散结、收敛固涩，二药相须善治滑脱证。"},{"q":"大青叶与青黛的共同功效是","o":["清热解毒，活血消斑","清热解毒，凉血消斑","清热解毒，泻火定惊","清热解毒，凉血消肿","清热解毒，疏散风热"],"a":1,"e":"大青叶苦寒，清热解毒、凉血消斑；青黛咸寒，清热解毒、凉血消斑、泻火定惊。二者同源，共有清热解毒、凉血消斑之功。"},{"q":"黄芩与知母的共同主治是","o":["痈肿疮毒","内热消渴","骨蒸潮热","肠燥便秘","肺热咳嗽"],"a":4,"e":"黄芩苦寒，清热燥湿、泻火解毒、止血安胎，善清肺火；知母苦甘寒，清热泻火、滋阴润燥，善清肺胃之热。二者均治肺热咳嗽。"},{"q":"确定归经学说的依据是","o":["阴阳学说","五行学说","药性理论","脏腑经络理论","所治病证"],"a":3,"e":"归经以脏腑经络理论为基础，表示药物作用的部位，其确立不离脏腑经络的生理病理。药性理论为总纲，非归经的直接依据。"},{"q":"长于疏肝破气的药物是","o":["刀豆","乌药","青皮","川楝子","荔枝核"],"a":2,"e":"青皮苦辛温，性较峻烈，疏肝破气、消积化滞，善治肝气郁结之胸胁胀痛、疝气疼痛及乳痈，破气之力胜于陈皮。"},{"q":"治风痰癫狂，常以白矾配伍","o":["郁金","磁石","朱砂","远志","皂荚"],"a":0,"e":"白矾酸涩寒，内服化痰、止血、止泻，配郁金即白金丸，取郁金清心开窍、行气解郁，共治痰浊蒙蔽心窍之癫狂。"},{"q":"附子与干姜共同的功效是","o":["温中散寒，回阳","补火助阳，化饮","散寒止痛，温肺","温通经脉，止痛","温通经脉，温肺"],"a":0,"e":"附子辛甘大热，回阳救逆、补火助阳、散寒止痛；干姜辛热，温中散寒、回阳通脉。二者相须，共有温中散寒、回阳救逆之功。"},{"q":"化湿药的主治证是","o":["湿疹湿疮","风湿痹证","湿阻中焦证","泄泻痢疾","水湿内停病证"],"a":2,"e":"化湿药气味芳香，性偏温燥，主入脾胃，能宣化湿浊、健运脾胃，故主治湿浊内阻、脾为湿困之湿阻中焦证。"},{"q":"治亡阳证，宜选的药组是","o":["鹿茸、肉桂","肉桂、人参","肉桂、干姜","附子、肉桂","附子、干姜"],"a":4,"e":"亡阳证见冷汗淋漓、四肢厥冷、脉微欲绝，宜附子配干姜，附子回阳救逆、干姜温中散寒，相须为用，为四逆汤之核心。"},{"q":"苦味药的作用是","o":["能和能缓","能燥能泄","能收能涩","能下能软","能行能散"],"a":1,"e":"苦味药能泄、能燥、能坚，具清泄火热、降泄气逆、通泄大便及燥湿坚阴之功。辛能行能散，酸能收能涩，甘能补能缓。"},{"q":"既能益肾固精，又能养肝明目的药物是","o":["菊花","苍术","覆盆子","桑螵蛸","金樱子"],"a":2,"e":"覆盆子甘酸温，益肾固精、缩尿、养肝明目，治肾虚遗精、遗尿尿频及肝肾不足之目暗昏花。"},{"q":"下列哪项不是桑寄生的功效","o":["祛风湿","补肝肾","强筋骨","安胎","益气"],"a":4,"e":"桑寄生苦甘平，祛风湿、补肝肾、强筋骨、安胎，治风湿痹痛、腰膝酸软及胎漏下血。益气非其所具。"},{"q":"某医师治疗湿热下注之妇人带下，擅长使用泽泻，其主要功效是","o":["利水渗湿，泄热","利水渗湿，健脾宁心","利水渗湿，健脾止泻","利尿消肿，除痹","利水消肿，清热解暑"],"a":0,"e":"泽泻甘淡寒，利水渗湿、泄热，善清下焦湿热，故治湿热下注之带下、小便淋浊，兼治水肿、泄泻、痰饮眩晕。"},{"q":"蒲公英与漏芦均善治的病证是","o":["乳痈","肠痈","肺痈","湿痹","烫伤"],"a":0,"e":"蒲公英苦甘寒，清热解毒、消肿散结、利湿通淋；漏芦苦寒，清热解毒、消痈下乳。二者均善治乳痈肿痛。"},{"q":"既能镇惊安神，又活血散瘀的药是","o":["朱砂","琥珀","桃仁","川芎","龙骨"],"a":1,"e":"琥珀甘平，镇惊安神、活血散瘀、利尿通淋，治惊风癫痫、心悸失眠及瘀血阻滞之痛经、癥瘕。"},{"q":"既能息肝风，又平肝阳，为止眩晕，定头痛要药的是","o":["钩藤","天麻","蜈蚣","全蝎","僵蚕"],"a":1,"e":"天麻甘平，息风止痉、平抑肝阳、祛风通络，其性平和，虚实寒热之眩晕头痛皆可配用，为止眩晕、定头痛之要药。"},{"q":"性味甘寒，归肺、大肠经的药物是","o":["桔梗","白前","前胡","旋覆花","胖大海"],"a":4,"e":"胖大海甘寒，归肺、大肠经，清热润肺、利咽解毒、润肠通便，治肺热声哑、干咳无痰及热结便秘。"},{"q":"能清热凉血，利尿通淋的药物是","o":["生地黄","车前子","白薇","地骨皮","紫草"],"a":2,"e":"白薇苦咸寒，清热凉血、利尿通淋、解毒疗疮，既治阴虚发热、产后虚热，又治热淋、血淋及疮痈肿毒。"},{"q":"既能治疗风湿热痹，又能治疗骨蒸潮热的药物是","o":["五加皮","狗脊","防已","桑枝","秦艽"],"a":4,"e":"秦艽辛苦平，祛风湿、通络止痛、退虚热、清湿热，为风药中之润剂，既治风湿热痹，又治骨蒸潮热。"},{"q":"能散寒止痛，理气和胃的药物是","o":["陈皮","生姜","木瓜","高良姜","小茴香"],"a":4,"e":"小茴香辛温，入肝肾脾胃经，散寒止痛、理气和胃，治寒疝腹痛、少腹冷痛及中焦寒凝气滞之脘腹胀痛。"},{"q":"具有安神，祛风通络作用的药物是","o":["磁石","灵芝","龙骨","首乌藤","远志"],"a":3,"e":"首乌藤甘平，养心安神、祛风通络，治阴虚血少之失眠多梦、心悸及血虚身痛、风湿痹痛。"},{"q":"既能平喘止咳，又能解痉、定痛的药物是","o":["胖大海","枇杷叶","马兜铃","紫苏子","洋金花"],"a":4,"e":"洋金花辛温有毒，平喘止咳、解痉定痛、麻醉，治哮喘咳嗽、胃痛腹痛及风湿痹痛，古时用作麻醉药。"},{"q":"在应用驱虫药时，为助肠寄生虫排出体外，常配伍","o":["乌梅","大黄","火麻仁","山楂","五味子"],"a":1,"e":"驱虫药多配伍大黄等泻下药，以促进虫体排出，所谓虫下宜速，同时可减轻驱虫药对肠道的刺激。"},{"q":"功效清热凉血活血，解毒透疹的药物是","o":["赤芍","紫草","生地黄","玄参","地骨皮"],"a":1,"e":"紫草甘咸寒，清热凉血、活血、解毒透疹，治温病血热毒盛之斑疹紫黑、麻疹不透及疮疡湿疹。"},{"q":"五倍子的入用部位是","o":["卵鞘","虫瘿","孢子","菌核","果实"],"a":1,"e":"五倍子为漆树科植物盐肤木等叶上寄生的五倍子蚜虫所形成的干燥虫瘿，故入药部位为虫瘿。"},{"q":"下列哪一项不属于土鳖虫的应用范围","o":["跌打损伤","血瘀经闭","癥瘕积聚","痈疽疮毒","产后瘀滞腹痛"],"a":3,"e":"土鳖虫破血逐瘀、续筋接骨，主治跌打损伤、血瘀经闭、癥瘕积聚及产后瘀滞腹痛。痈疽疮毒属攻毒蚀疮、消肿排脓类药物的适应证，非其主治范围。"},{"q":"不具有明目功效的药物是","o":["夏枯草","密蒙花","青葙子","决明子","鸭跖草"],"a":4,"e":"鸭跖草清热泻火、解毒、利水消肿，无清肝明目之功。夏枯草、密蒙花、青葙子、决明子均能清肝火而明目，为眼科常用之品。"},{"q":"能祛风解表，胜湿止痛的药组是","o":["白芷，紫苏叶","藁本，紫苏叶","防风，荆芥","麻黄，香薷","防风，羌活"],"a":4,"e":"防风顺羌活，二药均能祛风解表、胜湿止痛，为治风寒湿痹之常用组合。荆芥偏于透疹止痒，紫苏叶、香薷偏于化湿和中，胜湿止痛之力不专。"},{"q":"确定药物寒热、温凉的依据是","o":["神农氏尝百草的体会","《素问》：“寒者热之，热者寒之”","《本经》：“疗寒以热药，疗热以寒药”","药物作用于人体的反应","口尝的滋味"],"a":3,"e":"药性的寒热温凉由药物作用于人体后所产生的反应归纳而得，是与所治疾病寒热性质相对而言的用药经验总结，并非依口尝滋味或文献条文确定。"},{"q":"桂枝不具有的功效是","o":["发汗解肌","温通经脉","平冲降气","平喘利尿","助阳化气"],"a":3,"e":"桂枝发汗解肌、温通经脉、助阳化气、平冲降气，全无平喘利尿之力。平喘利尿为麻黄所长，二药虽同属辛温解表，功用各有专司。"},{"q":"下列哪项不是蛇床子的功效","o":["燥湿","化痰","祛风","温肾壮阳","杀虫止痒"],"a":1,"e":"蛇床子温肾壮阳、燥湿祛风、杀虫止痒，内治阳痿宫冷，外治阴痒湿疹。化痰非其所长，化痰之功多归于半夏、天南星一类。"},{"q":"蕲蛇的主治病证不包括","o":["风湿痹痛","筋骨痿软","中风偏瘫","麻风疥癣","急慢惊风"],"a":1,"e":"蕲蛇祛风通络、止痉，主治风湿顽痹、中风半身不遂、麻风疥癣及急慢惊风。筋骨痿软多因肝肾亏虚、筋骨失养，当用补肝肾强筋骨之品。"},{"q":"白矾火煅后称为","o":["明矾","胆矾","绛矾","枯矾","绿矾"],"a":3,"e":"白矾即明矾，火煅失去结晶水后称枯矾，收湿敛疮、止血化腐之力增强。胆矾、绿矾、绛矾各为不同矿物制品，与白矾煅品无关。"},{"q":"性寒通利，肾虚精滑无湿热者忌用的是","o":["泽泻","薏苡仁","香加皮","猪苓","茯苓"],"a":0,"e":"泽泻甘淡性寒，利水渗湿、泄热，通利之力较强，肾虚精滑而无湿热者忌用，以免耗伤肾气。茯苓、猪苓性平，薏苡仁兼能健脾。"},{"q":"湿热泻痢初起，腹痛里急后重，为清除湿热邪气，发挥通因通用作用，常在清热燥湿，行气导滞的黄连、木香中配伍","o":["白头翁","番泻叶","大黄","马齿苋","牵牛子"],"a":2,"e":"大黄苦寒沉降，泻下攻积、清热解毒，少量用于泻痢初起可通因通用，使湿热积滞从大便而去，与黄连、木香相配，清、行、下三法并行。"},{"q":"善治脏腑湿痰的药物是","o":["半夏","白前","白附子","天南星","旋覆花"],"a":0,"e":"半夏辛温而燥，主归脾胃肺经，善燥脾湿、化脏腑湿痰，为治湿痰之要药。天南星偏祛风痰，白前、旋覆花偏于降气消痰。"},{"q":"麻黄根、黄芪的共同功效是","o":["止带","止汗","止遗","止血","止泻"],"a":1,"e":"麻黄根甘涩性平，专于敛汗固表；黄芪甘温，补气固表而止汗。二药均以止汗见长，常相须用于自汗、盗汗之证。"},{"q":"为血肉有情之品的是","o":["鹿茸、阿胶","骨碎补、狗脊","鸡血藤、牛膝","鸡内金、牛黄","肉苁蓉、桑螵蛸"],"a":0,"e":"鹿茸为鹿科动物未骨化密生茸毛的幼角，阿胶由驴皮熬制而成，皆属血肉有情之品，长于填精养血、温补肾阳。"},{"q":"菊花的功效不包括","o":["疏散风热","平抑肝阳","清肝明目","升举阳气","清热解毒"],"a":3,"e":"菊花疏散风热、平抑肝阳、清肝明目、清热解毒。升举阳气为升麻、柴胡之功，非菊花所具。"},{"q":"能消食化积，止泻止痢，行气散瘀，降脂化浊的药物是","o":["黄连","山楂","木香","大黄","白头翁"],"a":1,"e":"山楂消食化积、行气散瘀、化浊降脂，尤善消肉食积滞，炒焦后兼能止泻止痢。黄连、白头翁清热燥湿治痢，木香行气，大黄攻下，均无消食降脂之全功。"},{"q":"可用于治疗白癜风的药组是","o":["鹿茸、淫羊藿","补骨脂、益智仁","巴戟天、肉苁蓉","菟丝子、沙苑子","补骨脂、菟丝子"],"a":4,"e":"补骨脂补肾壮阳、固精缩尿、温脾止泻，外用可治白癜风；菟丝子补肾益精、养肝明目，亦治白癜风，二药常相配为用。"},{"q":"长于拔毒化腐的药物是","o":["雄黄","硫磺","升药","明矾","硼砂"],"a":2,"e":"升药由水银、火硝、白矾升华制成，拔毒化腐排脓之力最强，为外科治疮疡溃后脓出不畅、腐肉不去之要药。"},{"q":"湿热黄疸患者，医生处方中有：茵陈、栀子、大黄、郁金。不宜再与本方配伍同用的药是","o":["木香","丁香","玄参","鸡内金","金钱草"],"a":1,"e":"丁香与郁金为十九畏配伍禁忌，同用易生毒副反应。方中郁金已在，故不宜再与本方配伍丁香。"},{"q":"淡渗甘补，药性平和，可治疗寒热虚实各种水肿的药物是","o":["冬瓜皮","茯苓","猪苓","车前子","泽泻"],"a":1,"e":"茯苓甘淡性平，淡渗利水兼能健脾，药性平和，寒热虚实之水肿皆可配伍应用，为利水渗湿要药。猪苓、泽泻专于渗利而无补益之力。"},{"q":"外用治皮肤瘙痒，并用于温灸的中药是","o":["槐花","炮姜","艾叶","侧柏叶","仙鹤草"],"a":2,"e":"艾叶辛苦温，温经止血、散寒止痛，外用煎汤熏洗可治皮肤瘙痒，又为温灸之常用燃料，可制成艾条、艾炷施灸。"},{"q":"下列需要煎汤代水的药物是","o":["灶心土","金银花","大黄","白芍","黄连"],"a":0,"e":"灶心土为黄土块，煎煮易糊锅且有效成分难溶出，故宜先煎取汁、去渣代水再煎他药，属煎汤代水之法。"},{"q":"内服须与豆腐同煮的药是","o":["硫黄","雄黄","白矾","胆矾","硼砂"],"a":0,"e":"硫黄酸温有毒，内服补火助阳通便，须与豆腐同煮以降低毒性、便于研末入药，外用则解毒杀虫疗疮。"},{"q":"功能利尿消肿，清热解暑的药物是","o":["玉米须","香加皮","冬瓜皮","泽泻","猪苓"],"a":2,"e":"冬瓜皮甘凉，利水消肿、清热解暑，用于水肿胀满、小便不利及暑热烦渴。玉米须偏于利湿退黄，香加皮偏于祛风湿、强筋骨。"},{"q":"宜首选升浮类药物治疗的是","o":["外感风寒","里实便秘","肝阳头痛","胃热呕吐","肺热鼻衄"],"a":0,"e":"升浮药主上行向外，多具升阳、发表、散寒、催吐之功，故外感风寒表证宜选。里实便秘、肝阳头痛、胃热呕吐等则宜沉降下行之品。"},{"q":"人参与莱菔子配伍，莱菔子削弱人参补气作用，这种关系称为","o":["相须","相使","相畏","相恶","相杀"],"a":3,"e":"相恶指两药合用，一药使另一药功效降低或丧失。莱菔子耗气，与人参同用削弱其补气之力，正属相恶。相杀则是减轻毒性。"},{"q":"细辛的性味是","o":["辛温","辛寒","苦寒","苦温","甘温"],"a":0,"e":"细辛辛温，有小毒，归心肺肾经，能解表散寒、祛风止痛、通窍、温肺化饮，其性味为辛温而非苦寒或甘温。"},{"q":"味甘能解酒毒的药物是","o":["升麻","柴胡","蝉蜕","葛根","淡竹叶"],"a":3,"e":"葛根甘辛凉，解肌退热、生津止渴、升阳止泻、通经活络，又能解酒毒，为治酒醉烦渴之常用药。"},{"q":"某女，50岁。带下色黄、质稠15天，近日又见肺热咳嗽，宜选用的药物是","o":["地肤子","萹蓄","海金沙","虎杖","茵陈"],"a":3,"e":"虎杖苦微寒，利湿退黄、清热解毒、散瘀止痛、止咳化痰，既能清下焦湿热而止带，又可清肺热止咳嗽，一药兼治两证。"},{"q":"能散寒止痛，降逆止呕，助阳止泻的药物是","o":["柴胡","葛根","附子","砂仁","吴茱萸"],"a":4,"e":"吴茱萸辛苦热，有小毒，散寒止痛、降逆止呕、助阳止泻，为治肝寒气滞诸痛及脾肾阳虚泄泻之要药，外用还能引火下行。"},{"q":"治疗表虚不固的自汗，最宜选用","o":["牡蛎","龙骨","黄芪","白芍","酸枣仁"],"a":2,"e":"黄芪甘温，补气升阳、固表止汗，表虚不固之自汗用之，能补肺脾之气而固护卫表。牡蛎、龙骨偏于收涩，白芍偏于养血敛阴。"},{"q":"阳气虚弱患者最宜选用","o":["红参","生晒参","西洋参","太子参","人参叶"],"a":0,"e":"红参经蒸制后性偏温，大补元气、复脉固脱、益气摄血，阳气虚弱者用之最宜。生晒参性平，西洋参性凉，太子参力薄。"},{"q":"内服补中、润燥，外用生肌敛疮的药物是","o":["甘草","黄芪","蜂蜜","大枣","刺五加"],"a":2,"e":"蜂蜜甘平，内服补中缓急、润肺止咳、润肠通便，外用能生肌敛疮，为药食两用之品，又可作丸剂赋形剂。"},{"q":"妊娠禁用药多为","o":["峻猛剧毒之品","破气行滞之品","活血祛瘀之品","攻下通肠之品","辛热滑利之品"],"a":0,"e":"妊娠禁用药多为峻猛剧毒之品，如砒霜、斑蝥、麝香、巴豆，用之可伤胎堕胎。破气行滞、活血祛瘀、辛热滑利者多属慎用而非禁用。"},{"q":"天南星用牛胆汁拌制的目的是","o":["降低毒性","增强疗效","改变性状","改变性能","矫臭矫味"],"a":3,"e":"天南星经牛胆汁拌制为胆南星，药性由温转凉，功用由燥湿化痰变为清热化痰、息风定惊，属改变药物性能的炮制。"},{"q":"既能内行气血、通经止痛，又能外散风寒湿邪的药是","o":["姜黄","郁金","牛膝","羌活","独活"],"a":0,"e":"姜黄辛苦温，既入血分活血行气、通经止痛，又入气分散风寒湿邪，善治肩背疼痛及血瘀气滞诸痛。"},{"q":"既能清热凉血，又能活血散瘀的药组是","o":["玄参、生地黄","地骨皮、牡丹皮","知母、黄柏","赤芍、牡丹皮","大黄、芒硝"],"a":3,"e":"赤芍、牡丹皮均能清热凉血、活血散瘀，治温病热入营血及血热瘀滞之证。玄参、生地黄偏于凉血养阴，散瘀之力不显。"},{"q":"雄黄适用于癫痫，与其具有的什么功效相关","o":["解毒","燥湿","开窍","祛痰","活血"],"a":3,"e":"雄黄辛苦温有毒，解毒杀虫、燥湿祛痰、截疟，其治癫痫、惊痫即取祛痰之功，使痰浊得化而神明自安。"},{"q":"外感风寒表证内兼湿阻中焦证治宜首选","o":["广藿香","豆蔻","五加皮","砂仁","茯苓"],"a":0,"e":"广藿香辛微温，芳香化浊、和中止呕、发表解暑，外能解表散寒，内能化湿醒脾，故外感风寒兼湿阻中焦者最为合宜。"},{"q":"虎杖对于孕妇慎用，除考量其通利作用较强外，相关因素还有","o":["清热解暑","解毒消肿","通淋排石","散瘀止痛","止咳化痰"],"a":3,"e":"虎杖苦微寒，散瘀止痛、活血通经之力较强，孕妇用之有动胎之弊，与通利二便同为其慎用之因。"},{"q":"肝阳上亢、头痛眩晕，伴胃气上逆、呕吐嗳气，最宜选用的药是","o":["赭石","石决明","生龙骨","杭白芍","灵磁石"],"a":0,"e":"赭石苦寒质重，平肝潜阳、重镇降逆、凉血止血，既降肝阳以治头痛眩晕，又降胃气以止呕吐嗳气，一药兼顾两方面病机。"},{"q":"治肺燥咳嗽宜蜜炙用的药物是","o":["菊花","桑叶","牛蒡子","蝉蜕","柴胡"],"a":1,"e":"桑叶苦甘寒，疏散风热、清肺润燥、平肝明目，蜜炙后润肺止咳之力增强，故治肺燥咳嗽宜用蜜炙品。"},{"q":"治上部出血证，止血药宜配伍的药物类别是","o":["降气药","活血药","升阳药","行气药","清热凉血药"],"a":0,"e":"治上部出血宜配伍降气药，取血随气行之义，气降则血降，使上逆之血得以下行，如赭石、旋覆花之属。"},{"q":"具有行气止痛，温肾纳气功效的药物是","o":["香附","青皮","沉香","木香","佛手"],"a":2,"e":"沉香辛苦微温，行气止痛、温中止呕、纳气平喘，其温肾纳气之力善治下元虚冷、肾不纳气之虚喘。"},{"q":"既能治疗肝阳上亢的头晕目眩，又可治疗吐血、衄血、崩漏的中药是","o":["赭石","蒺藜","珍珠","羚羊角","白僵蚕"],"a":0,"e":"赭石苦寒质重，平肝潜阳治头晕目眩，又入血分凉血止血，善治吐血、衄血、崩漏等血热妄行之证。"},{"q":"朱砂的主治病症不包括","o":["心悸失眠","惊风癫痫","疮痈肿毒","咽喉肿痛","肺热咳嗽"],"a":4,"e":"朱砂甘微寒有毒，清心镇惊、安神、明目、解毒，主治心悸失眠、惊风癫痫及疮痈肿毒、咽喉肿痛。肺热咳嗽非其所治。"},{"q":"具有敛肺止咳作用的药物大多具有何种药味","o":["辛","甘","酸","苦","咸"],"a":2,"e":"酸味能收能涩，故敛肺止咳药多具酸味，如五味子、乌梅、诃子之类，以收敛耗散之肺气而止咳。"},{"q":"白果止咳平喘的机制是","o":["宣肺","润肺","清肺","敛肺","泻肺"],"a":3,"e":"白果甘苦涩平，敛肺定喘、止带缩尿，其平喘系收敛肺气、减少肺气耗散而实现，故其机制为敛肺。"},{"q":"常用以治疗小儿夜啼不安的药物是","o":["葛根","淡豆豉","牛蒡子","蝉蜕","薄荷"],"a":3,"e":"蝉蜕甘寒，疏散风热、利咽透疹、明目退翳、息风止痉，又能安神定惊，故常用于小儿夜啼不安。"},{"q":"脾不统血、冲脉不固之虚寒性出血宜选用","o":["凉血止血药","温经止血药","收敛止血药","化瘀止血药","温肾止血药"],"a":1,"e":"温经止血药性温，能温经散寒、固冲止血，适用于脾不统血、冲脉不固之虚寒性出血，如炮姜、艾叶、灶心土。"},{"q":"不属苦参功效的是","o":["清热","燥湿","祛风","杀虫","利尿"],"a":2,"e":"苦参苦寒，清热燥湿、杀虫止痒、利尿，主治湿热泻痢、黄疸、带下阴痒及小便不利。祛风非其功效。"},{"q":"水火烫伤、痈肿疮毒，宜选","o":["大蓟","白及","地榆","侧柏叶","白茅根"],"a":2,"e":"地榆苦酸微寒，凉血止血、解毒敛疮，既善治下焦血热出血，又为治水火烫伤、痈肿疮毒之要药，可研末外敷。"},{"q":"平肝潜阳宜生用，收敛固涩宜煅用的药物是","o":["石膏","龙骨","琥珀","柏子仁","瓦楞子"],"a":1,"e":"龙骨甘涩平，生用质重镇惊、平肝潜阳、安神，煅用则收敛固涩、敛汗固精，故有生煅分用之法。"},{"q":"治疗阴虚火旺，潮热盗汗，黄柏常相须配伍的药是","o":["黄芩","黄连","栀子","知母","石膏"],"a":3,"e":"知母苦甘寒，清热泻火、滋阴润燥，与黄柏相须为用，既清下焦湿热，又泻相火、退骨蒸，为治阴虚火旺、潮热盗汗之要配。"},{"q":"有“定风草”之称，获“治风神药”之誉的药物是","o":["天麻","牛黄","珍珠","钩藤","羚羊角"],"a":0,"e":"天麻甘平，息风止痉、平抑肝阳、祛风通络，药性平和，寒热虚实之肝风皆可配用，故有定风草之称。"},{"q":"治热结旁流常以大黄配","o":["番泻叶","甘遂","芒硝","火麻仁","生地黄"],"a":2,"e":"芒硝咸苦寒，泻下攻积、润燥软坚、清热消肿，与大黄相须为用，治热结旁流之下利清水、腹满硬痛。"},{"q":"治疗外感发热，项背强痛，首选的药物是","o":["葛根","淡豆豉","牛蒡子","蝉蜕","薄荷"],"a":0,"e":"葛根甘辛凉，解肌退热、生津止渴、升阳止泻，其解肌之力善缓解项背强急，为外感发热、项背强痛之首选。"},{"q":"补血药的主要归经为","o":["肝肺经","心肾经","心肝经","心脾经","肺脾经"],"a":2,"e":"补血药多归心、肝二经，因心主血、肝藏血，补血即补心肝之血，当归、熟地黄、白芍、阿胶皆然。"},{"q":"冬虫夏草和紫河车均可用于治疗","o":["脾肾虚泻","口多唾涎","骨蒸劳嗽","肠燥便秘","筋伤骨折"],"a":2,"e":"冬虫夏草甘平，补肾益肺、止血化痰；紫河车甘咸温，温肾补精、益气养血。二者均补虚损，同治虚劳骨蒸、劳嗽。"},{"q":"紫菀与款冬花均有的功效是","o":["清肺化痰，润肠通便","消痰行水，降逆止呕","纳气平喘，固精止带","润肺下气，化痰止咳","泻肺平喘，利水消肿"],"a":3,"e":"紫菀、款冬花均性温而润，能润肺下气、化痰止咳，新久咳嗽、寒热虚实皆可配伍，常相须为用。"},{"q":"既能收敛止汗，又能镇惊安神的药物是","o":["磁石","龙骨","浮小麦","酸枣仁","五味子"],"a":1,"e":"龙骨甘涩平，镇惊安神、平肝潜阳，煅用收敛固涩而能敛汗固精，故兼具收敛止汗与镇惊安神之功。"},{"q":"上能温肺散寒以化痰饮，中能温脾运水以消痰，为寒饮喘咳之良药的是","o":["肉桂","桂枝","干姜","丁香","吴茱萸"],"a":2,"e":"干姜辛热，温中散寒、回阳通脉、温肺化饮，上能温肺散寒以化饮，中能温脾运水以消痰，为寒饮喘咳之良药。"},{"q":"治疗肝肾不足，遗尿尿频，目黯不明，脾肾虚泻。最宜选择的药物是","o":["续断","桑寄生","枸杞子","补骨脂","菟丝子"],"a":4,"e":"菟丝子甘温，补肾益精、养肝明目、固胎止泻，既能固精缩尿，又可治目暗不明及脾肾虚泻，平补而不燥。"},{"q":"性沉降下行，善治下焦血热出血的药物是","o":["蒲黄","三七","大蓟","地榆","侧柏叶"],"a":3,"e":"地榆苦酸微寒，性沉降下行，善走下焦，凉血止血，为治下焦血热所致便血、痔血、崩漏之要药。"},{"q":"治邪在少阳，寒热往来证，清半表半里之热，共收和解少阳之功，柴胡最宜配伍的药物是","o":["黄芩","黄连","黄柏","栀子","葛根"],"a":0,"e":"黄芩苦寒，善清少阳半表半里之热，与柴胡一散一清，共收和解少阳之功，为治寒热往来之经典配伍。"},{"q":"麻黄配石膏善治","o":["风水水肿","虚烦不眠","肺热喘咳","血瘀经闭","风湿痹痛"],"a":2,"e":"麻黄辛温宣肺平喘，石膏辛甘大寒清泄肺热，一宣一清、相互制约，共治肺热壅盛之喘咳。"},{"q":"杜仲、续断都能治疗的病证是","o":["肝肾不足、胎动不安","肝肾不足、阳虚冷泻","肝肾不足、肠燥便秘","肝肾不足、五更泄泻","肝肾不足、气血两虚"],"a":0,"e":"杜仲、续断均能补肝肾、强筋骨、安胎，故同治肝肾不足、胎动不安。续断兼能续筋接骨，杜仲兼能降血压。"},{"q":"治阴血不足，筋失所养的挛急疼痛，白芍常配伍","o":["麦冬","甘草","川芎","延胡索","五味子"],"a":1,"e":"白芍配甘草，酸甘化阴、缓急止痛，即芍药甘草汤，为治阴血不足、筋脉失养而挛急疼痛之基础方。"},{"q":"能清肺止咳，降逆止呕的药物是","o":["紫菀","礞石","天竺黄","枇杷叶","款冬花"],"a":3,"e":"枇杷叶苦微寒，清肺止咳、降逆止呕，既清肺热以止咳，又降胃气以止呕，蜜炙偏润肺，姜汁炙偏止呕。"},{"q":"具有补虚强壮之功，常用治脱力劳伤的药物是","o":["三七","白及","蒲黄","仙鹤草","血余炭"],"a":3,"e":"仙鹤草苦涩平，收敛止血、截疟、止痢、解毒、补虚，其补虚强壮之力可用于脱力劳伤、神疲乏力。"},{"q":"不是用炒法制成的药物是","o":["艾叶炭","炒白术","炒苏子","荆芥炭","血余炭"],"a":4,"e":"血余炭系人发闷煅而成，属煅法而非炒法。艾叶炭、荆芥炭为炒炭，炒白术、炒苏子为清炒或加辅料炒。"},{"q":"白前的功效是","o":["降气祛痰","发散风寒","润肺止咳","清热泻火","泻肺平喘"],"a":0,"e":"白前辛苦微温，降气、消痰、止咳，专于降肺气而化痰止咳，为治肺气壅实、咳嗽痰多之要药。"},{"q":"生用涌吐风痰，炒用消食化痰的药物是","o":["山楂","神曲","麦芽","莱菔子","鸡内金"],"a":3,"e":"莱菔子辛甘平，生用涌吐风痰，炒用降气化痰、消食除胀，其消食之力善治食积气滞之脘腹胀满，故有生炒异用之说。"},{"q":"拔毒化腐生肌药多含砷、汞、铅等元素，多具剧烈毒性或强大刺激性。下列使用方法中错误的是","o":["不可内服","应该视病情而确定使用","外用不可过量和过久应用","应该严格控制剂量和用法","有些药不宜用于头面及黏膜"],"a":0,"e":"此类药多含砷、汞、铅，毒性剧烈或刺激性强大，应严格掌握剂量用法、外用不可过量久用、头面黏膜处慎用。并非一律不可内服，部分可极微量入丸散。"},{"q":"主要用于肺、胃阴虚证的药物是","o":["石斛","枸杞子","北沙参","墨旱莲","女贞子"],"a":2,"e":"北沙参甘微苦微寒，养阴清肺、益胃生津，主归肺胃二经，为肺胃阴虚之燥咳、咽干口渴的常用药。"},{"q":"治胃火炽盛，牙龈肿痛，首选的药物是","o":["金银花","鱼腥草","蒲公英","山豆根","白头翁"],"a":3,"e":"山豆根苦寒有毒，清热解毒、利咽消肿，善清胃火，为治胃火炽盛、牙龈肿痛及咽喉肿痛之要药。"},{"q":"半夏的功效是","o":["燥湿化痰，祛风止痉，消痞散结","燥湿化痰，降逆止呕，通络止痛","燥湿化痰，降逆止呕，消痞散结","燥湿化痰，利气宽胸，消痞散结","燥湿化痰，祛风止痉，润肠通便"],"a":2,"e":"半夏辛温有毒，燥湿化痰、降逆止呕、消痞散结，外用消肿止痛，为治湿痰寒痰及呕吐之要药。"},{"q":"善治口中甜腻、多涎之脾瘅证的药物是","o":["香薷","佩兰","广藿香","砂仁","厚朴"],"a":1,"e":"佩兰辛平，芳香化湿、醒脾开胃、发表解暑，其化湿和中之力善除陈腐之气，故为治脾瘅口甜、多涎之要药。"},{"q":"善治寒积便秘的药物是","o":["大黄","芒硝","番泻叶","巴豆霜","牵牛子"],"a":3,"e":"巴豆霜辛热有大毒，峻下冷积、逐水退肿、豁痰利咽，其性热而善攻，故为治寒积便秘之要药。"},{"q":"治疗下元虚冷、肾不纳气之虚喘，最宜选用","o":["沉香","香附","佛手","橘皮","刀豆"],"a":0,"e":"沉香辛苦微温，行气止痛、温中止呕、纳气平喘，其纳气归元之力善治下元虚冷、肾不纳气之虚喘。"},{"q":"石决明的功效是","o":["平肝潜阳、清肺止咳","平肝潜阳、化痰开窍","平肝潜阳、息风止痉","平肝潜阳、清肝明目","平肝潜阳、解毒散结"],"a":3,"e":"石决明咸寒，平肝潜阳、清肝明目，为治肝阳上亢、头晕目眩及目赤翳障之要药，入汤剂宜打碎先煎。"},{"q":"内服不可过量或持续服用，且忌火煅的药物是","o":["磁石","牡蛎","朱砂","琥珀","珍珠母"],"a":2,"e":"朱砂甘微寒有毒，主含硫化汞，内服不可过量或久服，且忌火煅，因火煅可析出汞而使毒性剧增。"},{"q":"现代常用治真性红细胞增多症、冠心病心绞痛的药物是","o":["水蛭","莪术","三棱","虻虫","土鳖虫"],"a":0,"e":"水蛭咸苦平有小毒，破血通经、逐瘀消癥，现代常用于真性红细胞增多症、冠心病心绞痛及中风偏瘫属血瘀者。"},{"q":"党参的归经是","o":["心、脾经","心、肺经","脾、肺经","脾、肾经","肺、肾经"],"a":2,"e":"党参甘平，补中益气、健脾益肺、养血生津，主归脾、肺二经，为脾气虚、肺气虚及气血两虚之常用药。"},{"q":"下列药物需要冲服的是","o":["半夏","连翘","蒲黄","天花粉","芒硝"],"a":4,"e":"芒硝为矿物药，入汤剂极易溶解，故宜溶化冲服而不入煎。蒲黄需包煎，半夏、连翘、天花粉皆常规煎煮。"},{"q":"功能逐水通便，适用于水邪盛而正气尚能耐受攻伐，且一般利水药乏效的药物是","o":["茯苓","猪苓","轻粉","土茯苓","白花蛇舌草"],"a":2,"e":"轻粉辛寒有毒，外用杀虫攻毒，内服逐水通便，适用于水邪壅盛而正气尚耐攻伐、一般利水药无效之水肿。"},{"q":"不具有清热燥湿功效的药组是","o":["黄芩，黄连","黄芩，龙胆","黄柏，秦皮","青黛，三颗针","苦参，白鲜皮"],"a":3,"e":"青黛咸寒，清热解毒、凉血消斑、泻火定惊，不具燥湿之力。黄芩、黄连、黄柏、龙胆、秦皮、苦参、白鲜皮皆能清热燥湿。"},{"q":"肺热咳嗽，常与地骨皮配伍的药物是","o":["金银花","竹叶","决明子","桑白皮","栀子"],"a":3,"e":"桑白皮甘寒，泻肺平喘、利水消肿，与地骨皮相配即泻白散，一泻肺中伏火，一清阴分虚热，共治肺热咳嗽。"},{"q":"不具有润肠通便作用的药物是","o":["苦杏仁","桃仁","瓜蒌仁","酸枣仁","柏子仁"],"a":3,"e":"酸枣仁甘酸平，养心补肝、宁心安神、敛汗生津，无润肠通便之力。苦杏仁、桃仁、瓜蒌仁、柏子仁皆富含油脂而能润肠。"},{"q":"性味苦寒，有小毒的药物是","o":["礞石","浙贝母","黄药子","苦杏仁","天南星"],"a":2,"e":"黄药子苦寒有小毒，化痰散结消瘿、清热解毒、凉血止血，为治瘿瘤之要药，用量不宜过大。"},{"q":"既能除虚热，又能益气阴的药是","o":["麻黄根","浮小麦","山茱萸","金樱子","刺五加"],"a":1,"e":"浮小麦甘凉，固表止汗、益气、除虚热，既敛虚汗又退骨蒸劳热，故兼具除虚热与益气阴之功。"},{"q":"能养血安神的补气药是","o":["山药","党参","大枣","甘草","白芍"],"a":2,"e":"大枣甘温，补中益气、养血安神、缓和药性，为补气药中兼能养血安神之品，常用于脾虚食少及脏躁失眠。"},{"q":"下列药物尤宜于风湿顽痹，日久不愈者是","o":["独活","防己","木瓜","乌梢蛇","威灵仙"],"a":3,"e":"乌梢蛇甘平，祛风通络、止痉，性善走窜，搜风之力较强，故尤宜于风湿顽痹日久不愈、肢体麻木拘挛者。"},{"q":"为治疗肝阳上亢及目疾之要药是","o":["牡蛎","蒺藜","桑叶","石决明","羚羊角"],"a":3,"e":"石决明咸寒质重，平肝潜阳、清肝明目，既为平抑肝阳之要药，又为目赤翳障等目疾所常用。"},{"q":"银柴胡主要治疗","o":["少阳证寒热往来","表证发热","热病高热烦渴","温病伤阴，夜热早凉","阴虚发热，骨蒸劳热"],"a":4,"e":"银柴胡甘微寒，清虚热、除疳热，专退阴虚发热、骨蒸劳热及小儿疳积发热，无解表与和解少阳之功。"},{"q":"秦艽除能祛风湿外，还能","o":["补肝肾","消水肿","清虚热","治骨鲠","强筋骨"],"a":2,"e":"秦艽辛苦平，祛风湿、通络止痛、退虚热、清湿热，既能治风湿痹痛，又可退骨蒸潮热、清利湿热而退黄。"},{"q":"入汤剂，多宜后下的药物是","o":["牛黄","天麻","全蝎","钩藤","羚羊角"],"a":3,"e":"钩藤甘凉，息风定惊、清热平肝，其有效成分钩藤碱久煎易被破坏，故入汤剂宜后下，煎煮时间不宜过长。"},{"q":"栀子用治湿热黄疸，因其能","o":["泻火除烦","清热利湿","凉血解毒","消肿止痛","凉血止血"],"a":1,"e":"栀子苦寒，泻火除烦、清热利湿、凉血解毒，其清利湿热之力可使湿热从小便而去，故能治湿热黄疸。"},{"q":"既能安神，又能消肿，祛痰的药是","o":["远志","酸枣仁","首乌藤","夜交藤","合欢花"],"a":0,"e":"远志苦辛温，安神益智、祛痰开窍、消散痈肿，既能安神定志，又可祛痰开窍、消肿，为治失眠健忘及疮痈之品。"},{"q":"血虚、血寒、血瘀皆可应用，被称为“血中之圣药”的药物是","o":["当归","阿胶","制首乌","熟地黄","龙眼肉"],"a":0,"e":"当归甘辛温，补血活血、调经止痛、润肠通便，血虚能补、血瘀能通、血寒能温，故被誉为血中之圣药。"},{"q":"既能平肝潜阳、镇惊安神，又能纳气定喘的药物是","o":["龙骨","牡蛎","朱砂","磁石","石菖蒲"],"a":3,"e":"磁石咸寒，平肝潜阳、镇惊安神、聪耳明目、纳气定喘，为治肝阳上亢、心神不宁及肾虚作喘之品。"},{"q":"白术补气健脾，宜采用的炮制方法是","o":["生用","煅用","炒焦用","炒炭用","麸炒用"],"a":4,"e":"白术麸炒后健脾和胃之力增强，故补气健脾宜麸炒用。生白术偏于燥湿利水，炒焦则偏于健脾止泻。"},{"q":"患者肾阳不足，精血亏虚，眩晕耳鸣，阴疽日久不敛，尤宜选用的药物是","o":["杜仲","鹿茸","核桃仁","菟丝子","韭菜子"],"a":1,"e":"鹿茸甘咸温，补肾阳、益精血、强筋骨、调冲任、托疮毒，既治肾阳不足、精血亏虚之眩晕耳鸣，又治阴疽日久不敛。"},{"q":"大黄粉生用治疗上消化道出血，是因其能","o":["收敛止血","凉血止血","温经止血","泻火解毒","泻下攻积"],"a":1,"e":"大黄苦寒，生用研粉内服能凉血止血，使热清血宁而血止，兼可泻火解毒、逐瘀，故治上消化道出血有效。"},{"q":"治疗湿痹、筋脉拘挛、吐泻转筋病证，最宜选用的药物是","o":["木瓜","防己","豨莶草","秦艽","伸筋草"],"a":0,"e":"木瓜酸温，舒筋活络、和胃化湿，善治湿痹拘挛、腰膝酸重及吐泻转筋，为治转筋之要药。"},{"q":"擅治肝郁气滞证的药物是","o":["陈皮","枳实","香附","木香","砂仁"],"a":2,"e":"香附辛微苦微甘平，疏肝解郁、理气宽中、调经止痛，主归肝经，为疏肝理气之要药，故称气病之总司、女科之主帅。"},{"q":"易损害肾脏，肾功能不全者禁用的药物是","o":["半夏","浮海石","胖大海","海蛤壳","马兜铃"],"a":4,"e":"马兜铃苦微寒，清肺降气、止咳平喘、清肠消痔，含马兜铃酸，易致肾损害，肾功能不全者禁用。"},{"q":"治疗虚寒泄泻，宜用","o":["黄芩","丁香","黄连","吴茱萸","小茴香"],"a":3,"e":"吴茱萸辛苦热，散寒止痛、降逆止呕、助阳止泻，其温脾助阳之力善治脾肾阳虚、五更泄泻之虚寒泄泻。"},{"q":"豨莶草治风湿痹痛兼高血压病的患者常配伍","o":["臭梧桐","独活","雷公藤","羌活","威灵仙"],"a":0,"e":"臭梧桐辛苦甘凉，祛风湿、通经络、平肝降压，与豨莶草相配，既治风湿痹痛，又兼降血压，故为常用配伍。"},{"q":"白前与旋覆花均具有的功效是","o":["降气消痰","降逆止呕","疏散风热","利气散结","凉血止血"],"a":0,"e":"白前、旋覆花均能降气消痰，白前偏于止咳，旋覆花兼能降逆止呕、行水，二药常同用于痰壅气逆之咳喘。"},{"q":"治疗感冒发热，寒热往来，首选的药物是","o":["葛根","升麻","牛蒡子","蝉蜕","柴胡"],"a":4,"e":"柴胡辛苦微寒，解表退热、疏肝解郁、升举阳气，其透表泄热之力善治外感发热及邪在半表半里之寒热往来。"},{"q":"葛根的功效不包括","o":["生津止渴","通经活络","升阳止泻","活血止痛","解肌退热"],"a":3,"e":"葛根解肌退热、生津止渴、升阳止泻、通经活络、解酒毒，无活血止痛之功。活血止痛多为川芎、延胡索所长。"},{"q":"安神药主归","o":["心、脾经","肝、胆经","心、肝经","肝、肾经","心、肺经"],"a":2,"e":"安神药主归心、肝二经，因心主神明、肝藏魂，心神不宁与肝魂不安密切相关，故其归经多在心肝。"},{"q":"药性和缓，且微温不烈，外感风寒、风热表证均可，还用于疮疡初起兼有表证的药物是","o":["桂枝","荆芥","苍耳子","香薷","紫苏叶"],"a":1,"e":"荆芥辛微温，药性和缓，长于发表散风、透疹消疮，风寒风热表证皆可配伍，疮疡初起兼表证者亦宜。"},{"q":"既能清虚热，又能解毒疗疮的药物是","o":["连翘","黄连","银柴胡","胡黄连","白薇"],"a":4,"e":"白薇苦咸寒，清热凉血、利尿通淋、解毒疗疮，既清虚热而退骨蒸，又能解毒疗疮，故阴虚发热兼疮疡者尤宜。"},{"q":"既能发汗解表，又能利水消肿的一组药物是","o":["麻黄、香薷","香薷、紫苏叶","荆芥、防风","紫苏、生姜","麻黄、桂枝"],"a":0,"e":"麻黄、香薷均能发汗解表、利水消肿，麻黄兼宣肺平喘，香薷兼化湿和中，故同具解表与利水两功。"},{"q":"续断常用于治疗的病证有","o":["气滞血瘀、痰热互结","痰热咳喘、湿热泻痢","跌扑损伤、筋伤骨折","五更泄泻、腰膝酸软","肾虚作喘、筋伤骨折"],"a":2,"e":"续断苦辛微温，补肝肾、强筋骨、续折伤、止崩漏，其续筋接骨之力善治跌扑损伤、筋伤骨折。"},{"q":"麻黄的功效是","o":["发汗解表，利水平喘，散寒止痛","发汗解表，宣肺平喘，利水消疮","发汗解表，宣肺平喘，利水消肿","发汗解表，宣肺平喘，通阳散结","发汗解表，宣肺平喘，化湿通淋"],"a":2,"e":"麻黄辛微苦温，发汗解表、宣肺平喘、利水消肿，为治风寒表实无汗及肺气壅遏喘咳之要药。"},{"q":"下列哪一项不属于苏木的主治范围","o":["跌打损伤","痈肿疮毒","心腹瘀痛","耳鸣耳聋","血瘀经闭"],"a":3,"e":"苏木甘咸辛平，活血疗伤、祛瘀通经，主治跌打损伤、心腹瘀痛、血瘀经闭及痈肿疮毒。耳鸣耳聋非其所治。"},{"q":"升降浮沉是指","o":["药物的作用趋向性","药物的作用部位的选择性","药物有无毒副作用","药物性能峻猛与否","药物有无补泻作用"],"a":0,"e":"升降浮沉指药物对人体作用的不同趋向性，升浮主上行向外，沉降主下行向内，反映药物作用的趋向而非作用部位。"},{"q":"血热夹瘀之出血病证，宜选用的药物是","o":["地榆","茜草","侧柏叶","血余炭","白茅根"],"a":1,"e":"茜草苦寒，凉血化瘀止血，既清血热又行血瘀，止血而不留瘀，故为血热夹瘀出血之要药。"},{"q":"功能袪风湿，利关节，解毒。有生泄熟补特点的药物是","o":["豨莶草","臭梧桐叶","海桐皮","络石藤","老鹳草"],"a":0,"e":"豨莶草辛苦寒，祛风湿、利关节、解毒、降血压，生用苦寒清泄，酒蒸后性温而补益肝肾，故有生泄熟补之说。"},{"q":"痰饮水肿，夜盲眼目昏涩，治宜选用的药物是","o":["茯苓","苍术","泽泻","厚朴","地肤子"],"a":1,"e":"苍术辛苦温，燥湿健脾、祛风散寒、明目，既治痰饮水肿、湿阻中焦，又能治夜盲及眼目昏涩。"},{"q":"下列哪项不是穿山甲的功效","o":["活血消癥","通经下乳","搜风通络","消肿排脓","消积止痛"],"a":4,"e":"穿山甲咸微寒，活血消癥、通经下乳、消肿排脓、搜风通络，为治癥瘕、乳汁不通及疮痈肿毒之品，无消积止痛之功。"},{"q":"蜜炙黄芪一般不用于","o":["肺气亏虚","气血不足","中气下陷","脾气亏虚","疮疡脓成不溃"],"a":4,"e":"蜜炙黄芪长于补气升阳，用于肺脾气虚、中气下陷、气血不足。疮疡脓成不溃须托毒排脓，宜用生黄芪而非蜜炙。"},{"q":"具有消风祛斑作用，可用于斑秃、白癜风的活血药是","o":["苏木","土鳖虫","马钱子","骨碎补","自然铜"],"a":3,"e":"骨碎补苦温，补肾强骨、续伤止痛，外用能消风祛斑，故用于斑秃、白癜风，又为治跌扑闪挫、筋伤骨折之品。"},{"q":"白鲜皮与防风的共同主治是","o":["麻疹不透","鼻渊头痛","风寒感冒","破伤风证","风疹瘙痒"],"a":4,"e":"白鲜皮、防风均能祛风止痒，同治风疹瘙痒。白鲜皮兼清热燥湿，防风兼胜湿止痛、止痉，主治各有侧重。"},{"q":"既可清肺化痰、利咽开音，又可润肠通便的药为","o":["白果","菊花","贝母","胖大海","苦杏仁"],"a":3,"e":"胖大海甘寒，清肺化痰、利咽开音、润肠通便，为治肺热声哑、咽喉肿痛及燥热便秘之常用药。"},{"q":"干姜治疗亡阳证常与哪项配伍","o":["生姜","炮姜","肉桂","附子","高良姜"],"a":3,"e":"干姜温中散寒、回阳通脉，附子回阳救逆，二者相须为用，即四逆汤之意，共治亡阳厥逆、脉微欲绝。"},{"q":"下列除哪项以外均是木香的主治病证","o":["肝胆失疏之湿热黄疸","脾胃气虚之食少吐泻","下痢腹痛、里急后重","脾胃气滞之脘腹胀痛","肺气不宣之咳嗽痰多"],"a":4,"e":"木香辛苦温，行气止痛、健脾消食，主治脾胃气滞脘腹胀痛、泻痢里急后重、脾虚食少吐泻及湿热黄疸。咳嗽痰多非其所治。"},{"q":"中药炮制的常用液体辅料不含以下哪项","o":["油","蜜","醋","姜汁","盐水"],"a":0,"e":"液体辅料主要有酒、醋、蜂蜜、姜汁、盐水、米泔水、甘草汁等。油多作炙法的加热介质，不列为常用液体辅料。"},{"q":"药性苦寒，善清利肌表之湿热而解毒疗疮，用于湿疮瘙痒的是","o":["金钱草","虎杖","茵陈","萆薢","石韦"],"a":2,"e":"茵陈苦辛微寒，清利湿热、利胆退黄，善清脾胃肝胆湿热，外用煎汤熏洗可治湿疮瘙痒，为治黄疸之要药。"},{"q":"来源于石竹科植物孩儿参的块根的是","o":["人参","党参","玄参","太子参","南沙参"],"a":3,"e":"太子参为石竹科植物孩儿参的干燥块根，益气健脾、生津润肺，功似人参而力薄，为清补之品。"},{"q":"辛温有毒，性善走窜，通达内外，功似全蝎而止痉之力尤甚的是","o":["地龙","蜈蚣","僵蚕","蝉蜕","蕲蛇"],"a":1,"e":"蜈蚣辛温有毒，息风镇痉、攻毒散结、通络止痛，性善走窜，通达内外，止痉之力较全蝎更强。"},{"q":"出血兼有瘀滞者，不宜选用的药物是","o":["蒲黄","藕节","棕榈炭","花蕊石","血余炭"],"a":2,"e":"棕榈炭苦涩平，收敛止血而偏于收涩，易致留瘀，故出血兼有瘀滞者不宜单用。蒲黄、花蕊石、血余炭均兼能化瘀。"},{"q":"善治头痛，无论风寒、风热、风湿、血瘀、血虚皆可随证选用的是","o":["羌活","藁本","白芷","川芎","细辛"],"a":3,"e":"川芎辛温，活血行气、祛风止痛，上行头目，为治头痛之要药，风寒、风热、风湿、血瘀、血虚头痛皆可随证配伍。"},{"q":"具有行气调中止痛功效的药物是","o":["柿蒂","香附","木香","乌药","薤白"],"a":2,"e":"木香辛苦温，行气调中止痛、健脾消食，善通行脾胃气滞，为治脘腹胀痛、泻痢后重之要药。"},{"q":"理气药中，能降气止呃的是","o":["甘松","乌药","柿蒂","荔枝核","土木香"],"a":2,"e":"柿蒂苦涩平，专入胃经，降气止呃，为治呃逆之要药，寒热虚实皆可随证配伍，虚寒者常配丁香、人参。"},{"q":"具有固精缩尿、明目、止泻功效的药物有","o":["肉苁蓉","菟丝子","补骨脂","淫羊藿","益智仁"],"a":1,"e":"菟丝子甘温，补肾益精、养肝明目、固精缩尿、固胎止泻，故兼具固精缩尿、明目、止泻三功。"},{"q":"治疗阴虚血热的出血证，宜首选","o":["艾叶","茜草","三七","仙鹤草","墨旱莲"],"a":4,"e":"墨旱莲甘酸寒，滋阴益肾、凉血止血，善治阴虚血热之吐血、衄血、尿血、崩漏，为二至丸的组成药之一。"},{"q":"细辛的主治病证不包括","o":["风寒表证","阳虚外感","肺热喘咳","头风头痛","风寒湿痹"],"a":2,"e":"细辛辛温，解表散寒、祛风止痛、通窍、温肺化饮，主治风寒表证、阳虚外感、头风头痛、鼻渊及风寒湿痹。肺热喘咳非其所宜。"},{"q":"下列哪项不是寒凉性所表示的作用","o":["清热","凉血","泻火","化湿","解热毒"],"a":3,"e":"寒凉药多具清热、泻火、凉血、解毒之功，主治热证。化湿多由苦温芳香之品所具，与寒凉药性无对应关系。"},{"q":"以下哪类药物不属于妊娠禁用药","o":["剧毒药，如砒霜","破血逐瘀药，如三棱","破气行滞药，如枳实","峻下逐水药，如牵牛子","辛香走窜力强药，如麝香"],"a":2,"e":"妊娠禁用药包括剧毒药、破血逐瘀药、峻下逐水药及辛香走窜力强者。破气行滞之品如枳实属慎用药，非禁用。"},{"q":"肝郁气滞，月经不调，下列药物首选","o":["陈皮","青皮","香附","薤白","木香"],"a":2,"e":"香附辛微苦微甘平，疏肝解郁、理气宽中、调经止痛，为妇科调经之要药，故肝郁气滞、月经不调者首选。"},{"q":"磁石的功效不包括","o":["平肝潜阳","镇静安神","聪耳明目","息风止痉","纳气定喘"],"a":3,"e":"磁石咸寒，平肝潜阳、镇惊安神、聪耳明目、纳气定喘，无息风止痉之力。息风止痉多为羚羊角、钩藤、天麻所长。"},{"q":"治疗尿频遗尿、腹中冷痛、口多唾涎常选用的药物是","o":["补骨脂","肉苁蓉","益智仁","核桃仁","淫羊藿"],"a":2,"e":"益智仁辛温，暖肾固精缩尿、温脾止泻摄唾，既治肾虚遗尿尿频，又治脾寒腹中冷痛及口多唾涎。"},{"q":"能解鱼蟹及半夏、天南星毒的药物是","o":["生姜","藿香","紫苏叶","香薷","白芷"],"a":0,"e":"生姜辛温，解表散寒、温中止呕、化痰止咳，又能解鱼蟹毒及半夏、天南星之毒，故为常用解毒之品。"},{"q":"患者，男，52岁。患肾病多年，水肿、小便不利，舌质暗，有瘀斑。证属水瘀互阻之水肿。最宜选用的药是","o":["丹参","红花","桃仁","益母草","车前子"],"a":3,"e":"益母草辛苦微寒，活血调经、利水消肿、清热解毒，既能活血化瘀，又能利水消肿，故水瘀互阻之水肿最宜。"},{"q":"患者产后血虚，低热不退，治疗宜与当归、人参同用的药物是","o":["生石膏","白薇","青蒿","白芍","熟地黄"],"a":1,"e":"白薇苦咸寒，清热凉血、益阴除热，善治产后血虚发热及阴虚内热，与当归、人参同用可养血益气而退虚热。"},{"q":"尤善清心经实火的药组是","o":["石膏、知母","黄芩、龙胆","芦根、黄芩","黄柏、连翘","黄连、栀子"],"a":4,"e":"黄连、栀子均苦寒，善清心经实火，黄连尤长于清心胃之火，栀子兼能导热下行，故为清心经实火之常用组合。"},{"q":"月季花的功效是","o":["活血调经，疏肝解郁","活血调经，凉血祛风","活血行气，通络止痛","活血行气，下乳消痈","活血补血，调经止痛"],"a":0,"e":"月季花甘淡微苦平，活血调经、疏肝解郁，既调经又疏肝，为治肝郁气滞、月经不调及跌打损伤之品。"},{"q":"治疗湿热黄疸，肝火头痛，应首选的药是","o":["夏枯草","天麻","龙胆","菊花","白鲜皮"],"a":2,"e":"龙胆苦寒，归肝胆经，善清肝胆实火与下焦湿热，既能清肝火治头痛目赤，又能利湿退黄治湿热黄疸，为肝胆湿热诸证之要药。"},{"q":"金钱草是全草入药，其法定的入药品种是","o":["豆科植物过路黄","唇形科植物活血丹","报春花科植物过路黄","伞形科植物白毛胡天荽","旋花科植物马蹄金"],"a":2,"e":"金钱草为报春花科植物过路黄的干燥全草，同科同名者方为正品；豆科过路黄与唇形科活血丹均非法定品种。"},{"q":"大血藤与败酱草的共同功效是","o":["祛瘀止痛","祛风止痛","散寒止痛","行气止痛","消食止痛"],"a":0,"e":"大血藤活血祛风止痛，败酱草消痈排脓兼祛瘀止痛，二者共有祛瘀止痛之功，故常用于瘀阻腹痛及肠痈。"},{"q":"雄黄内服的用量范围是","o":["0.05～0.1g","0.1～0.2g","0.15～0.2g","0.5～1g","1～2g"],"a":0,"e":"雄黄辛温有毒，内服只入丸散，每次0.05～0.1g，且宜暂用不可久服，以免砷蓄积中毒。"},{"q":"水牛角不具有的功效是","o":["清心","凉血","活血","解毒","定惊"],"a":2,"e":"水牛角苦寒，功能清热凉血、解毒定惊，兼能清心热，并无活血之力；活血为赤芍、牡丹皮之长。"},{"q":"用治两侧头痛宜首选","o":["归太阳经的药物","归太阴经的药物","归阳明经的药物","归少阳经的药物","归厥阴经的药物"],"a":3,"e":"手足少阳经循行于头之两侧，两侧头痛属少阳经病位，故选用归少阳经的引经药，如柴胡、川芎。"},{"q":"柴胡与薄荷均具有的功效是","o":["疏肝","透疹","升阳","解毒","明目"],"a":0,"e":"手足少阳经循行于头之两侧，两侧头痛属少阳经病位，故宜选用归少阳经的引经药，如柴胡、川芎、蔓荆子。"},{"q":"药性苦、涩，凉，主要用于治疗绦虫病的药物是","o":["雷丸","槟榔","苦楝皮","鹤草芽","使君子"],"a":3,"e":"柴胡疏肝解郁、升举阳气，薄荷疏散风热、清利头目兼能疏肝，二者共有疏肝之功，肝郁气滞者常相须为用。"},{"q":"临床常用党参代替人参入药，以下病证中不宜应用党参的是","o":["脾虚食少便溏","气虚津伤口渴","肺气虚之咳喘","元气虚极欲脱证","气血两虚之头晕心悸"],"a":3,"e":"党参补中益气、生津养血，力较人参平和，可代治脾肺气虚及气血两虚；元气虚极欲脱须用人参大补元气、复脉固脱。"},{"q":"牛膝、益母草均有的功效是","o":["活血、破气","活血、生肌","活血、润肠","活血、利水","活血、解毒"],"a":3,"e":"党参补中益气、生津养血，力较人参平和，可代治脾肺气虚及气血两虚诸证；元气虚极欲脱须用人参大补元气、复脉固脱。"},{"q":"治乳痈、乳癖、乳房胀痛，宜选用的药物是","o":["夏枯草","淡竹叶","青葙子","决明子","密蒙花"],"a":0,"e":"牛膝活血通经、补肝肾强筋骨，益母草活血调经、利水消肿，二者共有活血利水之功，血瘀经闭兼水肿者常同用。"},{"q":"下列哪项不属于中药配伍的目的","o":["增强疗效","减轻毒副作用","扩大治疗范围","增加药物的反应性","适应复杂病情"],"a":3,"e":"中药配伍旨在增强疗效、减轻毒副作用、扩大治疗范围并适应复杂病情；增加药物反应性属不良反应，不是配伍目的。"},{"q":"属于配伍禁忌的是","o":["人参与藜芦","人参与海藻","人参与大戟","人参与莱菔子","人参与五倍子"],"a":0,"e":"中药配伍旨在增强疗效、减轻毒副作用、扩大治疗范围并适应复杂病情；增加药物反应性属不良反应，不是配伍目的。"},{"q":"煅龙骨功效长于","o":["平肝潜阳","息风止痉","收敛固涩","聪耳明目","镇惊安神"],"a":2,"e":"龙骨生用镇惊安神、平肝潜阳，煅后质地疏松，长于收敛固涩，用于遗精、崩漏等滑脱诸证。"},{"q":"能上助心阳，中温脾阳，下补肾阳的药物是","o":["附子","花椒","细辛","高良姜","吴茱萸"],"a":0,"e":"附子大辛大热，上助心阳以通脉，中温脾阳以散寒，下补肾阳以益火，为回阳救逆之要药。"},{"q":"均具有袪风湿，通络止痛功效的药物是","o":["秦艽、五加皮、威灵仙","威灵仙、秦艽、海桐皮","桑寄生、秦艽、松节","狗脊、威灵仙、寻骨风","秦艽、千年健、海风藤"],"a":1,"e":"威灵仙、秦艽、海桐皮均能祛风湿、通络止痛，为治疗风湿痹痛、肢体麻木疼痛之常用组合。"},{"q":"鸡血藤、当归的共同功效是","o":["补血、活血","补血、止血","活血、止血","凉血、活血","活血、行气"],"a":0,"e":"威灵仙、秦艽、海桐皮均能祛风湿、通络止痛，为治疗风湿痹痛、肢体麻木疼痛之常用组合，寒湿偏盛者尤宜。"},{"q":"关于朱砂的用法用量及使用注意，不正确的是","o":["孕妇忌服","宜暂用，不可久服","研末服，每次0、3~1g","醋淬，打碎后装瓶备用","肝肾功能不全者忌服"],"a":3,"e":"朱砂质重难溶，只宜水飞研末冲服或入丸散，不可火煅醋淬，煅后析出游离汞而毒性大增。"},{"q":"具有凉肝息风作用的药物是","o":["温热药","寒凉药","升浮药","平性药","甘淡药"],"a":1,"e":"药性寒凉者多具清热、泻火、凉血、解毒之功，凉肝息风亦属其范畴；补肾助阳为温热药所主。"},{"q":"以下哪个是云南的道地药材","o":["阿胶","三七","附子","人参","菊花"],"a":1,"e":"药性寒凉者多具清热、泻火、凉血、解毒之功，凉肝息风亦属其范畴；补肾助阳为温热药所主，非寒凉药所能。"},{"q":"性味甘，平。功能祛风，通络，活血，下乳的药物是","o":["老鹳草","雷公藤","海桐皮","丝瓜络","络石藤"],"a":3,"e":"三七为五加科植物三七的根，主产云南文山，为云南道地药材，素有金不换之称，尤善止血化瘀、消肿定痛。"},{"q":"川贝母与浙贝母相同的功效是","o":["润肺止咳，开郁","温肺化痰，止咳","清热化痰，散结","清热化痰，开郁","润肺化痰，散结"],"a":2,"e":"丝瓜络甘、平，功能祛风通络、活血下乳，善治风湿痹痛、筋脉拘挛及乳汁不通、胸胁胀痛。"},{"q":"下列哪项是甘味药的作用","o":["温中止痛","缓急止痛","理气止痛","化瘀止痛","祛风止痛"],"a":1,"e":"甘味药能补、能缓、能和，故有缓急止痛之功，多用于脘腹四肢挛急疼痛；温中、理气、化瘀非甘味所主。"},{"q":"木香、黄连均可治疗","o":["脾虚证","食积腹痛","胃热呕吐","湿热痢疾","脾胃气滞证"],"a":3,"e":"甘味药能补、能缓、能和，故有缓急止痛之功，多用于脘腹四肢挛急疼痛，如白芍、甘草、饴糖之属。"},{"q":"患者阴虚发热，骨蒸潮热，心烦盗汗，宜选用","o":["牡丹皮","地骨皮","栀子","竹叶","黄芩"],"a":1,"e":"木香行气止痛，黄连清热燥湿，二者相配即香连丸，善治湿热痢疾、腹痛里急后重，为治痢之常用配伍。"},{"q":"为治疗肝胃不和，呕吐，吐酸要药的是","o":["生姜","紫苏","藿香","竹茹","吴茱萸"],"a":4,"e":"地骨皮甘寒，凉血退蒸、清肺降火，善治阴虚发热、骨蒸潮热、盗汗及肺热咳嗽，兼能生津止渴。"},{"q":"既能活血补血，又能舒筋活络的药是","o":["大血藤","鸡血藤","络石藤","忍冬藤","首乌藤"],"a":1,"e":"吴茱萸辛苦热，疏肝下气、散寒止痛，为治肝胃不和之呕吐吞酸、巅顶头痛之要药，如吴茱萸汤。"},{"q":"某医师治疗诸淋涩痛，擅用海金沙，此药味甘、咸，性寒。其主要功效是","o":["清热利尿，通气下乳","利尿通淋，活血通经","清热利尿，通淋","清热利湿，通淋止痛","利尿通淋，凉血止血"],"a":3,"e":"鸡血藤苦甘温，活血补血、舒筋活络，血虚血瘀之月经不调及风湿痹痛、肢体麻木均宜，兼治血虚萎黄。"},{"q":"善清大肠湿热及血分热毒的药物是","o":["鱼腥草","紫花地丁","金荞麦","蒲公英","白头翁"],"a":4,"e":"白头翁苦寒，归大肠经，清热解毒、凉血止痢，善清大肠湿热及血分热毒，为热毒血痢要药。"},{"q":"平补肺脾肾之气阴，且补而兼涩、补而不腻的药物是","o":["党参","山药","黄芪","人参","太子参"],"a":1,"e":"山药甘平，补脾养胃、生津益肺、补肾涩精，平补肺脾肾气阴而兼收涩，补而不腻，为平补三焦之良药。"},{"q":"小便涩痛，淋沥不尽者，宜选用的药物是","o":["槐花","茜草","白茅根","花蕊石","苎麻根"],"a":2,"e":"白茅根甘寒，凉血止血、清热利尿，善治湿热下注之小便涩痛、淋沥不尽及血淋，又能清肺胃之热而治热病烦渴。"},{"q":"治疗惊风抽搐，破伤风，宜首选的药物是","o":["葛根","升麻","牛蒡子","蝉蜕","薄荷"],"a":3,"e":"蝉蜕甘寒，疏散风热、利咽透疹、明目退翳，又能息风止痉，故惊风抽搐、破伤风及小儿夜啼常用。"},{"q":"不属于桑螵蛸主治病证的是","o":["白浊","崩漏","阳痿","遗尿尿频","遗精滑精"],"a":1,"e":"桑螵蛸甘咸平，固精缩尿、补肾助阳，主治遗精滑精、遗尿尿频、白浊及阳痿；崩漏非其所主。"},{"q":"二、八月最宜采集的药材是","o":["叶类","花类","全草类","果实类","根及根茎类"],"a":4,"e":"根及根茎类药材宜在秋末春初即二月、八月采收，此时有效成分贮积最多，产量与质量俱佳。"},{"q":"治疗阴痒，湿疹瘙痒，蛔虫腹痛，宜选","o":["花椒","胡椒","干姜","吴茱萸","小茴香"],"a":0,"e":"根及根茎类药材宜在秋末春初即二月、八月采收，此时有效成分贮积最多，产量与质量俱佳，人参、甘草皆然。"},{"q":"因含微量砷，不宜长期服用的药物是","o":["赭石","蒺藜","牡蛎","天麻","钩藤"],"a":0,"e":"花椒辛热，温中止痛、杀虫止痒，外用煎汤熏洗可治阴痒、湿疹瘙痒，内服治蛔虫腹痛及寒湿吐泻。"},{"q":"丹参与郁金的共同功效是","o":["活血、行气","活血、退黄","活血、养血","活血、利水","活血、凉血"],"a":4,"e":"丹参活血祛瘀、凉血消痈，郁金活血止痛、行气解郁、清心凉血，二者共有活血凉血之功。"},{"q":"治温病后期，阴虚发热，无汗骨蒸，宜首选的药物是","o":["青蒿","银柴胡","牡丹皮","玄参","地骨皮"],"a":2,"e":"丹参活血祛瘀、凉血消痈，郁金活血止痛、行气解郁、清心凉血，二者共有活血凉血之功，皆可用于血热瘀滞之证。"},{"q":"具有补益肝肾、安胎、明目功效的药物是","o":["杜仲","续断","鹿茸","菟丝子","紫河车"],"a":3,"e":"牡丹皮苦辛微寒，清热凉血、活血散瘀，善清透阴分伏热，为温病后期无汗骨蒸之要药，又能活血消痈。"},{"q":"下列药物性味辛、苦，微温。功能祛风除湿，通络止痛的是","o":["丁公藤","伸筋草","海风藤","青风藤","路路通"],"a":2,"e":"菟丝子甘温，补肾益精、养肝明目、固胎止泄，为补益肝肾、安胎明目之常用药，兼能固精缩尿。"},{"q":"治扭挫伤痛，宜选用的药物是","o":["夏枯草","密蒙花","青葙子","决明子","栀子"],"a":4,"e":"海风藤辛、苦，微温，祛风湿、通络止痛，善治风寒湿痹之关节疼痛、筋脉拘挛，常与独活、威灵仙同用。"},{"q":"荆芥炭长于","o":["祛风","止血","透疹","消疮","止痛"],"a":1,"e":"栀子苦寒，清热泻火、凉血解毒，研末醋调外敷能消肿止痛，故扭挫伤痛常用，内服兼可凉血解毒。"},{"q":"大黄泻下攻积，最宜用于","o":["阴虚肠燥便秘","血虚肠燥便秘","津枯肠燥便秘","实热积滞便秘","食积腹痛便秘"],"a":3,"e":"大黄苦寒沉降，泻下攻积、荡涤肠胃，最宜实热积滞之便秘腹满；津亏肠燥者须配养阴生津之品。"},{"q":"石膏配伍知母属于中药“七情”中的","o":["相使","相须","相杀","相畏","相反"],"a":1,"e":"石膏与知母同属清热泻火药，配伍后清泻气分实热之力显著增强，属七情中的相须，为白虎汤核心配伍。"},{"q":"板蓝根与大青叶除均能清热解毒外，还能","o":["凉血","定惊","驱虫","利尿","下乳"],"a":0,"e":"石膏与知母同属清热泻火药，配伍后清泻气分实热之力显著增强，属七情中的相须，为白虎汤核心配伍。"},{"q":"治血热毒盛，斑疹色紫黑，宜首选","o":["玄参","生地黄","蝉蜕","紫草","赤芍"],"a":3,"e":"板蓝根与大青叶同出一源，均能清热解毒、凉血消斑，善治温毒发斑、丹毒、痄腮及喉痹肿痛。"},{"q":"解表药的药味及归经是","o":["苦，入心","咸，入肾","甘，入脾","辛，入肺","酸，入肝"],"a":3,"e":"解表药味多辛，能散能行，主归肺与膀胱经，肺主皮毛，故能发散表邪、宣肺止咳、通调水道。"},{"q":"陈皮与青皮的功效区别是","o":["青皮补气，陈皮破气","陈皮补气，青皮破气","青皮理脾胃之气，陈皮理肝气","陈皮兼能化痰，青皮兼能活血","陈皮理脾胃之气，青皮破肝胆之气"],"a":4,"e":"解表药味多辛，能散能行，主归肺与膀胱经，肺主皮毛，故能发散表邪、宣肺止咳、通调水道，其性升浮而主表。"},{"q":"治外感风寒表实无汗之要药是","o":["石膏","升麻","生姜","柴胡","麻黄"],"a":4,"e":"陈皮理气健脾、燥湿化痰，主理脾胃之气，性较缓和；青皮疏肝破气、消积化滞，主破肝胆之气。"},{"q":"桑螵蛸的入用部位是","o":["虫卵","卵鞘","若虫","成虫","内壳"],"a":1,"e":"桑螵蛸为螳螂科昆虫大刀螂、小刀螂或巨斧螳螂的干燥卵鞘，并非虫体本身，故入药部位为卵鞘。"},{"q":"善治痈肿疔疮、目赤肿痛、胃火牙痛的药物是","o":["秦皮","黄连","知母","龙胆","苦参"],"a":1,"e":"黄连大苦大寒，清热燥湿、泻火解毒，善清心胃之火，为痈肿疔疮、目赤肿痛、胃火牙痛之要药。"},{"q":"功能理气止痛、祛寒散滞，可以治疗肝胃气痛的药物是","o":["青皮","沉香","香附","陈皮","荔枝核"],"a":4,"e":"黄连大苦大寒，清热燥湿、泻火解毒，善清心胃之火，为痈肿疔疮、目赤肿痛、胃火牙痛之要药，亦治湿热泻痢。"},{"q":"既治头晕目眩，又治呕吐噫气的药物是","o":["赭石","枇杷叶","石决明","珍珠母","旋覆花"],"a":0,"e":"荔枝核甘温，理气止痛、祛寒散滞，善治肝经寒凝气滞之疝气疼痛及肝胃气痛，常与小茴香同用。"},{"q":"既能解毒杀虫疗疮，又能补火助阳通便的药是","o":["硫黄","麻黄","大黄","雄黄","牛黄"],"a":0,"e":"赭石苦寒质重，平肝潜阳、重镇降逆，既治肝阳上亢之头晕目眩，又降胃气治呕吐噫气，兼能凉血止血。"},{"q":"生姜与干姜共同的功效是","o":["止呕，止泻","解表，化饮","理气，助阳","温中，温肺","通脉，解毒"],"a":2,"e":"官方答案为【理气，助阳】，但依据教材，正确答案为【温中，温肺】。生姜温中止呕、温肺止咳，干姜温中散寒、温肺化饮，共有温中温肺之功。"},{"q":"下列哪项不属于蛇床子的适用范围","o":["湿疹","疥癣","湿痹腰痛","虫蛇咬伤","宫冷不孕"],"a":3,"e":"蛇床子辛苦温，燥湿祛风、杀虫止痒、温肾壮阳，主治阴痒湿疹、疥癣及宫冷不孕；虫蛇咬伤非其所治。"},{"q":"具有解毒润肠作用，可用于痈疽、瘰疬、血虚肠燥便秘的药物是","o":["甘草","当归","黄芪","何首乌","肉苁蓉"],"a":3,"e":"何首乌苦甘涩微温，制用补益精血、固肾乌须，生用解毒截疟、润肠通便，故痈疽瘰疬与血虚肠燥便秘皆宜。"},{"q":"血竭可用于治疗","o":["皮肤湿疮","肾虚腰痛","肺热咳嗽","食积不化","外伤出血"],"a":4,"e":"血竭甘咸平，活血定痛、化瘀止血、生肌敛疮，为外伤出血、跌打损伤及疮疡不敛之要药。"},{"q":"具有小毒的药物是","o":["桑白皮","葶苈子","款冬花","马兜铃","苦杏仁"],"a":4,"e":"苦杏仁苦微温，有小毒，降气止咳平喘、润肠通便，生品入煎剂宜后下，用量不宜过大，婴儿慎用。"},{"q":"七情配伍中，具有协同作用能提高药效的配伍方法是","o":["相须、相使","相须、相畏","相须、相杀","相使、相畏","相使、相杀"],"a":0,"e":"相须指性能功效相类似药物配伍以增强原有疗效，相使指性能功效有某种共性者主辅配合以提高主药疗效，二者均属协同增效。"},{"q":"临床上见恶寒发热，咳嗽咽痛等证，一般应选用","o":["归心经的药物","归肺经的药物","归肝经的药物","归肾经的药物","归脾经的药物"],"a":1,"e":"恶寒发热、咳嗽咽痛为外邪犯肺之表证，病位在肺，故选用归肺经的解表药物以发散外邪。"},{"q":"肺热咳喘兼胃热呕吐者，宜选用","o":["生姜","竹茹","砂仁","藿香","枇杷叶"],"a":4,"e":"恶寒发热、咳嗽咽痛为外邪犯肺之表证，病位在肺，故选用归肺经的解表药物以发散外邪，如麻黄、荆芥、桔梗。"},{"q":"薄菏的性味是","o":["苦寒","苦温","辛凉","甘寒","甘凉"],"a":2,"e":"枇杷叶苦微寒，清肺止咳、降逆止呕，既清肺热治咳喘，又降胃气治胃热呕吐；叶背有绒毛，入煎剂宜包煎。"},{"q":"有退黄之功，可治疗湿热黄疸的药组是","o":["茵陈、胡黄连","地骨皮、栀子","白薇、大黄","银柴胡、白鲜皮","青蒿、茵陈"],"a":4,"e":"青蒿清透虚热、凉血退黄，茵陈苦泄下降、善利胆退黄，二者均可治湿热黄疸，如茵陈蒿汤之用。"},{"q":"我国第一部药典性著作是","o":["《神农本草经》","《本草经集注》","《新修本草》","《证类本草》","《本草纲目》"],"a":2,"e":"《新修本草》由苏敬等编撰，是我国第一部由国家颁布的药典性本草，早于《本草纲目》八百余年。"},{"q":"以治疗肝阳上亢之头晕目眩为主的中药属于","o":["重镇安神药","平抑肝阳药","豁痰开窍药","息风止痉药","滋阴潜阳药"],"a":1,"e":"凡以平抑肝阳、主治肝阳上亢所致头晕目眩、头痛为主要功效的药物，均归入平抑肝阳药，如石决明、珍珠母。"},{"q":"大黄治头痛，目赤，易怒，便秘者，主要作用部位是","o":["脾经","胃经","大肠经","肝经","心包经"],"a":3,"e":"大黄苦寒沉降，善泻肝火、导热下行，故肝火上炎之头痛目赤、易怒便秘用之，其作用部位在肝经。"},{"q":"味苦性凉，为清热解毒之良药，内服外用均宜的药是","o":["甘草","牛黄","冰片","羚羊角","珍珠母"],"a":1,"e":"大黄苦寒沉降，善泻肝火、导热下行，故肝火上炎之头痛目赤、易怒便秘用之，其作用部位在肝经，非在大肠。"},{"q":"治疗邪热壅肺之喘咳，宜选用的药对是","o":["白芥子、莱菔子","石膏、麻黄","半夏、天南星","陈皮、半夏","苦杏仁、白果"],"a":1,"e":"石膏清泻肺热，麻黄宣肺平喘，二者相伍辛凉宣泄、清肺平喘，即麻杏石甘汤之意，用治邪热壅肺之喘咳。"},{"q":"属于“十九畏”的配伍药对是","o":["川乌与草乌","桃仁与红花","官桂与赤石脂","乌头与贝母","甘草与甘遂"],"a":2,"e":"十九畏载官桂畏石脂，二者同用可减弱温阳之力，属配伍禁忌；乌头与贝母则属十八反，非十九畏。"},{"q":"石膏与寒水石入汤剂宜","o":["先煎","后下","包煎","另煎","烊化"],"a":0,"e":"石膏、寒水石均为矿物类药，质地坚硬，有效成分不易煎出，入汤剂宜打碎先煎二十分钟。"},{"q":"可广泛用于多种饮食积滞证，尤善消化谷麦酒食积滞的药物是","o":["山楂","神曲","麦芽","葛根","陈皮"],"a":1,"e":"石膏、寒水石均为矿物类药，质地坚硬，有效成分不易煎出，入汤剂宜打碎先煎二十分钟，以利溶出。"},{"q":"能补益肺肾，止咳平喘，可用治肺虚咳喘的药物是","o":["灵芝","远志","首乌藤","酸枣仁","合欢皮"],"a":0,"e":"灵芝甘平，补气安神、止咳平喘，入肺肾二经，能补益肺肾之气，用治肺虚咳喘、虚劳短气。"},{"q":"钩藤入汤剂宜","o":["包煎","先煎","后下","另煎","烊化"],"a":2,"e":"钩藤有效成分钩藤碱久煎易被破坏，故入汤剂宜后下，煎煮不宜超过二十分钟，以免降压之力减弱。"},{"q":"下列不属于道地药材的是","o":["四川的附子","浙江的白芍","陕西的当归","河南的地黄","山东的阿胶"],"a":2,"e":"当归道地产区为甘肃岷县，陕西非其道地；附子产四川、白芍产浙江、地黄产河南、阿胶产山东。"},{"q":"可用于治疗瘀血证的消食药是","o":["青皮","桃仁","红花","山楂","神曲"],"a":3,"e":"山楂酸甘微温，消食化积、行气散瘀，善消肉食油腻之积，兼入血分治瘀血经闭、产后瘀阻。"},{"q":"下列不属于蟾酥适用范围的是","o":["牙痛","咽喉肿痛","痈疽疔疮","痧胀腹痛","风湿痹痛"],"a":4,"e":"蟾酥辛温有毒，解毒消肿、止痛、开窍醒神，主治痈疽疔疮、咽喉肿痛、牙痛及痧胀腹痛；风湿痹痛非其所主。"},{"q":"牛蒡子的归经是","o":["脾、胃、肺经","肺、肝经","肝、胆、肺经","膀胱、肝、胃经","肺、胃经"],"a":4,"e":"蟾酥辛温有毒，解毒消肿、止痛、开窍醒神，主治痈疽疔疮、咽喉肿痛、牙痛及痧胀腹痛；风湿痹痛非其所主。"},{"q":"赤药具有而牡丹皮不具有的功效是","o":["清热凉血","清退虚热","活血化瘀","清肝泻火","解毒透疹"],"a":3,"e":"赤芍苦微寒，清热凉血、散瘀止痛，又能清肝泻火治肝热目赤肿痛；牡丹皮则长于清透虚热。"},{"q":"某些对胃肠有刺激性的药物宜","o":["饭前服","多次分服","空腹时服","饭后服","腹痛时服"],"a":3,"e":"对胃肠有刺激性的药物宜饭后服用，以减少对胃黏膜的刺激；补益药、驱虫药则多空腹服。"},{"q":"治疗久泄久痢的中药大多具有","o":["酸味","苦味","甘味","辛味","咸味"],"a":0,"e":"对胃肠有刺激性的药物宜饭后服用，以减少对胃黏膜的刺激；补益药、驱虫药多空腹服，安神药宜睡前服。"},{"q":"“温热天之阳，寒凉天之阴；阳则升，阴则降”，反映了四气与下列哪项的关系","o":["四气","五味","归经","升降浮沉","毒性"],"a":3,"e":"温热属阳，其性升浮；寒凉属阴，其性沉降，此语说明四气与升降浮沉之间存在对应关系。"},{"q":"被称为“气病之总司，女科之主帅”的药物是","o":["香附","乌药","甘松","大腹皮","荔枝核"],"a":0,"e":"香附辛微苦微甘平，疏肝解郁、理气宽中、调经止痛，李时珍称其为气病之总司、女科之主帅。"},{"q":"治疗肺热咳嗽，高热烦渴，首选的药物是","o":["龙胆","黄连","黄芩","黄柏","苦参"],"a":2,"e":"香附辛微苦微甘平，疏肝解郁、理气宽中、调经止痛，李时珍称其为气病之总司、女科之主帅，为调经要药。"},{"q":"人参配莱菔子，莱菔子能削弱人参的补气作用，这种配伍关系属于","o":["相须","相使","相畏","相恶","相杀"],"a":3,"e":"黄芩苦寒，善清肺火及上焦实热，又能清热安胎、凉血止血，为肺热咳嗽、高热烦渴之首选。"},{"q":"下列病症中，哪种不宜用赭石治疗","o":["热证抽搐","烦躁不寐","血热吐血、崩漏","气逆之嗳气、呕吐","肝阳上亢之头痛、眩晕"],"a":0,"e":"赭石质重沉降，平肝潜阳、降逆止血，无息风止痉之功，故热证抽搐非其所宜；抽搐当用羚羊角、钩藤。"},{"q":"下列不属于土荆皮临床应用范围的是","o":["体癣","湿疹","疮痈","头癣","手足癣"],"a":2,"e":"土荆皮辛温有毒，只作外用，杀虫止痒，主治体癣、头癣、手足癣及湿疹；疮痈非其适用范围。"},{"q":"水蛭、虻虫的相同功效是","o":["活血疗伤接骨","破血逐瘀消癥","散结消肿止痛","破血行气消积","活血消肿排脓"],"a":1,"e":"土荆皮辛温有毒，只作外用，杀虫止痒，主治体癣、头癣、手足癣及湿疹；疮痈非其适用范围，亦不入煎剂。"},{"q":"不宜与砒石同用的药物是","o":["硼砂","雄黄","水银","轻粉","朴硝"],"a":2,"e":"水蛭、虻虫均入肝经血分，破血逐瘀、消癥散结，为瘀血癥瘕、经闭之峻药，孕妇禁用，体虚者慎用。"},{"q":"患者，男。胃溃疡病史，近日发现大便隐血，伴胃脘冷痛，泛酸，四肢不温。医方中用到白及，同方中不应该同时出现的药物是","o":["半夏","瓜蒌","附子","贝母","五灵脂"],"a":2,"e":"十八反载半蒌贝蔹及攻乌，白及反乌头，附子为乌头子根，同属禁忌，故方中不宜与白及同用。"},{"q":"能治疗肝郁气滞，胸胁胀痛，月经不调的药物是","o":["菊花","升麻","牛蒡子","蝉蜕","柴胡"],"a":4,"e":"柴胡辛苦微寒，归肝胆经，疏肝解郁、升举阳气，为肝郁气滞、胸胁胀痛、月经不调之要药。"},{"q":"茵陈的性味归经是","o":["辛、苦，寒。归肾、膀胱经","苦、辛，微寒。归脾、胃、肝、胆经","微苦，微寒。归肝、胆、肺经","苦，平。归肝、胆经","甘、淡，凉。归肝、胆、小肠经"],"a":1,"e":"柴胡辛苦微寒，归肝胆经，疏肝解郁、升举阳气，为肝郁气滞、胸胁胀痛、月经不调之要药，常与白芍配伍。"},{"q":"不属于寒凉药所示的功效是","o":["清热利尿","凉血止血","凉肝息风","补肾助阳","泻火解毒"],"a":3,"e":"茵陈苦、辛，微寒，归脾、胃、肝、胆经，善清利湿热、利胆退黄，为治黄疸之要药，阳黄阴黄皆可配伍应用。"},{"q":"来源于相同植物的药是","o":["猪苓、茯苓","羌活、独活","桑寄生、桑椹","干姜、高良姜","枸杞子、地骨皮"],"a":4,"e":"枸杞子与地骨皮同出于茄科植物宁夏枸杞，前者药用果实，后者药用根皮，故来源于同一植物。"},{"q":"玄参具有而生地黄不具有的功效是","o":["养阴生津","清热凉血","透疹消斑","解毒散结","活血化瘀"],"a":3,"e":"玄参苦甘咸微寒，清热凉血、滋阴降火、解毒散结；生地黄偏于清热凉血、养阴生津，无解毒散结之力。"},{"q":"大黄与芒硝配伍，当属七情配伍中的","o":["相须","相使","相恶","相反","相杀"],"a":0,"e":"大黄苦寒泻下攻积，芒硝咸寒软坚润燥，配伍后泻下热结之力大增，属七情中的相须，即大承气汤之意。"},{"q":"石决明的药用部位是","o":["化石","贝壳","果实","树脂","种子"],"a":1,"e":"石决明为鲍科动物杂色鲍或皱纹盘鲍的干燥贝壳，生用平肝潜阳、清肝明目，煅用收敛制酸。"},{"q":"可虚实两清，既能治疗阴虚发热，又能治疗血热咯血衄血的药物是","o":["黄柏","地骨皮","白薇","白茅根","秦艽"],"a":1,"e":"石决明为鲍科动物杂色鲍或皱纹盘鲍的干燥贝壳，生用平肝潜阳、清肝明目，煅用收敛制酸，为眼科要药。"},{"q":"陈皮的功效是","o":["理气健脾，燥湿化痰","理气和中，化痰除痞","行气调中，杀虫疗癣","理气止痛，祛寒散滞","理气和中，疏肝化痰"],"a":0,"e":"陈皮辛、苦，温，归脾、肺经，理气健脾、燥湿化痰，为治脾胃气滞及湿痰咳嗽之常用药。"},{"q":"下焦血热所致的便血、崩漏，宜首选的药物是","o":["大蓟","小蓟","地榆","白茅根","侧柏叶"],"a":2,"e":"地榆苦酸微寒，凉血止血、解毒敛疮，善走下焦，为便血、崩漏、痔血等下焦血热出血之首选。"},{"q":"薤白的功效为行气导滞","o":["通阳散结","疏肝解郁","行气宽中","降逆止呃","温肾助阳"],"a":0,"e":"地榆苦酸微寒，凉血止血、解毒敛疮，善走下焦，为便血、崩漏、痔血等下焦血热出血之首选，兼可敛疮。"},{"q":"善滋养胃阴，兼清胃热，治胃阴虚有热之口渴多饮、饥不欲食的药是","o":["桑椹","天冬","楮实子","黑芝麻","北沙参"],"a":4,"e":"北沙参甘微苦微寒，养阴清肺、益胃生津，善滋养胃阴兼清胃热，治胃阴虚有热之口渴多饮、饥不欲食。"},{"q":"不宜与甘草同用的药物是","o":["海藻","昆布","海蛤壳","海浮石","瓦楞子"],"a":0,"e":"十八反载海藻反甘草，二者同用易使毒性增强或产生不良反应，故属配伍禁忌，处方中不宜并列。"},{"q":"下列那项不是雄黄的功效","o":["解毒","杀虫","通便","截疟","燥湿祛痰"],"a":2,"e":"十八反载海藻反甘草，二者同用易使毒性增强或产生不良反应，故属配伍禁忌；甘遂、大戟、芫花亦反甘草。"},{"q":"清虚热药可用于","o":["温病初起","热病高热烦渴","温毒斑疹","温病后期夜热早凉","热入营分"],"a":3,"e":"雄黄辛苦温有毒，解毒杀虫、燥湿祛痰、截疟，外用治疥癣、蛇虫咬伤；通便非其功效，内服不宜久用。"},{"q":"湿阻、食积、气滞中满者宜慎用的药味是","o":["辛味","淡味","苦味","咸味","甘味"],"a":4,"e":"清虚热药主入阴分，退虚热、除骨蒸，适用于温病后期邪伏阴分之夜热早凉、热退无汗及阴虚骨蒸潮热。"},{"q":"生用行气，煨用止泻的药物是","o":["香附","青皮","木香","沉香","土木香"],"a":2,"e":"木香辛苦温，生用行气止痛力强，煨用则减其辛散之性而长于实肠止泻，为行气止痛要药。"},{"q":"吴茱萸煎服时用量为","o":["1～3g","1～5g","2～5g","3～6g","3～10g"],"a":2,"e":"吴茱萸辛热有小毒，内服煎汤用量2～5g，外用适量研末调敷，本品辛热燥烈，不宜多用久服。"},{"q":"既能涩肠止泻，又能收敛止血的药物是","o":["白及","紫珠","肉豆蔻","罂粟壳","禹余粮"],"a":4,"e":"禹余粮甘、涩，微寒，归胃、大肠经，涩肠止泻、收敛止血，主治久泻久痢及崩漏、便血。"},{"q":"能养阴生津，润肺清心的药物是","o":["石斛","天冬","麦冬","南沙参","北沙参"],"a":2,"e":"禹余粮甘、涩，微寒，归胃、大肠经，涩肠止泻、收敛止血，主治久泻久痢及崩漏、便血，为涩肠固脱之品。"},{"q":"不宜与南沙参、北沙参同用的药物是","o":["甘草","附子","藜芦","川乌","草乌"],"a":2,"e":"十八反谓诸参辛芍叛藜芦，南沙参、北沙参均在诸参之列，与藜芦同用易增毒副反应，属配伍禁忌。"},{"q":"能固精止遗的药物是","o":["山楂","神曲","麦芽","莱菔子","鸡内金"],"a":4,"e":"鸡内金甘平，消食健胃、涩精止遗、通淋化石，既为消食良药，又能固精止遗治遗精、遗尿。"},{"q":"具有补肝肾、续折伤、止崩漏功效的药物是","o":["杜仲","续断","仙茅","锁阳","蛤蚧"],"a":1,"e":"续断苦辛微温，补肝肾、强筋骨、续折伤、止崩漏，为伤科筋骨损伤及胎漏下血常用之品。"},{"q":"芡实与白果的共同功效是","o":["止汗","止泻","止带","止痛","止咳"],"a":2,"e":"续断苦辛微温，补肝肾、强筋骨、续折伤、止崩漏，为伤科筋骨损伤及胎漏下血常用之品，兼能安胎。"},{"q":"可治外感内伤、寒热虚实之咳嗽，为治肺痨咳嗽、久咳虚嗽之要药的是","o":["百部","枇杷叶","桑白皮","紫苏子","苦杏仁"],"a":0,"e":"百部甘苦微温，润肺下气止咳、杀虫灭虱，寒热虚实之咳嗽皆可配用，尤宜肺痨咳嗽、久咳虚嗽。"},{"q":"治厥阴头痛，宜选","o":["花椒","白芷","羌活","干姜","吴茱萸"],"a":4,"e":"百部甘苦微温，润肺下气止咳、杀虫灭虱，寒热虚实之咳嗽皆可配用，尤宜肺痨咳嗽、久咳虚嗽及头虱体虱。"},{"q":"治脾虚胎动不安，最宜选用","o":["砂仁","杜仲","白术","紫苏梗","桑寄生"],"a":2,"e":"吴茱萸辛热，入肝经，善散厥阴肝经寒邪，为治巅顶头痛、干呕吐涎沫之要药，即厥阴头痛之首选。"},{"q":"知母治阴虚消渴，主要是因其能","o":["利尿通淋","除烦止渴","润燥通便","滋阴润燥","清热泻火"],"a":3,"e":"白术甘苦温，补气健脾、燥湿利水、止汗安胎，脾虚气弱而胎动不安者最宜，兼能利水消肿、固表止汗。"},{"q":"主归胃、肾经，既能益胃生津，又能滋阴清热的药物是","o":["黄精","玉竹","石斛","麦冬","百合"],"a":2,"e":"知母苦甘寒，清热泻火、滋阴润燥，既清胃热又滋胃阴，故治阴虚内热之消渴，常与天花粉、山药配伍。"},{"q":"旋覆花不具有的功效是","o":["止血","行水","降气","止呕","消痰"],"a":0,"e":"旋覆花苦、辛、咸，微温，降气化痰、降逆止呕、行水，入煎剂须包煎，诸功效中并无止血。"},{"q":"既能化痰散结，又能清热解毒的药物是","o":["僵蚕","地龙","黄药子","天竺黄","天南星"],"a":2,"e":"旋覆花苦、辛、咸，微温，降气化痰、降逆止呕、行水，入煎剂须包煎，诸功效中并无止血。"},{"q":"大黄长期服用致继发性便秘，是因其含有","o":["蒽醌类成分","生物碱","挥发油","鞣质","双蒽酮苷类成分"],"a":3,"e":"大黄含大量鞣质，具收敛止泻作用，久服后鞣质蓄积，停药后肠蠕动减弱而出现继发性便秘。"},{"q":"孕妇忌服的药物是","o":["千年健","雪莲花","狗脊","桑寄生","五加皮"],"a":1,"e":"大黄含大量鞣质，具收敛止泻作用，久服后鞣质蓄积，停药后肠蠕动减弱而出现继发性便秘，即泻剂依赖。"},{"q":"与菊花相比，野菊花长于","o":["清热解毒","清泻肝火","平抑肝阳","疏散风热","清肺润燥"],"a":0,"e":"野菊花苦辛微寒，清热解毒之力强于菊花，善治痈肿疔疮、咽喉肿痛；菊花偏疏散风热、平肝明目。"},{"q":"治疗心气不足的心悸、脉结代，最宜选用的药是","o":["黄芪","白术","丹参","山药","炙甘草"],"a":4,"e":"野菊花苦辛微寒，清热解毒之力强于菊花，善治痈肿疔疮、咽喉肿痛；菊花则偏疏散风热、平肝明目。"},{"q":"不属于何首乌功效的是","o":["固肾乌须","补益精血","止咳平喘","润肠通便","截疟解毒"],"a":2,"e":"炙甘草甘温，益气复脉、补脾和胃，为治心气不足之心悸、脉结代之要药，如炙甘草汤，亦能缓急止痛。"},{"q":"古人认为可“劫肝阴”，阴虚阳亢，肝风内动，阴虚火旺者忌用或慎用的药物是","o":["桑叶","升麻","牛蒡子","蝉蜕","柴胡"],"a":4,"e":"柴胡辛散升发，久用或过量易耗气伤阴而劫肝阴，故阴虚阳亢、肝风内动及阴虚火旺者忌用或慎用。"},{"q":"具有清热解毒，化痰散结之功，近年来广泛应用于癥瘕痞块和多种肿瘤的药物是","o":["金银花","败酱草","山慈菇","熊胆粉","白花蛇舌草"],"a":2,"e":"山慈菇甘微辛凉，清热解毒、化痰散结，善治痈疽疔毒、瘰疬痰核，近年常用于癥瘕痞块及多种肿瘤。"},{"q":"治风寒表实证兼喘咳，宜首选的药物是","o":["羌活","紫苏叶","麻黄","桂枝","防风"],"a":2,"e":"麻黄辛温，发汗解表、宣肺平喘，风寒表实无汗而兼喘咳者最为适宜，为解表宣肺之要药。"},{"q":"水蛭研末内服的用量是","o":["0、01～0、03g","0、04～0、06g","0、1～0、15g","0、3～0、5g","0、6～1g"],"a":3,"e":"水蛭咸苦平有小毒，破血逐瘀消癥，研末内服每次0.3～0.5g，煎汤服1～3g，孕妇禁用。"},{"q":"理气药中，擅于行气调中止痛的药物是","o":["木香","香附","沉香","土木香","九香虫"],"a":0,"e":"水蛭咸苦平有小毒，破血逐瘀消癥，研末内服每次0.3～0.5g，煎汤服1～3g，孕妇禁用，出血倾向者慎用。"},{"q":"浮小麦可用治","o":["脏躁证","久咳虚喘","骨蒸劳热","饮食积滞","失眠多梦"],"a":2,"e":"木香辛苦温，行气止痛、健脾消食，善行脾胃及大肠气滞，为治脘腹胀痛、泻痢后重之要药。"},{"q":"味甘性平，寒热虚实出血病证均宜选用的药物是","o":["大蓟","茜草","蒲黄","三七","槐花"],"a":2,"e":"蒲黄甘平，止血化瘀、利尿通淋，生用活血、炒用止血，性平不偏，故寒热虚实之出血证均可配伍应用。"},{"q":"功能活血通经，凉血祛风的药是","o":["丹参","红花","川芎","延胡索","凌霄花"],"a":4,"e":"凌霄花甘、酸，寒，归肝、心包经，活血通经、凉血祛风，治血瘀经闭、癥瘕及风疹瘙痒。"},{"q":"用治风湿痹证兼夜盲者宜选用","o":["苍术","砂仁","木瓜","豆蔻","厚朴"],"a":0,"e":"凌霄花甘、酸，寒，归肝、心包经，活血通经、凉血祛风，治血瘀经闭、癥瘕及风疹瘙痒，孕妇忌用。"},{"q":"天南星的功效是","o":["燥湿化痰，降逆止呕","燥湿化痰，利气散结","燥湿化痰，宽胸散结","燥湿化痰，祛风止痉","燥湿化痰，疏散风热"],"a":3,"e":"苍术辛苦温，燥湿健脾、祛风散寒、明目，风湿痹证兼夜盲、眼目昏涩者最宜，兼能发汗解表。"},{"q":"药物“七情”的含义是","o":["喜、怒、忧、思、悲、恐、惊","辛、甘、酸、苦、咸、淡、涩","相须、相使、相畏、相杀、相恶、相反、单行","寒、热、温、凉、平、无毒、有毒","肝、心、脾、肺、肾、大肠、小肠"],"a":2,"e":"七情指单行及相须、相使、相畏、相杀、相恶、相反六种配伍关系，是药物配伍应用的基本规律。"},{"q":"不属秦皮功效的是","o":["燥湿","止痢","止带","明目","解毒"],"a":4,"e":"秦皮苦、涩，寒，归肝、胆、大肠经，清热燥湿、收涩止痢、止带、明目，并无解毒之功。"},{"q":"白芍与当归的共同适应证为","o":["月经不调","肝阳眩晕","跌打损伤","痈疽疮疡","泻痢腹痛"],"a":0,"e":"白芍养血调经、柔肝止痛，当归补血活血、调经止痛，二者同用善治血虚之月经不调、痛经。"},{"q":"既能清肺化痰，又能宽胸散结的药物是","o":["知母","白前","瓜蒌","桔梗","百部"],"a":2,"e":"白芍养血调经、柔肝止痛，当归补血活血、调经止痛，二者同用善治血虚之月经不调、痛经，为妇科常用配伍。"},{"q":"既能解表散寒，又能宣通鼻窍、温肺化饮的药物是","o":["防风","桂枝","荆芥","生姜","细辛"],"a":4,"e":"细辛辛温，解表散寒、祛风止痛、通窍、温肺化饮，为风寒感冒兼鼻塞头痛、寒饮咳喘常用之品。"},{"q":"肺胃热盛之出血，宜选用的药物是","o":["芦根","大蓟","小蓟","石膏","白茅根"],"a":4,"e":"白茅根甘寒，凉血止血、清热生津、利尿通淋，善清肺胃之热，故肺胃热盛之吐血、衄血宜之。"},{"q":"金银花除能清热解毒，疏散风热外，还具有的功效是","o":["助阳止泻","健脾止泻","涩肠止泻","凉血止痢","渗湿止泻"],"a":3,"e":"金银花甘寒，归肺、心、胃经，清热解毒、疏散风热，兼能凉血止痢，治热毒血痢、便下脓血。"},{"q":"蕲蛇的功效是","o":["祛风湿、止痛、补肝肾","祛风、通络、止痉","祛风湿、补肝肾、强筋骨","祛风活络、凉血定惊","祛风除湿、散寒止痛"],"a":1,"e":"金银花甘寒，归肺、心、胃经，清热解毒、疏散风热，兼能凉血止痢，治热毒血痢、便下脓血，炒炭后止血力更著。"},{"q":"柴胡与升麻均具有的功效是","o":["生津","透疹","升阳","解毒","收敛"],"a":2,"e":"柴胡升举阳气，升麻升阳举陷，二者均能升阳，常相须用于中气下陷之脏器脱垂，如补中益气汤。"},{"q":"萹蓄除能利尿通淋外，还能","o":["杀虫止痒","祛风止痒","通淋止痛","活血通经","润肠通便"],"a":0,"e":"萹蓄苦、微寒，归膀胱经，利尿通淋、杀虫止痒，善治湿热淋证、小便短赤及湿疹阴痒、蛔虫腹痛。"},{"q":"能益气托疮生肌，被称为“疮痈圣药”的是","o":["连翘","黄芪","白芷","蒲公英","紫花地丁"],"a":1,"e":"黄芪甘温，补气升阳、益卫固表、托毒生肌、利水消肿，善治疮疡久不敛口，故有益气托疮生肌之效。"},{"q":"能补火助阳，益阳消阴，引火归元，为治命门火衰之要药的是","o":["干姜","桂枝","丁香","肉桂","吴茱萸"],"a":3,"e":"黄芪甘温，补气升阳、益卫固表、托毒生肌、利水消肿，善治疮疡久不敛口，故为益气托疮生肌之要药。"},{"q":"理气药中，用于治疗胃肠积滞、脘腹痞满，为破气除痞之要药的是","o":["青皮","甘松","枳实","佛手","荔枝核"],"a":2,"e":"枳实苦辛酸微寒，破气消积、化痰除痞，善治胃肠积滞、脘腹痞满胀痛，为破气除痞之要药。"},{"q":"下列药物用法哪项是错误的","o":["旋覆花布包入汤剂","琥珀入汤剂","钩藤入汤剂后下","雷丸研末冷开水凋服","麝香入丸散服"],"a":1,"e":"琥珀为树脂化石，难溶于水，只宜研末冲服或入丸散，入汤剂则药力难以煎出；雷丸亦须研末调服。"},{"q":"青蒿治疟疾寒热往来，最佳用法是","o":["鲜用，绞汁服","阴干，久煎","鲜用，久煎","阴干，包煎","炒用，煎服"],"a":0,"e":"青蒿治疟疾寒热往来宜鲜用绞汁服。其抗疟有效成分不耐久煎，鲜品绞汁或入煎后下可保全药效，故不宜阴干久煎。"},{"q":"患者，男，55岁。近2周常有下肢挛急作痛，最宜选用的药组是","o":["桂枝，白芍","细辛，干姜","甘草，白芍","独活，羌活","黄芪，防风"],"a":2,"e":"甘草与白芍配伍即芍药甘草汤，酸甘化阴、缓急止痛，为治筋脉失养、下肢挛急作痛的代表配伍。"},{"q":"黄芪与茯苓配伍，茯苓能增强黄芪的补气利水作用，这种配伍关系是","o":["相须","相使","相反","相恶","相畏"],"a":1,"e":"相使指两药同用，一药为主、一药为辅，辅药能增强主药疗效。黄芪补气利水为主，茯苓淡渗利湿为辅，故属相使。"},{"q":"下列药物中，可以治疗胃下垂、子宫脱垂的药物是","o":["甘松","枳实","乌药","荔枝核","川楝子"],"a":1,"e":"枳实破气消积，且具升提之性，能使弛缓的脏腑复位，临床用于胃下垂、子宫脱垂、脱肛等中气下陷证。"},{"q":"出血过多，气随血脱时，宜急投大剂的","o":["收敛止血药","化瘀止血药","补气固脱药","温经止血药","凉血止血药"],"a":2,"e":"血脱者益气，气旺则血有所统。出血过多致气随血脱，当急投大剂补气固脱药如独参汤，以挽回散失之气。"},{"q":"具解毒散结之功，可用治赘疣，癌肿的药物是","o":["猪苓","香加皮","薏苡仁","滑石","泽泻"],"a":2,"e":"薏苡仁利水渗湿、健脾除痹、清热排脓，并能解毒散结，故可用于赘疣、癌肿等有形结块。"},{"q":"具有破血逐瘀之功，用于干血成劳，经闭腹痛的首选药是","o":["苏木","土鳖虫","马钱子","骨碎补","自然铜"],"a":1,"e":"土鳖虫咸寒，破血逐瘀、续筋接骨，善治瘀血久积之干血成劳、经闭腹痛，大黄䗪虫丸即以其为主药。"},{"q":"大量服用可引起呃逆、眩晕、呕吐、腹泻等反应的药物是","o":["榧子","雷丸","槟榔","川楝子","使君子"],"a":4,"e":"使君子大量服用可致呃逆、眩晕、呕吐、腹泻，故用量宜控制在9～12g，且忌与热茶同服。"},{"q":"药用部位是花蕾的药物是","o":["丁香","夏枯草","高良姜","天花粉","小茴香"],"a":0,"e":"丁香以花蕾入药。夏枯草用果穗，高良姜用根茎，天花粉用根，小茴香用成熟果实，均非花蕾。"},{"q":"具有纳气平喘作用的药物是","o":["香附","沉香","枳实","青皮","薤白"],"a":1,"e":"沉香芳香沉降，能行气止痛、温中止呕、纳气平喘，治下元虚冷、肾不纳气之虚喘呃逆。，为理气降逆之常用药。"},{"q":"磁石善于治疗","o":["肺气不足之虚喘","肾不纳气之虚喘","肺气壅滞之喘满","痰壅气逆之咳喘","热邪壅肺之咳喘"],"a":1,"e":"磁石质重沉降，镇惊安神、平肝潜阳、聪耳明目、纳气平喘，尤宜肾不纳气之虚喘，常与代赭石、五味子同用。"},{"q":"杨某，男，32岁。高热不退，已3日不大便，腹部胀满拒按，时有谵语，言语不清，面色红赤，脉沉实有力，宜首选","o":["生地黄","牡丹皮","大黄","巴豆霜","甘遂"],"a":2,"e":"高热、腹部胀满拒按、谵语、脉沉实，属阳明腑实、燥屎内结。大黄苦寒泻下、荡涤肠胃，攻积导滞最为合宜。"},{"q":"桑白皮最宜用于","o":["脾虚水肿见便溏","全身水肿兼喘咳","肾虚水肿下身肿著","全身水肿，面目发黄","水肿兼恶寒发热，汗出"],"a":1,"e":"桑白皮泻肺平喘、利水消肿，肺气壅实、水道不利之全身水肿兼喘咳者最宜，肺与水同病取其两功兼顾。"},{"q":"蒺藜与蝉蜕都能治疗的病症是","o":["中风面瘫","乳闭不通","风疹瘙痒","瘰疬痰核","急慢惊风"],"a":2,"e":"蒺藜平肝疏肝、祛风明目、散结祛瘀，蝉蜕疏散风热、透疹止痒，二者同治风疹瘙痒。，二药皆入肝肺经而止痒。"},{"q":"发散风寒药的药性特点是","o":["苦，寒","苦，温","辛，凉","甘，寒","辛，温"],"a":4,"e":"发散风寒药味辛能散、性温散寒，故药性特点为辛温，主治风寒表证，如麻黄、桂枝、紫苏叶。"},{"q":"均可以疏肝理气的药物有","o":["陈皮、青皮","木香、沉香","薤白、甘松","香附、佛手","枳实、刀豆"],"a":3,"e":"香附疏肝解郁、理气调中，佛手疏肝理气、和胃止痛、燥湿化痰，二者均以疏肝理气见长。"},{"q":"治疗痰壅气逆，咳喘痰多之要药是","o":["百部","款冬花","桑白皮","紫苏子","苦杏仁"],"a":3,"e":"紫苏子降气化痰、止咳平喘、润肠通便，为治痰壅气逆、咳喘痰多之要药，方如苏子降气汤。"},{"q":"治疗营血亏虚，肝肾不足之痹痛的药物是","o":["蕲蛇","威灵仙","桑枝","桑寄生","海风藤"],"a":3,"e":"桑寄生祛风湿、补肝肾、强筋骨、安胎，独活寄生汤中重用之，正治营血亏虚、肝肾不足之痹痛。"},{"q":"某医师治疗毒蛇咬伤时常用多味中药捣烂外敷，其中所含虎杖发挥的功效是","o":["清热利湿","清热解毒","敛疮生肌","消痰燥湿","散结消肿"],"a":1,"e":"虎杖苦寒，能清热解毒、利湿退黄、散瘀止痛、化痰止咳，外敷治毒蛇咬伤取其清热解毒之力。"},{"q":"某医师治疗小儿咳嗽，处方中擅于用车前子，其中车前子发挥的功效是","o":["润肺袪痰","清肺袪痰","滋阴润肺","温肺袪痰","降气祛痰"],"a":1,"e":"车前子能清热利尿通淋、渗湿止泻、明目、祛痰，其祛痰实为清肺化痰，宜于痰热咳嗽。，为利水与化痰并举之品。"},{"q":"木通除利尿通淋，清心除烦外，还能","o":["祛湿敛疮","明目，祛痰","祛风止痒","通经下乳","凉血止血"],"a":3,"e":"木通苦寒，利尿通淋、清心除烦、通经下乳，故除前二功外还能通经下乳，为治乳汁短少、经闭常用药。"},{"q":"紫苏叶的功效不包括","o":["发表散寒","理气安胎","疏肝解郁","行气宽中","解鱼蟹毒"],"a":2,"e":"紫苏叶发表散寒、行气宽中、理气安胎、解鱼蟹毒，无疏肝解郁之功，疏肝解郁系柴胡、香附所主。"},{"q":"性能功效相类似的药物配合应用，可增强原有疗效的配伍关系是","o":["相须","相使","相畏","相杀、相畏","相恶"],"a":0,"e":"相须指性能功效相类似的药物配合应用，可明显增强原有疗效，如石膏与知母、金银花与连翘同用。"},{"q":"罂粟壳的使用注意不包括","o":["不宜常服","儿童禁用","孕妇禁用","老年人禁用","运动员慎用"],"a":3,"e":"罂粟壳酸涩有毒，不宜常服，儿童及孕妇禁用，运动员慎用；老年人并非禁用对象，只是不宜久服。"},{"q":"药性偏凉的药物是","o":["人参","黄芪","党参","白术","西洋参"],"a":4,"e":"西洋参苦微甘凉，补气养阴、清热生津；人参、黄芪、党参、白术均性温，偏于温补。，惟西洋参独属凉性。"},{"q":"只入心经的重镇安神药是","o":["朱砂","磁石","琥珀","龙骨","牡蛎"],"a":0,"e":"朱砂甘微寒，专入心经，清心镇惊安神；磁石、龙骨、牡蛎兼入肝肾，琥珀入心、肝、膀胱经。"},{"q":"既能镇惊安神，又能平肝潜阳，还能收敛固涩的药是","o":["朱砂","龙骨","磁石","琥珀","龙齿"],"a":1,"e":"龙骨镇惊安神、平肝潜阳、收敛固涩三功兼备，煅用则收敛固涩之力更强，为质重沉降之安神药。"},{"q":"猪苓、茯苓的入药部位是","o":["根或根茎","菌核","根皮","花朵","花粉"],"a":1,"e":"猪苓、茯苓均为多孔菌科真菌的干燥菌核，故药用部位是菌核，而非根、根皮或花类。，与根类药材不同。"},{"q":"治疗热病伤阴，虚烦不眠，首选","o":["豆豉、栀子","青蒿、鳖甲","黄连、朱砂","人参、茯苓","黄连、阿胶"],"a":4,"e":"黄连清心泻火、阿胶滋阴养血，二者合用即黄连阿胶汤，专治热病伤阴、心肾不交之虚烦不眠。"},{"q":"佛手的功效是和中化痰，又能","o":["行气消积","疏肝理气","疏肝破气","行气散结","补肾纳气"],"a":1,"e":"佛手辛苦温，疏肝理气、和胃止痛、燥湿化痰，故除和中化痰外又能疏肝理气，为肝胃气滞常用药。"},{"q":"治温病热伤肺脏气阴所致的短气咳喘，最宜选用","o":["红参","麦冬","枇杷叶","西洋参","苦杏仁"],"a":3,"e":"西洋参补气养阴、清热生津，宜于温病热伤肺之气阴而短气咳喘者，气阴双补而不助热。，尤宜暑热耗气伤阴者。"},{"q":"不属于丹参主治病证的是","o":["痛经","心悸失眠","癥瘕积聚","湿热黄疸","疮疡痈肿"],"a":3,"e":"丹参活血祛瘀、凉血消痈、清心除烦，主治痛经、癥瘕积聚、心悸失眠、疮疡痈肿，湿热黄疸非其所治。"},{"q":"煅后水飞可点眼以治肝火目赤翳障的中药是","o":["地龙","天麻","蒺藜","赭石","石决明"],"a":4,"e":"石决明平肝潜阳、清肝明目，煅后水飞点眼可治肝火目赤、翳障，为眼科外用的传统用法。"},{"q":"有毒，孕妇及肝肾功能不全者应慎服的药物是","o":["榧子","雷丸","槟榔","苦楝皮","使君子"],"a":3,"e":"苦楝皮苦寒有毒，杀虫疗癣，孕妇及肝肾功能不全者慎服，且不可过量或久服，以免蓄积中毒。"},{"q":"蛇床子具有的药理作用是","o":["抗癌","止泻","止血","降血糖","抗细菌、真菌"],"a":4,"e":"蛇床子燥湿杀虫、温肾壮阳，其煎剂及提取物对多种细菌、真菌均有抑制作用，故外用治阴痒湿疮有效。"},{"q":"性大寒，专泻肺中水饮及痰火而平喘咳的药物为","o":["竹沥","前胡","贝母","桑白皮","葶苈子"],"a":4,"e":"葶苈子辛苦大寒，专泻肺中水饮及痰火而平喘咳，力峻效捷，方如葶苈大枣泻肺汤。，配大枣则泻肺而不伤正。"},{"q":"具有清热泻火，解毒，利水消肿功效的药物是","o":["夏枯草","密蒙花","青葙子","决明子","鸭跖草"],"a":4,"e":"鸭跖草甘淡寒，清热泻火、解毒、利水消肿，三功兼备，为治热病烦渴、咽喉肿痛兼水肿之品。"},{"q":"敛肺定喘，治哮喘咳嗽，宜选用","o":["桔梗","百部","白果","白前","半夏"],"a":2,"e":"白果甘苦涩平，敛肺定喘、止带缩尿，善治哮喘痰嗽，然有毒，不宜过量服用。，小儿尤当控制剂量。"},{"q":"辛夷的主治证是","o":["风寒头痛，鼻渊","目赤肿痛","巅顶痛","牙痛","咽喉肿痛"],"a":0,"e":"辛夷辛温，散风寒、通鼻窍，为治鼻渊鼻塞、流涕腥臭及风寒头痛之要药。，内服须纱布包煎。"},{"q":"金银花与连翘配伍使用，属于哪种配伍关系","o":["相杀","相畏","相反","相须","相使"],"a":3,"e":"金银花与连翘同属清热解毒药，性能功效相似，配伍后清热解毒、疏散风热之力大增，属相须为用。"},{"q":"临床外用可以治疗白癜风的药物有","o":["淫羊藿、肉苁蓉","补骨脂、益智仁","吴茱萸、肉苁蓉","补骨脂、菟丝子","益智仁、菟丝子"],"a":3,"e":"补骨脂、菟丝子外用能增色消斑，其酒精浸出液外搽患处可治白癜风，为温肾助阳药的外治应用。"},{"q":"因心阳不振而致心悸、脉结代，宜用","o":["桂枝配白芍","桂枝配白术","桂枝配茯苓","桂枝配生姜","桂枝配甘草"],"a":4,"e":"桂枝配甘草辛甘化阳、温通心阳，即桂枝甘草汤，专治心阳不振之心悸、脉结代。，为温通心阳之基础方。"},{"q":"治疗湿热脚气，痿证，苍术常配伍的药是","o":["黄柏","黄芩","黄连","知母","石膏"],"a":0,"e":"苍术配黄柏即二妙散，苍术燥湿健脾、黄柏清热燥湿，共治湿热下注之脚气、痿证、带下。"},{"q":"酒炒可使药性转化为","o":["藏","沉","降","收","升"],"a":4,"e":"酒制上行，酒炒能使药性由沉降转为升浮，多用于引药上达头面，故酒炒可使药性转化为升。"},{"q":"无疏肝理气、和胃止痛作用的药物是","o":["香橼","梅花","娑罗子","九香虫","玫瑰花"],"a":3,"e":"九香虫理气止痛、温中助阳，善治胃寒胀痛、肾虚阳痿，无疏肝理气、和胃止痛之功。，与疏肝理气药功用有别。"},{"q":"虎杖除治疗湿热黄疸，淋浊，带下外，还可以治疗","o":["乳汁不下","疮痈肿毒","脾虚泄泻","目暗昏花","遗精滑泄"],"a":1,"e":"虎杖利湿退黄、清热解毒、散瘀止痛、化痰止咳，故除湿热黄疸、淋浊、带下外，还治疮痈肿毒、水火烫伤。"},{"q":"具有清热燥湿作用的药物应具有何种药味","o":["酸","苦","甘","辛","咸"],"a":1,"e":"苦能泄、能燥、能坚，清热燥湿药多味苦性寒，如黄连、黄芩、黄柏，故其药味应为苦。，故湿热诸证多用之。"},{"q":"蜈蚣入汤剂的常规用量是","o":["0、5～1g","1～3g","3～5g","3～10g","9～15g"],"a":1,"e":"蜈蚣辛温有毒，入汤剂常用1～3g；研末冲服每次0.6～1g，外用适量，孕妇禁用。"},{"q":"咸味药的功效包括","o":["活血破瘀","利水通淋","泻下通肠","养阴润燥","理气散结"],"a":2,"e":"咸能软坚散结、泻下通肠，故咸味药可用于癥瘕痰核及肠燥便秘，如芒硝咸寒泻下通便。，此为咸味药的作用特点。"},{"q":"三棱、莪术除破血行气外，又能","o":["通经止痛","消积止痛","消肿生肌","散积消癥","散结消肿"],"a":1,"e":"三棱、莪术均能破血行气、消积止痛，为治气滞血瘀之癥瘕积聚、心腹瘀痛的要药。，二者常相须为用。"},{"q":"治疗鼻渊，流涕 ，头痛，宜首选的药物是","o":["桂枝","紫苏叶","葛根","藁本","苍耳子"],"a":4,"e":"苍耳子辛温，散风寒、通鼻窍、祛风湿，为治鼻渊流浊涕、前额头痛之要药。，用时宜炒去刺。"},{"q":"功效与龙骨相似，又长于软坚散结的药物是","o":["牡蛎","磁石","赭石","龙齿","珍珠母"],"a":0,"e":"牡蛎与龙骨功效相似，均能重镇安神、平肝潜阳、收敛固涩，而牡蛎兼能软坚散结，治痰核瘰疬。"},{"q":"用于凉血止血，宜选择","o":["熟大黄","生大黄","酒炒大黄","醋炒大黄","大黄炭"],"a":4,"e":"大黄炭泻下之力大减而止血之力增强，故凉血止血宜选大黄炭，用于血热妄行之吐血、衄血。"},{"q":"十九畏中的意义相当于七情中的","o":["相畏","相须或相使","相畏或相杀","相恶或相反","相使"],"a":3,"e":"十九畏所载多为两药同用后产生毒性或降低疗效，其意义相当于七情中的相恶或相反，与相畏含义不同。"},{"q":"大蓟、小蓟皆可用于治疗","o":["肝火目赤","肺热咳嗽","胃火牙痛","热淋涩痛","热毒疮疡"],"a":4,"e":"大蓟、小蓟均能凉血止血、散瘀解毒消痈，故血热出血与热毒疮疡皆可应用。，鲜品捣烂外敷尤宜。"},{"q":"疏散退热宜生用，疏肝解郁宜醋炙，升举阳气可生用或酒炙的药物是","o":["菊花","柴胡","蝉蜕","淡豆豉","牛蒡子"],"a":1,"e":"柴胡生用长于疏散退热，醋炙则疏肝解郁，酒炙能升举阳气，与题干所述炮制用途完全吻合。"},{"q":"既能用于风湿痹证，腰膝酸软，下肢无力。又可用于遗尿，白带过多的药物是","o":["千年健","五加皮","桑寄生","狗脊","雪莲花"],"a":3,"e":"狗脊祛风湿、补肝肾、强腰膝，并能温补固摄，故既治腰膝酸软、下肢无力，又治遗尿、白带过多。"},{"q":"下列哪味药物麸炒后可降低其燥烈之性","o":["厚朴","佩兰","广藿香","苍术","肉豆蔻"],"a":3,"e":"苍术辛香燥烈，麸炒后燥性减弱而长于健脾和胃，故麸炒可降低其燥烈之性。，多用于脾虚湿困之证。"},{"q":"功能疏散风热，清利头目，可用治风热上攻，目赤肿痛，目昏多泪，牙龈肿痛的药物是","o":["菊花","牛蒡子","蔓荆子","香薷","柴胡"],"a":2,"e":"蔓荆子疏散风热、清利头目，善治风热上攻之目赤肿痛、目昏多泪，亦治牙龈肿痛、头面诸痛。"},{"q":"患者风湿痹痛，尤以肩臂疼痛为甚，最宜选用的药是","o":["川芎","独活","乳香","姜黄","威灵仙"],"a":3,"e":"姜黄辛苦温，破血行气、通经止痛，其药力善行肩臂，故痹痛以肩臂为甚者最为适宜。，为治肩臂疼痛之引经药。"},{"q":"治疗悬饮咳喘，胸胁胀痛，常用芥子，因其能","o":["燥湿化痰，祛风止痉","消痰散结，降逆止呕","温肺豁痰，利气宽胸","清热化痰，润肺止咳","温肺化饮，消痰软坚"],"a":2,"e":"芥子辛温，温肺豁痰、利气宽胸、散结通络，故治悬饮咳喘、胸胁胀痛，方如控涎丹。，寒痰壅肺者亦用之。"},{"q":"苦寒泻下，荡涤肠胃，走而不守，有“将军”之称，为治热结便秘要药的是","o":["大黄","芒硝","番泻叶","牵牛子","巴豆"],"a":0,"e":"大黄苦寒泻下、荡涤肠胃，走而不守，素有“将军”之称，为治热结便秘、阳明腑实之要药。"},{"q":"善治情志忧郁，失眠，心神不安的药物是","o":["山药","灵芝","酸枣仁","合欢皮","珍珠母"],"a":3,"e":"合欢皮甘平，解郁安神、活血消肿，善治情志忧郁、忿怒烦躁所致之失眠、心神不安。，合欢花功用与之相近。"},{"q":"朱砂内服，正确的方法是","o":["先煎","后下","冲服","包煎","泡酒服"],"a":2,"e":"朱砂主含硫化汞，不入煎剂，宜研末冲服或入丸散，每次0.1～0.5g，且不可过量久服。"},{"q":"风寒感冒，肩背疼痛，腰以上风寒湿痹，最宜选用的药物是","o":["荆芥","香薷","辛夷","紫苏叶","羌活"],"a":4,"e":"羌活辛温，解表散寒、祛风除湿、止痛，善治腰以上风寒湿痹及肩背疼痛，其性上行而不下行。"},{"q":"不具有沉降作用的药物是","o":["大黄","芒硝","山楂","栀子","羌活"],"a":4,"e":"羌活辛温升浮，功能发散风寒、升举清阳，属升浮之品；大黄、芒硝、山楂、栀子均主沉降。"},{"q":"中药学中广义的“毒”不包括","o":["药物的总称","药物的偏性","药物剂量的大小","药物作用的强弱","药物的毒副作用"],"a":2,"e":"广义之毒包括药物的总称、药物的偏性以及毒副作用、作用强弱；剂量大小属用法用量范畴，不属“毒”的含义。"},{"q":"杜仲常用于治疗的病证有","o":["跌打损伤、痰热阻滞","肝阳上亢、视物昏花","肝肾亏虚、妊娠胎漏","肾不纳气、湿热淋证","肺热咳喘、妊娠胎漏"],"a":2,"e":"杜仲补肝肾、强筋骨、安胎，为治肝肾亏虚之腰膝酸痛、筋骨无力及妊娠胎漏下血之要药。"},{"q":"黄芪通过补气作用不能达到的间接功效是","o":["生血","行血","摄血","生津","壮阳"],"a":4,"e":"黄芪补气能生血、行血、摄血、生津、托毒，壮阳非补气所派生之功，需赖补阳药方能实现。"},{"q":"既能化瘀止血，又能凉血止血的药物是","o":["生地","三七","茜草","蒲黄","大黄"],"a":2,"e":"茜草苦寒，凉血化瘀止血、通经，既化瘀止血又凉血止血，宜于血热夹瘀之出血证。，炒炭后止血力更著。"},{"q":"与佩兰功效相似而力稍强的药物是","o":["苍术","厚朴","砂仁","广藿香","白豆蔻"],"a":3,"e":"广藿香与佩兰同能芳香化湿、发表解暑，而藿香化湿和中之力较强，故为功效相似而力稍强。"},{"q":"茵陈是利胆退黄常用药，其主治病证不包括","o":["湿热黄疸","寒湿黄疸","暑湿证","蓄血发黄","湿温证"],"a":3,"e":"茵陈清利湿热、利胆退黄，治湿热黄疸、寒湿阴黄及湿温、暑湿；蓄血发黄系瘀血所致，非其所主。"},{"q":"既能养心安神，又能润肠通便的药是","o":["杏仁","桃仁","柏子仁","酸枣仁","郁李仁"],"a":2,"e":"柏子仁甘平，养心安神、润肠通便，宜于心血不足之心悸失眠兼肠燥便秘者。，与酸枣仁养心安神相近。"},{"q":"平性药的临床意义在于","o":["多可用做方中君药","可更好纠正寒热之偏","毒副作用相对较小","功擅调和气血","补益作用强"],"a":2,"e":"平性药寒热偏性不明显，作用和缓，故毒副作用相对较小，临床应用较为安全，但仍属四气范畴。"},{"q":"具有渗湿利水作用的药味是","o":["涩味","辛味","酸味","咸味","淡味"],"a":4,"e":"淡能渗、能利，故淡味药具有渗湿利水作用，如茯苓、猪苓、薏苡仁，多用于水肿、小便不利。"},{"q":"善治肺胃出血的药物是","o":["小蓟","白及","槐花","茜草","三七"],"a":1,"e":"白及苦甘涩微寒，收敛止血、消肿生肌，善治肺胃出血之咯血、吐血，为收敛止血要药。，研末冲服亦可。"},{"q":"牡丹皮除清热凉血外，又能","o":["解毒透疹","活血化瘀","润肠通便","利尿通淋","燥湿止痒"],"a":1,"e":"牡丹皮苦辛微寒，清热凉血、活血化瘀，治温毒发斑、血热吐衄及瘀滞经闭、跌打伤痛。，炒炭则长于止血。"},{"q":"青光眼患者禁用的药物是","o":["夏枯草","密蒙花","青葙子","决明子","鸭跖草"],"a":2,"e":"青葙子清肝泻火、明目退翳，且有扩瞳作用，青光眼患者用之可致眼压升高，故禁用。，瞳孔散大者亦忌用。"},{"q":"不属于熟地黄功效的是","o":["补血","滋阴","益精","填髓","益气"],"a":4,"e":"熟地黄补血滋阴、益精填髓，为补血要药，无益气之功；益气系人参、黄芪等补气药所主。"},{"q":"具有补气安神、止咳平喘功效的安神药是","o":["朱砂","远志","灵芝","首乌藤","酸枣仁"],"a":2,"e":"灵芝甘平，补气安神、止咳平喘，兼具补虚与安神之功，为虚烦不眠兼咳喘者常用之安神药。"},{"q":"治疗风痰眩晕，中风，癫痫，破伤风，应首选的药物是","o":["半夏","瓜蒌","白前","天南星","旋覆花"],"a":3,"e":"天南星苦辛温有毒，燥湿化痰、祛风止痉，善治风痰眩晕、中风痰壅、癫痫及破伤风。，生用力峻，胆南星则性凉。"},{"q":"被称为治湿热黄疸之良品，石淋要药的是","o":["茵陈","车前子","虎杖","金钱草","海金沙"],"a":3,"e":"金钱草利湿退黄、利尿通淋、解毒消肿，为治湿热黄疸之良品、石淋之要药。，湿热淋证与黄疸多用之。"},{"q":"三棱与莪术的共同主治证是","o":["癥瘕积聚","恶疮癌肿","风湿顽痹","赤白痢疾","跌打损伤"],"a":0,"e":"三棱、莪术均破血行气、消积止痛，共同主治气滞血瘀之癥瘕积聚、心腹瘀痛。，醋制后止痛之力增强。"},{"q":"既能活血通经，又能凉血止血的药物是","o":["蒲黄","三七","茜草","侧柏叶","白茅根"],"a":2,"e":"茜草苦寒，凉血化瘀止血、通经，既活血通经又凉血止血，为妇科血热夹瘀出血之常用药。"},{"q":"既能祛风散寒，又能除湿止痛的药物是","o":["香薷","荆芥","藁本","葱白","紫苏叶"],"a":2,"e":"藁本辛温，祛风散寒、除湿止痛，善治风寒感冒、巅顶头痛及风寒湿痹、肢节疼痛。，其性上行直达巅顶。"},{"q":"清热燥湿药的性味是","o":["辛寒","苦寒","甘寒","咸寒","淡寒"],"a":1,"e":"清热燥湿药性味多苦寒，苦以燥湿、寒以清热，如黄连、黄芩、黄柏，主治湿热诸证。，为治湿热证之主药。"},{"q":"治风湿痹痛，带下过多，最宜选用的药物是","o":["防风","苍耳子","羌活","桂枝","白芷"],"a":4,"e":"白芷辛温，解表散寒、祛风止痛、燥湿止带、消肿排脓，故治风湿痹痛及寒湿带下过多。，亦治鼻渊前额头痛。"},{"q":"治疗烦躁胸闷，虚烦不眠，首选的药物是","o":["葛根","升麻","牛蒡子","淡豆豉","柴胡"],"a":3,"e":"淡豆豉解表除烦、宣发郁热，配栀子成栀子豉汤，治热郁胸中之烦躁胸闷、虚烦不眠。，其力平和而不伤正。"},{"q":"诃子涩肠止泻，可用于治疗","o":["脾虚久泻","热毒血痢","湿热泄泻","湿热痢疾","暑湿泄泻"],"a":0,"e":"诃子苦酸涩平，涩肠止泻、敛肺止咳、利咽开音，其收涩之性宜于脾虚久泻久痢，湿热泄痢初起忌用。"},{"q":"治疗胃寒呕吐，呃逆之要药是","o":["丁香","肉桂","苍术","藿香","花椒"],"a":0,"e":"丁香辛温，温中降逆、散寒止痛、温肾助阳，为治胃寒呕吐、呃逆之要药。，与郁金相畏须留意。"},{"q":"治水饮与热邪结聚所致的结胸证，选大黄、芒硝配","o":["甘遂","京大戟","芫花","牵牛子","商陆"],"a":0,"e":"大黄、芒硝配甘遂即大陷胸汤，泻热逐水，治水饮与热邪结聚之结胸证，甘遂善逐胸胁水饮。"},{"q":"炒炭的主要目的是","o":["止泻","止血","止痛","止呕","止痒"],"a":1,"e":"炒炭使药物部分炭化，增强收敛止血之力，故炒炭的主要目的在于止血，多用于出血证。，如地榆炭、侧柏炭之类。"},{"q":"老年人习惯性便秘，可小量泡服","o":["大黄","芒硝","番泻叶","芦荟","车前子"],"a":2,"e":"番泻叶苦寒，泻热行滞、通便，小量泡服即能缓下，宜于老年人习惯性便秘及术后通便。，不宜久煎，以免减效。"},{"q":"解表生用，止咳平喘宜蜜炙用的药物是","o":["麻黄","桂枝","紫苏叶","生姜","香薷"],"a":0,"e":"麻黄生用发汗解表力强，蜜炙后辛散之性减弱而润肺止咳平喘，故止咳平喘宜蜜炙用。，解表与止咳分用两法。"},{"q":"矮地茶的主治证不包括","o":["咳喘痰多","湿热黄疸","经闭瘀阻","跌打损伤","带下白浊"],"a":4,"e":"矮地茶化痰止咳、利湿、活血，治咳喘痰多、湿热黄疸、经闭瘀阻及跌打损伤；带下白浊非其主治。"},{"q":"能温中止痛，又能杀虫止痒的药物是","o":["生姜","干姜","丁香","花椒","小茴香"],"a":3,"e":"花椒辛温，温中止痛、杀虫止痒，内治脘腹冷痛、寒湿泄泻，外治湿疹瘙痒、阴痒。，炒用则辛散之性稍减。"},{"q":"妊娠慎用的药物不包括的是","o":["枳实","肉桂","附子","红花","莪术"],"a":4,"e":"莪术破血行气、消积止痛，其力峻猛，属妊娠禁用之品，不在妊娠慎用之列。，与妊娠慎用药性不同。"},{"q":"不具有解毒功效的药物是","o":["山药","甘草","生姜","蜂蜜","白扁豆"],"a":0,"e":"山药补脾养胃、生津益肺、补肾涩精，无解毒之功；甘草、生姜、蜂蜜、白扁豆均能解药毒或食毒。"},{"q":"清热凉血药主归","o":["肺、肝经","肝、肾经","心、脾经","心、肝经","肺、肾经"],"a":3,"e":"清热凉血药多入心、肝经，以清解营血分热邪，如生地黄、玄参、牡丹皮、赤芍。，如水牛角、紫草亦属此类。"},{"q":"治血热妄行之吐血、衄血、尿血，宜选用的药物是","o":["夏枯草","决明子","栀子","天花粉","芦根"],"a":2,"e":"栀子苦寒，泻火除烦、清热利湿、凉血解毒，治血热妄行之吐血、衄血、尿血。，炒焦偏于止血，生用偏于泻火。"},{"q":"不属道地药材的是","o":["河南的地黄","江苏的薄荷","云南的玄参","山东的阿胶","东北的五味子"],"a":2,"e":"玄参以浙江为道地产区，属“浙八味”；云南的道地药材为三七、木香、重楼，故云南的玄参不属道地药材。"},{"q":"消食药多属渐消缓散之品，适用于病情较缓，积滞不甚者；若食积难消，腹痛便秘，病情较为急重者，宜配伍","o":["理气药","温里药","清热药","攻下药","化湿药"],"a":3,"e":"食积难消、腹痛便秘而病情急重者，当配伍攻下药通腑泻实，使积滞从下而去，取“通则不痛”之意。"},{"q":"可用以反映药物在补、泄、散、敛等方面作用特征的是","o":["四气","五味","归经","升降浮沉","毒性"],"a":1,"e":"五味反映药物补、泄、散、敛等作用特征，辛散、酸收、甘补、苦泄、咸软，为药性理论的核心内容之一。"},{"q":"薄荷与牛蒡子均具有的功效是","o":["透疹","清肝","升阳","解毒","宣肺"],"a":0,"e":"薄荷疏散风热、利咽透疹、疏肝行气；牛蒡子疏散风热、宣肺透疹、解毒利咽；透疹为二者共有之功。"},{"q":"川楝子配延胡索增强的作用是","o":["行气调中止痛","行气活血止痛","行气通阳散结","行气燥湿化痰","行气解毒消肿"],"a":1,"e":"川楝子配延胡索即金铃子散，川楝子行气、延胡索活血，合用行气活血止痛，治肝郁气滞血瘀之胸腹诸痛。"},{"q":"具有健脾化湿、和中消暑功效，可用于治疗夏月暑湿伤中的药物是","o":["山药","黄芪","党参","藿香","白扁豆"],"a":4,"e":"白扁豆甘微温，健脾化湿、和中消暑，为治夏月暑湿伤中、吐泻腹胀之常用药。，炒用则健脾止泻力增。"},{"q":"覆盆子与鸡内金的共同功效是","o":["消食化积","养肝明目","化石消坚","涩肠止泻","固精缩尿"],"a":4,"e":"覆盆子益肾固精缩尿，鸡内金涩精止遗、通淋化石，固精缩尿为二者共有功效。，二药均属收涩之品。"},{"q":"金银花用治热毒所致的咽喉肿痛，主要是因其能","o":["清热解毒","清心利尿","凉血止痢","清解暑热","消痈散结"],"a":0,"e":"金银花甘寒，清热解毒、疏散风热，热毒所致咽喉肿痛正取其清热解毒之力，方如银翘散。"},{"q":"鹿茸的用法正确是","o":["先煎久煎","研末冲服","后下泡服","煎汤代水","单煎另煎"],"a":1,"e":"鹿茸为血肉有情之品，贵重且不耐久煎，宜研末冲服或入丸散，每次1～2g，不入汤剂先煎。"},{"q":"马兜铃与枇杷叶共有的功效是","o":["止咳平喘，清胃止呕","清肺化痰，清胃止呕","清肺化痰，利水消肿","清肺化痰，止咳平喘","清肺化痰，清肠消痔"],"a":3,"e":"马兜铃清肺化痰、止咳平喘、清肠消痔，枇杷叶清肺止咳、降逆止呕，二者共有清肺化痰、止咳平喘之功。"},{"q":"既能散寒解表，又能宣通鼻窍的药物是","o":["桂枝","紫苏叶","薄荷","羌活","辛夷"],"a":4,"e":"辛夷辛温，散风寒、通鼻窍，为治鼻塞不通、鼻渊头痛之要药，内服外用皆可。，阴虚火旺者慎用。"},{"q":"下列药物除哪项外，均善于滋补肝肾之阴","o":["枸杞子","女贞子","墨旱莲","北沙参","黑芝麻"],"a":3,"e":"北沙参养阴清肺、益胃生津，作用在肺胃而不在肝肾；枸杞子、女贞子、墨旱莲、黑芝麻均滋补肝肾之阴。"},{"q":"附子与肉桂共同的功效是","o":["补火助阳，降逆止呕","补火助阳，散寒止痛","补火助阳，回阳救逆","补火助阳，理气止痛","补火助阳，杀虫止痒"],"a":1,"e":"附子、肉桂均能补火助阳、散寒止痛，为温里祛寒之要药；附子长于回阳救逆，肉桂长于引火归原。"},{"q":"尤长于清中焦湿热的药物是","o":["黄芩","黄连","黄柏","龙胆","苦参"],"a":1,"e":"黄连大苦大寒，尤善清中焦脾胃湿热，为治湿热泻痢、呕吐吞酸之要药；黄芩偏上焦，黄柏偏下焦。"},{"q":"擅治中焦虚寒性吐血、便血的是","o":["生姜","艾叶","炮姜","地榆","白茅根"],"a":2,"e":"炮姜苦涩温，温经止血、温中止痛，善治中焦虚寒、脾不统血之吐血、便血，与生姜发散之性不同。"},{"q":"药性苦燥寒清，治黄疸无论湿热阳黄、寒湿阴黄均为要药的是","o":["金钱草","茵陈","虎杖","车前子","滑石"],"a":1,"e":"茵陈苦燥寒清，清利湿热、利胆退黄，湿热阳黄与寒湿阴黄均可配伍应用，为治黄疸之要药。"},{"q":"既能杀虫，又有消积行气利水作用的药物是","o":["雷丸","榧子","槟榔","使君子","苦楝皮"],"a":2,"e":"槟榔苦辛温，杀虫消积、行气、利水，故除杀虫外兼具消积行气利水之功，为驱绦虫常用药。"},{"q":"既归心、肝经，能清热凉血，又归肾经，能清透阴分伏热的药物是","o":["水牛角","赤芍","牡丹皮","玄参","紫草"],"a":2,"e":"牡丹皮归心、肝、肾经，清热凉血、活血化瘀，又能清透阴分伏热，治夜热早凉、无汗骨蒸。"},{"q":"桑白皮的主治证不包括","o":["肺热咳喘","胃热呕逆","水肿尿少","咳血，衄血","肝阳上亢，头晕目眩"],"a":1,"e":"桑白皮泻肺平喘、利水消肿，治肺热咳喘、水肿尿少、咳血衄血；胃热呕逆非其所主，为枇杷叶、竹茹之能。"},{"q":"胆南星的功效是","o":["燥湿化痰，降逆止呕","燥湿化痰，祛风止痉","清热化痰，息风定惊","清热化痰，除烦止呕","清热化痰，利气宽胸"],"a":2,"e":"胆南星苦凉，清热化痰、息风定惊，治痰热咳嗽、惊风抽搐、癫痫，与天南星温燥之性迥异。"},{"q":"具有化痰止咳功效的药物是","o":["槐花","白及","白茅根","仙鹤草","侧柏叶"],"a":4,"e":"侧柏叶苦涩寒，凉血止血、化痰止咳、生发乌发，为兼具化痰止咳之功的止血药。，血热出血兼咳嗽者宜之。"},{"q":"具平肝息风之功，常与钩藤相须为用，治疗肝风内动、肝阳上亢之证的药是","o":["菊花","天麻","蜈蚣","全蝎","羚羊角"],"a":1,"e":"天麻甘平，平肝息风、平抑肝阳，常与钩藤相须为用，治肝风内动之抽搐及肝阳上亢之眩晕头痛。"},{"q":"能温胃止呕，散寒止痛的药物是","o":["香薷","藿香","佩兰","苍术","高良姜"],"a":4,"e":"高良姜辛热，温胃止呕、散寒止痛，为治胃寒冷痛、呕吐嗳气之常用药。，与干姜温中散寒之功相近。"},{"q":"山茱萸的主治病证不包括","o":["阳痿","胃痛泛酸","遗精滑精","遗尿尿频","腰酸耳鸣"],"a":1,"e":"山茱萸补益肝肾、收涩固脱，治腰膝酸软、头晕耳鸣、遗精遗尿、崩漏；胃痛泛酸非其所主。"},{"q":"桃仁除活血祛瘀外，还能","o":["生肌、敛疮","润肠、止咳","通经、破气","补血、舒筋","利水、杀虫"],"a":1,"e":"桃仁活血祛瘀、润肠通便、止咳平喘，故除活血祛瘀外还能润肠、止咳，治肠燥便秘与咳嗽气喘。"},{"q":"均有涩肠止泻之功的药组是","o":["乌梅、肉豆蔻","乌梅、覆盆子","五味子、覆盆子","五味子、桑螵蛸","桑螵蛸、肉豆蔻"],"a":0,"e":"乌梅涩肠止泻、敛肺止咳、生津安蛔，肉豆蔻涩肠止泻、温中行气，二者均能涩肠止泻。，湿热泻痢初起者均忌用。"},{"q":"利水渗湿作用较强，长久使用时，尤其应注意观察水、电解质平衡是否失调的药物是","o":["茯苓","薏苡仁","猪苓","冬瓜皮","香加皮"],"a":2,"e":"猪苓淡渗利水之力较茯苓、薏苡仁为强，久用易耗伤阴液，故须注意观察水与电解质平衡是否失调。"},{"q":"白芍具有的功效是","o":["补益精血，润肠通便","补血养阴，润肺止咳","平抑肝阳，柔肝止痛","养阴润肺，益胃生津","滋阴潜阳，清心除烦"],"a":2,"e":"白芍苦酸微寒，养血调经、敛阴止汗、平抑肝阳、柔肝止痛，为柔肝缓急止痛之要药。，与赤芍凉血活血之功有别。"},{"q":"能治疗热痢，脾虚泄泻的药物是","o":["薄荷","牛蒡子","葛根","升麻","柴胡"],"a":2,"e":"葛根解肌退热、生津止渴、升阳止泻，既能清热治热痢，又能升发清阳治脾虚泄泻。，煨用则专于止泻。"},{"q":"枇杷叶的功效是","o":["止咳平喘，润肠通便","止咳平喘，清肠消痔","止咳平喘，解痉止痛","润肺下气，消痰止咳","清肺止咳，降逆止呕"],"a":4,"e":"枇杷叶苦微寒，清肺止咳、降逆止呕，治肺热咳嗽痰稠及胃热呕吐、呃逆。，蜜炙则润肺之力增强。"},{"q":"中药归经的方法","o":["五色归经法","五味归经法","脏腑经络归经法","质地归经法","形状归经法"],"a":3,"e":"官方答案为【质地归经法】，但依据教材，正确答案为【脏腑经络归经法】。归经以脏腑经络理论为基础，按药物所治具体病证确定其归属，不以质地、形状或五色划分。"}];
